local _, ns = ...

ns:RegisterLocale("deDE", function() return {
    ["Seal Twist"] = "Seal Twist",
    ["Twist"] = "Twist",
    ["Hold seal"] = "Halte-Siegel",
    ["Seals"] = "Siegel",
    ["Seal you hold"] = "Siegel, das du hältst",
    ["Seal you twist in"] = "Siegel, in das du twistest",
    ["Timing"] = "Zeitpunkt",
    ["Twist window (seconds)"] = "Twist-Fenster (Sekunden)",
    ["How far before the swing the second seal has to land. 0.40 is the usual figure; raise it if your latency makes you miss the window."] = "Wie weit vor dem Schlag das zweite Siegel landen muss. 0,40 ist der übliche Wert; erhöhe ihn, wenn deine Latenz dich das Fenster verpassen lässt.",
    ["Suggest Crusader Strike"] = "Kreuzfahrerstoß vorschlagen",
    ["Prompts Crusader Strike when it is ready and there is room for it plus the Command cast before the window opens."] = "Schlägt den Kreuzfahrerstoß vor, wenn er bereit ist und davor noch Platz für ihn und den Befehls-Wirkvorgang bleibt.",
    ["Sound when the window opens"] = "Ton, wenn das Fenster aufgeht",
    ["Enable seal twist helper"] = "Seal-Twist-Hilfe aktivieren",
    ["Show swing bar"] = "Schwungleiste zeigen",
    ["Show next action"] = "Nächste Aktion zeigen",
    ["Show numbers"] = "Zahlen zeigen",
    ["(no seals learned)"] = "(keine Siegel gelernt)",
    ["%.2fs left  -  swing %.2fs  -  GCD %.2fs"] = "%.2fs übrig  -  Schlag %.2fs  -  GCD %.2fs",
    ["|cffffffffSEAL TWIST|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffffSEAL TWIST|r\n|cffaaaaaaZiehen oder Pfeiltasten|r",
    ["Seal Twist position: x=%.0f, y=%.0f"] = "Seal-Twist-Position: x=%.0f, y=%.0f",
    ["Seal Twist mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Test' again to finish."] = "Seal-Twist-Rahmen aktiv. |cff9b6cffZieh den lila Kasten|r oder nutze die |cff9b6cffPfeiltasten|r (UMSCHALT = 5px). Klick erneut auf „Entsperren / Test“, um fertig zu werden.",
    ["Seal Twist mover disabled."] = "Seal-Twist-Rahmen deaktiviert.",
    ["Practice"] = "Übung",
    ["|cffaaaaaaA swing clock that runs on its own, with no target and nothing spent. Press your bound keys against it and every swing is graded: the twist landed, it was too early, or nothing was attempted. The seal model is the real one -- a replaced seal keeps resolving for 0.4 seconds -- so the timing you learn here is the timing that works.|r"] = "|cffaaaaaaEine Schlaguhr, die von allein läuft, ohne Ziel und ohne Kosten. Drück deine belegten Tasten dagegen, und jeder Schlag wird bewertet: der Twist ist gelandet, er kam zu früh, oder es wurde keiner versucht. Das Siegelmodell ist das echte -- ein ersetztes Siegel wirkt noch 0,4 Sekunden nach -- der Zeitpunkt, den du hier lernst, ist also der, der funktioniert.|r",
    ["Start / stop practice"] = "Übung starten / beenden",
    ["Stop practice"] = "Übung beenden",
    ["Simulated weapon speed"] = "Simuliertes Waffentempo",
    ["0 uses whatever you have equipped. Any other value drills a speed you do not own yet, which is how you find out that the weapon you are saving for needs a different sequence."] = "0 nimmt das, was du angelegt hast. Jeder andere Wert übt ein Tempo, das du noch nicht besitzt -- so findest du heraus, dass die Waffe, auf die du sparst, eine andere Abfolge braucht.",
    ["Spell queue window (ms)"] = "Zauber-Warteschlangenfenster (ms)",
    ["A key pressed this far before the global cooldown ends is held and fires the moment it does, exactly as the client does it. Practising without it teaches a rhythm the game never asks for."] = "Eine Taste, die so weit vor dem Ende der globalen Abklingzeit gedrückt wird, wird gehalten und löst genau in dem Moment aus, so wie es das Spiel macht. Ohne das übt man einen Rhythmus, den das Spiel nie verlangt.",
    ["Result text size"] = "Größe des Ergebnistexts",
    ["Result text duration (seconds)"] = "Dauer des Ergebnistexts (Sekunden)",
    ["Landed colour"] = "Farbe für gelandet",
    ["Missed colour"] = "Farbe für verfehlt",
    ["Show the fight timeline"] = "Kampf-Zeitleiste zeigen",
    ["Every swing and every cast on one strip against a ruler. The ruler is the point: without it you can see that two swings were close together but not how close, which is the only number practice is about."] = "Jeder Schlag und jeder Zauber auf einem Streifen gegen ein Lineal. Das Lineal ist der Punkt: ohne es siehst du, dass zwei Schläge nah beieinander lagen, aber nicht wie nah -- und das ist die einzige Zahl, um die es beim Üben geht.",
    ["Timeline width"] = "Breite der Zeitleiste",
    ["Timeline pixels per second"] = "Pixel pro Sekunde der Zeitleiste",
    ["TWIST"] = "TWIST",
    ["MISS"] = "DANEBEN",
    ["TOO EARLY"] = "ZU FRÜH",
    ["speed %.2fs  -  GCD %.2fs  -  %d of %d"] = "Tempo %.2fs  -  GCD %.2fs  -  %d von %d",
    ["|cffffffffPRACTICE|r"] = "|cffffffffÜBUNG|r",
    ["|cffffffffRESULT|r"] = "|cffffffffERGEBNIS|r",
    ["|cffffffffTIMELINE|r"] = "|cffffffffZEITLEISTE|r",
    ["|cffffcc33Twist practice|r"] = "|cffffcc33Twist-Übung|r",
    ["Practice needs two seals: pick them under Seals first."] = "Die Übung braucht zwei Siegel: wähle sie zuerst unter Siegel.",
    ["Practice mode on. Press your bound keys; the swing runs on its own."] = "Übungsmodus an. Drück deine belegten Tasten, der Schlag läuft von allein.",
    ["Practice mode off. %d of %d swings carried the twist."] = "Übungsmodus aus. %d von %d Schlägen trugen den Twist.",
    ["Bloodlust"] = "Kampfrausch",
    ["Haste potion"] = "Tempotrank",
    ["Abacus"] = "Abakus",
    ["Time warp"] = "Zeitverzerrer",
    ["Crusader Strike"] = "Kreuzfahrerstoß",
    ["Judgement"] = "Richturteil",
    ["Cast the held seal"] = "Halte-Siegel wirken",
    ["Cast the twist seal"] = "Twist-Siegel wirken",
    ["Filler"] = "Füller",
    ["Start / stop attack"] = "Angriff starten / stoppen",
    ["wait"] = "warten",
    ["Next action"] = "Nächste Aktion",
    ["|cffffffffNEXT ACTION|r"] = "|cffffffffNÄCHSTE AKTION|r",
    ["Next action mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Test' again to finish."] = "Rahmen der nächsten Aktion aktiv. |cff9b6cffZieh den lila Kasten|r oder nutze die |cff9b6cffPfeiltasten|r (UMSCHALT = 5px). Klick erneut auf „Entsperren / Test“, um fertig zu werden.",
    ["Next action mover disabled."] = "Rahmen der nächsten Aktion deaktiviert.",
    ["|cffaaaaaaAn icon of the one thing to press, wherever you want it. It answers the same question as the line under the bar -- the three switches below feed both, so the word and the picture can never disagree.|r"] = "|cffaaaaaaEin Symbol für das eine, was du drücken sollst, an einer Stelle deiner Wahl. Es beantwortet dieselbe Frage wie die Zeile unter der Leiste -- die drei Schalter darunter speisen beide, damit Wort und Bild nie widersprechen.|r",
    ["Show the next action guide"] = "Anzeige der nächsten Aktion zeigen",
    ["When to show it"] = "Wann sie erscheint",
    ["Show a hold instead of nothing"] = "Warten zeigen statt nichts",
    ["While the right move is to press nothing on purpose -- the twist is coming and anything else would cost it -- the guide keeps showing the seal, drained and outlined. An empty box says the same thing much less clearly."] = "Solange es richtig ist, absichtlich nichts zu drücken -- der Twist kommt und alles andere würde ihn kosten -- zeigt die Anzeige weiter das Siegel, ausgeblasst und umrandet. Ein leerer Kasten sagt dasselbe viel undeutlicher.",
    ["Suggest Judgement"] = "Richturteil vorschlagen",
    ["Judging consumes the seal, so it is only ever offered with room to re-seal afterwards. Off by default: a mistimed judgement costs more than no suggestion at all."] = "Ein Richturteil verbraucht das Siegel, es wird also nur mit Platz zum Nachsiegeln vorgeschlagen. Standardmäßig aus: ein falsch gesetztes Richturteil kostet mehr als gar kein Vorschlag.",
    ["Suggest a filler"] = "Fülleraktion vorschlagen",
    ["Consecration, or Exorcism where the target can take it, in the stretch of the swing that is free for it. Exorcism is offered by asking the client whether the spell can be aimed at your target, which is right in every language."] = "Weihe, oder Exorzismus wo das Ziel ihn verträgt, in dem Abschnitt des Schlags, der dafür frei ist. Ob Exorzismus angeboten wird, entscheidet die Frage an das Spiel, ob der Zauber überhaupt auf dein Ziel gerichtet werden kann -- das stimmt in jeder Sprache.",
    ["Consecration mana floor (%)"] = "Mana-Untergrenze für Weihe (%)",
    ["Below this share of your mana the filler is not worth it."] = "Unter diesem Anteil deines Manas lohnt sich der Füller nicht.",
    ["Exorcism mana floor (%)"] = "Mana-Untergrenze für Exorzismus (%)",
    ["Longest Crusader Strike delay (ms)"] = "Längster Kreuzfahrerstoß-Verzug (ms)",
    ["Once leaving the strike any longer than this would waste it, it stops being a suggestion and becomes the answer. Measured against the earliest moment you could actually cast it, not against now."] = "Sobald ein längeres Warten den Stoß verschwenden würde, ist er kein Vorschlag mehr, sondern die Antwort. Gemessen am frühesten Moment, in dem du ihn wirklich wirken könntest, nicht am Jetzt.",
    ["Twist!"] = "Twist!",
    ["|cffffffffTWIST TEXT|r"] = "|cffffffffTWIST-TEXT|r",
    ["Twist text mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Test' again to finish."] = "Twist-Text-Rahmen aktiv. |cff9b6cffZieh den lila Kasten|r oder nutze die |cff9b6cffPfeiltasten|r (UMSCHALT = 5px). Klick erneut auf „Entsperren / Test“, um fertig zu werden.",
    ["Twist text mover disabled."] = "Twist-Text-Rahmen deaktiviert.",
    ["Twist landed"] = "Twist gelandet",
    ["|cffaaaaaaAll three cues below wait for PROOF, not for a prediction. A swing has to land with both seals up, and the held seal's own damage has to follow it in the combat log. Nothing fires without that second line -- a confirmation that is right most of the time is one you cannot practise against.|r"] = "|cffaaaaaaAlle drei Rückmeldungen unten warten auf einen BEWEIS, nicht auf eine Vorhersage. Ein Schlag muss mit beiden Siegeln landen, und der Schaden des gehaltenen Siegels muss ihm im Kampflog folgen. Ohne diese zweite Zeile passiert nichts -- eine Bestätigung, die meistens stimmt, ist eine, gegen die man nicht üben kann.|r",
    ["Sound channel"] = "Tonkanal",
    ["Master"] = "Gesamt",
    ["Sound effects"] = "Soundeffekte",
    ["Master ignores the sound effects slider, which is what a confirmation wants: it is feedback about the fight rather than part of it."] = "Gesamt ignoriert den Regler für Soundeffekte, und genau das will eine Bestätigung: sie ist eine Rückmeldung über den Kampf, nicht ein Teil davon.",
    ["The sniper and rifle cracks are bundled; the rest are the client's own cues. Below them stand any sounds other addons have registered as shared media."] = "Der Scharfschützen- und der Gewehrknall sind mitgeliefert, der Rest sind Töne des Spiels. Darunter stehen alle Töne, die andere Addons als geteilte Medien angemeldet haben.",
    ["Sniper"] = "Scharfschütze",
    ["Level up"] = "Stufenaufstieg",
    ["Quest complete"] = "Quest abgeschlossen",
    ["Bonus objective"] = "Bonusziel",
    ["Map ping"] = "Kartenmarkierung",
    ["Glow on the bar when the twist lands"] = "Leuchten auf der Leiste, wenn der Twist landet",
    ["Glow style"] = "Leuchtart",
    ["Pixel border"] = "Pixelrahmen",
    ["Autocast ring"] = "Autozauber-Ring",
    ["Pixel border traces the bar's own outline at any width. Autocast pins the client's own ring to the four corners, so it stays a ring however wide the bar gets."] = "Der Pixelrahmen zeichnet den Umriss der Leiste bei jeder Breite nach. Autozauber heftet den Ring des Spiels an die vier Ecken, damit er ein Ring bleibt, egal wie breit die Leiste wird.",
    ["Glow colour"] = "Leuchtfarbe",
    ["Glow duration (seconds)"] = "Leuchtdauer (Sekunden)",
    ["Text when the twist lands"] = "Text, wenn der Twist landet",
    ["A line somewhere on screen, with its own position. Useful where the bar is in the corner of the eye and the confirmation should be in the middle of it."] = "Eine Zeile irgendwo auf dem Bildschirm, mit eigener Position. Nützlich, wenn die Leiste im Augenwinkel liegt und die Bestätigung mitten im Blick stehen soll.",
    ["Text font"] = "Textschriftart",
    ["Text outline"] = "Textumrandung",
    ["Text colour"] = "Textfarbe",
    ["Text duration (seconds)"] = "Textdauer (Sekunden)",
    ["|cffffffffSEALS|r"] = "|cffffffffSIEGEL|r",
    ["Seal indicator mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Test' again to finish."] = "Siegelanzeigen-Rahmen aktiv. |cff9b6cffZieh den lila Kasten|r oder nutze die |cff9b6cffPfeiltasten|r (UMSCHALT = 5px). Klick erneut auf „Entsperren / Test“, um fertig zu werden.",
    ["Seal indicator mover disabled."] = "Siegelanzeigen-Rahmen deaktiviert.",
    ["Match the bar height"] = "Der Leistenhöhe folgen",
    ["Sizes the icons to the bar instead of to their own setting, so the pair keeps lining up with it when the bar height changes."] = "Passt die Symbole der Leiste an statt ihrer eigenen Einstellung, damit das Paar bündig bleibt, wenn sich die Leistenhöhe ändert.",
    ["Ignored while the icons match the bar height."] = "Wird ignoriert, solange die Symbole der Leistenhöhe folgen.",
    ["Seal icon spacing"] = "Abstand der Siegelsymbole",
    ["Centre the icons"] = "Symbole zentrieren",
    ["Keeps the midpoint of the pair still when the second seal appears or falls off. Left-aligned keeps the first icon still instead, which is what an attached pair wants -- that edge is the bar."] = "Hält die Mitte des Paares still, wenn das zweite Siegel auftaucht oder abfällt. Linksbündig hält stattdessen das erste Symbol still, was ein angehängtes Paar will -- diese Kante ist die Leiste.",
    ["Show the cooldown sweep"] = "Abklingzeit-Wischer zeigen",
    ["The client's own sweep across the icon. It says the same thing as the number under it, but it says it without being read."] = "Der Wischer des Spiels über dem Symbol. Er sagt dasselbe wie die Zahl darunter, aber er sagt es, ohne gelesen zu werden.",
    ["Seal timer colour"] = "Farbe der Siegelzeit",
    ["Detach from the bar"] = "Von der Leiste lösen",
    ["Gives the pair its own position anywhere on screen. They stay tied to the bar in every other way: when it is hidden, they are too."] = "Gibt dem Paar eine eigene Position irgendwo auf dem Bildschirm. In allem anderen bleiben sie an die Leiste gebunden: ist sie versteckt, sind sie es auch.",
    ["Twist lost"] = "Twist verloren",
    ["Swing ready -- restart your attack"] = "Schlag bereit -- starte deinen Angriff neu",
    ["(none available)"] = "(keine verfügbar)",
    ["Solid"] = "Einfarbig",
    ["Attack speed"] = "Angriffstempo",
    ["Swing timer"] = "Schlagzeit",
    ["Latency (ms)"] = "Latenz (ms)",
    ["Global cooldown left"] = "Globale Abklingzeit übrig",
    ["Nothing"] = "Nichts",
    ["Left readout"] = "Linke Anzeige",
    ["What the left end of the bar shows. Attack speed turns into the warning colour below two global cooldowns per swing -- under that the twist and the seal going back up no longer both fit, so wait for the cooldown before twisting."] = "Was das linke Ende der Leiste zeigt. Das Angriffstempo wechselt in die Warnfarbe, sobald weniger als zwei globale Abklingzeiten auf einen Schlag kommen -- darunter passen der Twist und das Siegel danach nicht mehr beide hinein, warte also die Abklingzeit ab.",
    ["Right readout"] = "Rechte Anzeige",
    ["Readout text size"] = "Textgröße der Anzeigen",
    ["The two numbers inside the bar. 0 follows the general text size."] = "Die beiden Zahlen in der Leiste. 0 folgt der allgemeinen Textgröße.",
    ["Global cooldown bar texture"] = "Textur der Abklingzeit-Leiste",
    ["Border"] = "Rand",
    ["Solid draws four flat edges in the colour below. Texture takes an edge file from shared media, which is what a border from another interface pack looks like."] = "Einfarbig zeichnet vier flache Kanten in der Farbe darunter. Textur nimmt eine Randdatei aus den geteilten Medien, also den Rand, den ein anderes Oberflächenpaket mitbringt.",
    ["Only used while the border is set to texture."] = "Wird nur benutzt, solange der Rand auf Textur steht.",
    ["Border width"] = "Randbreite",
    ["Marker texture"] = "Markentextur",
    ["Marker width"] = "Markenbreite",
    ["Font colour"] = "Schriftfarbe",
    ["Frame strata"] = "Rahmenebene",
    ["Which layer of the interface the helper sits in. Raise it to lift the bar over another addon that draws in the same place."] = "In welcher Ebene der Oberfläche die Hilfe sitzt. Erhöhe sie, um die Leiste über ein anderes Addon zu heben, das an derselben Stelle zeichnet.",
    ["Draw level"] = "Zeichenstufe",
    ["The order inside the chosen layer. Higher draws on top."] = "Die Reihenfolge innerhalb der gewählten Ebene. Höher zeichnet oben.",
    ["Colour the bar by"] = "Leiste einfärben nach",
    ["The zone the swing is in"] = "Die Zone, in der der Schlag steht",
    ["The seal you are carrying"] = "Das Siegel, das du trägst",
    ["Zones colour the fill by the stretch of the swing you are in, which is what this helper is built around. Seal colours it by what you are carrying, which is the faster read once the timing is in your fingers. Either way the special colours below outrank the choice."] = "Zonen färben die Füllung nach dem Abschnitt des Schlags, in dem du stehst -- darum herum ist diese Hilfe gebaut. Siegel färbt sie nach dem, was du trägst, was schneller zu lesen ist, sobald der Zeitpunkt in den Fingern sitzt. In beiden Fällen stechen die Sonderfarben darunter die Wahl.",
    ["Seal of Command"] = "Siegel des Befehls",
    ["Seal of Righteousness"] = "Siegel der Rechtschaffenheit",
    ["Seal of Blood / the Martyr"] = "Siegel des Blutes / des Märtyrers",
    ["Seal of Vengeance"] = "Siegel der Vergeltung",
    ["Seal of the Crusader"] = "Siegel des Kreuzfahrers",
    ["Seal of Justice"] = "Siegel der Gerechtigkeit",
    ["Seal of Light"] = "Siegel des Lichts",
    ["Seal of Wisdom"] = "Siegel der Weisheit",
    ["No twist possible"] = "Kein Twist möglich",
    ["The fill while this swing's twist is already gone, and the tail of the swing a cast can no longer reach."] = "Die Füllung, wenn der Twist dieses Schlags schon verloren ist, und das Ende des Schlags, das ein Wirkvorgang nicht mehr erreicht.",
    ["Warning"] = "Warnung",
    ["The warnings on the bar, and the attack speed once the weapon is too fast to twist with."] = "Die Warnungen auf der Leiste und das Angriffstempo, sobald die Waffe zum Twisten zu schnell ist.",
    ["Twisting"] = "Am Twisten",
    ["The fill while both seals are up: the twist is in and this swing carries it."] = "Die Füllung, solange beide Siegel liegen: der Twist ist drin und dieser Schlag trägt ihn.",
    ["Default"] = "Standard",
    ["The fill with no seal up and between swings."] = "Die Füllung ohne Siegel und zwischen den Schlägen.",
    ["Global cooldown"] = "Globale Abklingzeit",
    ["Deadzone"] = "Totzone",
    ["Twist window padding"] = "Polster für das Twist-Fenster",
    ["Pulls the twist window earlier so the cast still reaches the server inside it. Dynamic follows your calibrated latency; fixed is a number you choose yourself."] = "Zieht das Twist-Fenster nach vorn, damit der Wirkvorgang den Server noch darin erreicht. Dynamisch folgt deiner kalibrierten Latenz, fest ist ein Wert, den du selbst wählst.",
    ["Fixed twist padding (ms)"] = "Festes Twist-Polster (ms)",
    ["Only used while the padding mode is set to fixed."] = "Wird nur benutzt, solange der Polstermodus auf fest steht.",
    ["Dynamic (follows latency)"] = "Dynamisch (folgt der Latenz)",
    ["Fixed"] = "Fest",
    ["Latency"] = "Latenz",
    ["|cffaaaaaaThe round trip your client reports is not the delay a twist has to beat: the client adds a slice of its own, so the figure everything below works from is (world latency x multiplier) + offset. Raise the multiplier if you keep missing twists that looked in time.|r"] = "|cffaaaaaaDie Umlaufzeit, die dein Client meldet, ist nicht die Verzögerung, die ein Twist schlagen muss: der Client legt eine eigene Scheibe obendrauf. Der Wert, mit dem alles hier unten rechnet, ist (Weltlatenz x Multiplikator) + Versatz. Erhöhe den Multiplikator, wenn dir Twist durchgehen, die rechtzeitig aussahen.|r",
    ["Latency multiplier"] = "Latenz-Multiplikator",
    ["Latency offset (ms)"] = "Latenz-Versatz (ms)",
    ["Shade the deadzone"] = "Totzone einfärben",
    ["The tail of the swing a cast can no longer cross, shaded at the end of the bar. Its size follows your raw world latency rather than the calibrated figure, because this one is the wire and not a prediction. This switch only draws it -- the timing itself always accounts for it, so set the scale to 0 if you want no compensation at all."] = "Das Ende des Schlags, das ein Wirkvorgang nicht mehr überqueren kann, am Ende der Leiste eingefärbt. Die Größe folgt deiner rohen Weltlatenz statt dem kalibrierten Wert, denn das hier ist die Leitung und keine Vorhersage. Dieser Schalter zeichnet sie nur -- der Zeitpunkt rechnet sie immer mit ein, setz also die Skalierung auf 0, wenn du gar keinen Ausgleich willst.",
    ["Deadzone scale"] = "Totzonen-Skalierung",
    ["Multiplies your world latency. Raise it if you cannot twist just outside the shaded stretch, lower it if you still can inside it. 0 switches the compensation off entirely."] = "Multipliziert deine Weltlatenz. Erhöhe sie, wenn du direkt außerhalb des eingefärbten Stücks nicht twisten kannst, senke sie, wenn es darin noch geht. 0 schaltet den Ausgleich ganz ab.",
    ["Deadzone texture"] = "Totzonen-Textur",
    ["Deadzone transparency"] = "Totzonen-Transparenz",
    ["Global cooldown padding"] = "Polster für die globale Abklingzeit",
    ["Pulls the global cooldown boundary earlier by part of your latency, so a cast started right at the mark still clears the cooldown in time."] = "Zieht die Grenze der globalen Abklingzeit um einen Teil deiner Latenz nach vorn, damit ein Wirkvorgang direkt an der Marke die Abklingzeit noch rechtzeitig hinter sich lässt.",
    ["Fixed global cooldown padding (ms)"] = "Festes Polster für die globale Abklingzeit (ms)",
    ["Show the judgement mark"] = "Richturteil-Marke zeigen",
    ["A fourth line where Judgement comes off cooldown during this swing, so a judgement can be put in front of the twist instead of on top of it. Only drawn while a seal is up."] = "Eine vierte Linie dort, wo das Richturteil in diesem Schlag von der Abklingzeit kommt, damit ein Richturteil vor den Twist statt auf ihn passt. Wird nur gezeichnet, solange ein Siegel aktiv ist.",
    ["Show the global cooldown bar"] = "Leiste der globalen Abklingzeit zeigen",
    ["A strip along the bottom of the bar reaching to the moment the global cooldown frees up, so you can see how much of this swing is already spoken for."] = "Ein Streifen am unteren Rand der Leiste bis zu dem Moment, in dem die globale Abklingzeit frei wird -- so siehst du, wie viel von diesem Schlag schon vergeben ist.",
    ["Global cooldown bar height"] = "Höhe der Abklingzeit-Leiste",
    ["When to show the bar"] = "Wann die Leiste erscheint",
    ["Always keeps it on screen, which is the easier way to practise the timing on a dummy. Seal active shows it whenever you are carrying a seal, in or out of a fight."] = "Immer hält sie auf dem Bildschirm, was der einfachere Weg ist, den Zeitpunkt an einer Übungspuppe zu üben. Siegel aktiv zeigt sie, sobald du ein Siegel trägst, im Kampf wie außerhalb.",
    ["Seal active"] = "Siegel aktiv",
    ["In combat or seal active"] = "Im Kampf oder Siegel aktiv",
    ["Only with Two-Handed Weapon Specialization"] = "Nur mit Zweihandwaffen-Spezialisierung",
    ["Hides the helper unless you have a point in the talent. Twisting works without it, but the slow swing it is built around is what makes the whole habit pay."] = "Blendet die Hilfe aus, solange du keinen Punkt im Talent hast. Twisten geht auch ohne, aber der langsame Schlag, um den herum sie gebaut ist, macht die Gewohnheit erst lohnend.",
    ["|cffff8800Only active while playing a Paladin.|r"] = "|cffff8800Nur aktiv, wenn du einen Paladin spielst.|r",
    ["|cffff8800Switch the Class Specific module on to use this.|r"] = "|cffff8800Schalte das Modul „Klassenspezifisch“ ein, um das zu nutzen.|r",
    ["Class-specific tools, grouped by class: the Priest Vampiric Touch mana tracker, DoT trackers, the Shaman totem bar and the Paladin seal twist helper."] = "Klassenspezifische Werkzeuge, nach Klasse sortiert: der Manazähler für Vampirberührung des Priesters, DoT-Anzeigen, die Totemleiste des Schamanen und die Seal-Twist-Hilfe des Paladins.",
    ["Simplified Chinese and Traditional Chinese. Both are complete: every interface text, every option and every patch note, 2528 entries each. They are separate translations, not one converted into the other. Pick yours under General, or leave the setting on Auto and it follows your game client."] = "Vereinfachtes und traditionelles Chinesisch. Beide sind vollständig: jeder Oberflächentext, jede Einstellung und jede Patchnotiz, je 2528 Einträge. Es sind zwei eigenständige Übersetzungen, nicht eine aus der anderen umgewandelt. Wähle deine unter Allgemein, oder lass die Einstellung auf Auto, dann folgt sie deinem Spielclient.",
    -- Spam Filter
    ["Spam Filter"] = "Spam-Filter",
    ["Hide (and optionally ignore) chat spammers whose names spell 'casino' & co. with look-alike letters."] = "Blendet Chat-Spammer aus (optional auch ignorieren), deren Namen 'casino' & Co. mit ähnlich aussehenden Buchstaben schreiben.",
    ["|cffaaaaaaHides chat from gold/casino spammers whose names use look-alike letters (e.g. Gãsïnô, Casinòbâbe). The name is folded to plain letters, then matched against the keywords below. Applies to whisper, channels, say, yell and emotes — not guild/party/raid.|r"] = "|cffaaaaaaBlendet Chat von Gold-/Casino-Spammern aus, deren Namen ähnlich aussehende Buchstaben nutzen (z.B. Gãsïnô, Casinòbâbe). Der Name wird auf normale Buchstaben reduziert und gegen die Stichwörter unten geprüft. Gilt für Flüstern, Channels, Sagen, Schreien und Emotes — nicht Gilde/Gruppe/Schlachtzug.|r",
    ["Hide their chat messages"] = "Ihre Chat-Nachrichten ausblenden",
    ["Also add them to your ignore list"] = "Zusätzlich auf die Ignorieren-Liste setzen",
    ["Adds matched senders to /ignore too. The ignore list holds only ~50 names and spammers keep changing names, so hiding is usually enough — leave this off unless you want it."] = "Setzt erkannte Absender zusätzlich auf /ignore. Die Ignorieren-Liste fasst nur ~50 Namen und Spammer wechseln ständig den Namen — Ausblenden reicht meist. Nur einschalten wenn gewünscht.",
    ["Also match the message text"] = "Auch den Nachrichtentext prüfen",
    ["Also checks the message body for the keywords, not just the sender's name. Catches more spam but can have false positives."] = "Prüft auch den Nachrichtentext auf die Stichwörter, nicht nur den Absendernamen. Fängt mehr Spam, kann aber Fehltreffer haben.",
    ["Keywords"] = "Stichwörter",
    ["|cffaaaaaaBuilt-in: casino / asino / gasino / kasino. Add your own below, comma-separated (look-alike letters are handled automatically).|r"] = "|cffaaaaaaEingebaut: casino / asino / gasino / kasino. Eigene unten ergänzen, mit Komma getrennt (ähnlich aussehende Buchstaben werden automatisch behandelt).|r",
    ["Extra keywords"] = "Zusätzliche Stichwörter",
    ["Block messages with web links"] = "Nachrichten mit Web-Links blocken",
    ["Hides any message containing a web link (http://, www., domain.tld) in the filtered channels. Whitelisted names are exempt. Opt-in — can catch the occasional legit link."] = "Blendet jede Nachricht mit einem Web-Link aus (http://, www., domain.tld) in den gefilterten Channels. Whitelist-Namen sind ausgenommen. Optional — kann mal einen legitimen Link erwischen.",
    ["Whitelist"] = "Whitelist",
    ["|cffaaaaaaNames here are never filtered. Comma-separated, or use |r|cff9b6cff/vcui spam <name>|r|cffaaaaaa to toggle one.|r"] = "|cffaaaaaaNamen hier werden nie gefiltert. Mit Komma getrennt, oder |r|cff9b6cff/vcui spam <Name>|r|cffaaaaaa zum Umschalten.|r",
    ["Never filter these names"] = "Diese Namen nie filtern",
    ["Spam filter: '%s' removed from the whitelist."] = "Spam-Filter: '%s' von der Whitelist entfernt.",
    ["Spam filter: '%s' added to the whitelist (never filtered)."] = "Spam-Filter: '%s' zur Whitelist hinzugefügt (wird nie gefiltert).",
    ["|cff9b6cffBlocked this session: %d|r"] = "|cff9b6cffDiese Sitzung geblockt: %d|r",

    -- Quest Log
    ["Quest Log"] = "Questlog",
    ["Enhances the quest log: quest levels (and optional quest IDs) in the titles, a larger frame, and a Parchment or Dark theme."] = "Verbessert das Questlog: Quest-Level (optional Quest-IDs) im Titel, größeres Fenster und Pergament- oder Dunkel-Design.",
    ["|cffaaaaaaShows quest levels (and optionally IDs) in the quest log, can enlarge it, and lets you pick a Parchment or Dark look.|r"] = "|cffaaaaaaZeigt Quest-Level (optional IDs) im Questlog, kann es vergrößern und bietet Pergament- oder Dunkel-Look zur Auswahl.|r",
    ["Titles"] = "Titel",
    ["Show quest levels"] = "Quest-Level anzeigen",
    ["Show quest IDs"] = "Quest-IDs anzeigen",
    ["Frame"] = "Fenster",
    ["Larger quest log"] = "Größeres Questlog",
    ["Enlarges the quest log so more quests are visible with the detail pane beside the list. /reload to fully apply or revert."] = "Vergrößert das Questlog, sodass mehr Quests sichtbar sind und das Detailfenster neben der Liste steht. /reload zum vollständigen Anwenden oder Zurücksetzen.",
    ["Theme"] = "Design",
    ["Parchment (default)"] = "Pergament (Standard)",
    ["Dark"] = "Dunkel",
    ["Quest log size changed. /reload recommended."] = "Questlog-Größe geändert. /reload empfohlen.",

    -- Profession Window
    ["Profession Window"] = "Berufe-Fenster",
    ["Enlarges and themes the profession windows (Tradeskill & Craft) to match the quest log: the detail pane sits beside the recipe list, with a Parchment or Dark theme."] = "Vergrößert und gestaltet die Berufe-Fenster (Beruf & Handwerk) passend zum Questlog: das Detailfenster steht neben der Rezeptliste, mit Pergament- oder Dunkel-Design.",
    ["|cffaaaaaaEnlarges the Tradeskill and Craft windows so the detail sits beside the recipe list, with a Parchment or Dark look.|r"] = "|cffaaaaaaVergrößert die Berufe- und Handwerksfenster, sodass das Detailfenster neben der Rezeptliste steht – mit Pergament- oder Dunkel-Look.|r",
    ["Larger profession window"] = "Größeres Berufe-Fenster",
    ["Enlarges the profession windows so more recipes are visible with the detail pane beside the list. /reload to fully apply or revert."] = "Vergrößert die Berufe-Fenster, sodass mehr Rezepte sichtbar sind und das Detailfenster neben der Liste steht. /reload zum vollständigen Anwenden oder Zurücksetzen.",
    ["Profession window size changed. /reload recommended."] = "Berufe-Fenster-Größe geändert. /reload empfohlen.",
    ["Recipes"] = "Rezepte",
    ["Show craftable count"] = "Herstellbare Anzahl anzeigen",
    ["Shows how many of each recipe you can make right now, like [12]."] = "Zeigt, wie oft du jedes Rezept gerade herstellen kannst, z. B. [12].",
    ["Craftable"] = "Herstellbar",
    ["Missing"] = "Fehlt",
    ["Craftable count incl. bank + missing mats"] = "Herstellbare Anzahl inkl. Bank + fehlende Mats",
    ["On the selected recipe, shows how many you can craft counting your bank mats too, and lists what's still missing. Bank mats are remembered from your last visit to the bank."] = "Zeigt beim ausgewählten Rezept, wie oft du es herstellen kannst – inkl. deiner Bank-Mats – und listet auf, was noch fehlt. Bank-Mats werden von deinem letzten Bankbesuch gemerkt.",
    ["|cff888888Click a recipe's star (or right-click the recipe) to favourite it — the star turns gold.|r"] = "|cff888888Klicke den Stern eines Rezepts (oder Rechtsklick aufs Rezept), um es zu favorisieren – der Stern wird golden.|r",
    ["Favourites first"] = "Favoriten zuerst",
    ["Recipes you marked with the star float to the top of the list."] = "Mit dem Stern markierte Rezepte rücken an den Anfang der Liste.",
    ["Favourite (click to toggle)"] ="Favorit (Klick zum Umschalten)",
    ["Auction value"] = "Auktionswert",
    ["Show auction value & profit"] = "Auktionswert & Gewinn anzeigen",
    ["On the selected recipe, shows the crafted item's auction value, material cost and profit, using Auctionator's price data."] = "Zeigt beim ausgewählten Rezept den Auktionswert des hergestellten Gegenstands, die Materialkosten und den Gewinn – anhand der Preisdaten von Auctionator.",
    ["|cff1eff00Auctionator found — prices from its data.|r"] = "|cff1eff00Auctionator gefunden – Preise aus dessen Daten.|r",
    ["|cffff5555Auctionator not found. Install Auctionator to get price data.|r"] = "|cffff5555Auctionator nicht gefunden. Installiere Auctionator für Preisdaten.|r",
    ["Recipe info (CraftLib)"] = "Rezept-Infos (CraftLib)",
    ["|cffaaaaaaThree buttons under the recipe list toggle extra info on the selected recipe: source (where to learn/get it), skill levels (orange/yellow/green/grey) and your skill-up chance.|r"] = "|cffaaaaaaDrei Knöpfe unter der Rezeptliste schalten Zusatz-Infos zum ausgewählten Rezept um: Quelle (wo lernen/bekommen), Skill-Schwellen (orange/gelb/grün/grau) und deine Skill-up-Chance.|r",
    ["|cff1eff00CraftLib found — recipe source & levels available.|r"] = "|cff1eff00CraftLib gefunden – Rezept-Quelle & -Schwellen verfügbar.|r",
    ["|cffff5555CraftLib not found. Install CraftLib to show recipe source & levels.|r"] = "|cffff5555CraftLib nicht gefunden. Installiere CraftLib für Rezept-Quelle & -Schwellen.|r",
    ["Source"] = "Quelle",
    ["Levels"] = "Schwellen",
    ["Skill-up"] = "Skill-up",
    ["Trainer"] = "Lehrer",
    ["Vendor"] = "Händler",
    ["Drop"] = "Drop",
    ["Reputation"] = "Ruf",
    ["Quest"] = "Quest",
    ["Starter"] = "Startrezept",
    ["Discovery"] = "Entdeckung",
    ["World drop"] = "Welt-Drop",
    ["orange"] = "Orange",
    ["yellow"] = "Gelb",
    ["green"] = "Grün",
    ["gray"] = "Grau",
    ["AH value"] = "AH-Wert",
    ["Material cost"] = "Materialkosten",
    ["Profit"] = "Gewinn",

    -- Bind-on-Socket Fix
    ["Bind-on-Socket Fix"] = "Sockel-Bindung-Fix",
    ["Re-adds the missing BIND_SOCKET confirmation dialog so socketing a gem that binds the item no longer throws a Lua error (Anniversary client)."] = "Fügt den fehlenden BIND_SOCKET-Bestätigungsdialog wieder hinzu, damit das Einsetzen eines bindenden Steins keinen Lua-Fehler mehr auslöst (Anniversary-Client).",
    ["Socketing this gem will bind the item to you. Continue?"] = "Diesen Stein einzusetzen bindet den Gegenstand an dich. Fortfahren?",
    ["The Anniversary client is missing the |cffffffffBIND_SOCKET|r confirmation dialog. Socketing a gem that would bind the item then throws \"Dialog BIND_SOCKET does not exist\" and aborts. This re-adds the dialog so socketing works."] = "Dem Anniversary-Client fehlt der |cffffffffBIND_SOCKET|r-Bestätigungsdialog. Das Einsetzen eines Steins, der den Gegenstand bindet, wirft dann \"Dialog BIND_SOCKET does not exist\" und bricht ab. Dies fügt den Dialog wieder hinzu, damit das Sockeln funktioniert.",
    ["|cff66ff66Dialog defined|r"] = "|cff66ff66Dialog definiert|r",
    ["not defined yet"] = "noch nicht definiert",

    -- Nameplate Role Fix
    ["Nameplate Role Fix"] = "Namensplaketten-Rollen-Fix",
    ["Stops the Lua error that fires every time a nameplate appears (Blizzard's nameplate code calls a specialization API this client does not support)."] = "Stoppt den Lua-Fehler, der bei jeder erscheinenden Namensplakette auftritt (Blizzards Plaketten-Code ruft eine Spezialisierungs-API auf, die dieser Client nicht unterstützt).",
    ["Blizzard's own nameplate code asks for your specialization role - an API the Anniversary client rejects. The resulting Lua error fires on every nameplate spawn and aborts part of the nameplate setup. This fix answers the question safely with 'no role'."] = "Blizzards eigener Plaketten-Code fragt nach deiner Spezialisierungs-Rolle – eine API, die der Anniversary-Client ablehnt. Der Lua-Fehler feuert bei jeder erscheinenden Namensplakette und bricht einen Teil des Plaketten-Aufbaus ab. Dieser Fix beantwortet die Frage sicher mit 'keine Rolle'.",
    ["not needed on this client"] = "auf diesem Client nicht nötig",

    -- Combat Indicator
    ["Combat Indicator"] = "Kampf-Anzeige",
    ["Restores the missing 'in combat' glow on the Player frame (Anniversary default-UI bug). Pulses a red glow around your portrait while you are in combat."] = "Stellt den fehlenden 'im Kampf'-Glow am Spielerframe wieder her (Anniversary-Default-UI-Bug). Pulsierender roter Glow um dein Portrait, solange du im Kampf bist.",
    ["|cffaaaaaaThe default Player frame on Anniversary no longer shows when you are in combat. This restores it: a red glow pulses around your portrait while you are in combat.|r"] = "|cffaaaaaaDer Standard-Spielerframe auf Anniversary zeigt nicht mehr an, wenn du im Kampf bist. Dies stellt es wieder her: ein roter Glow pulsiert um dein Portrait, solange du im Kampf bist.|r",

    -- Disenchant Queue
    ["Disenchant Queue"] = "Entzauber-Queue",
    ["For enchanters: a window with one button that disenchants your bag items one click each, auto-advancing through the queue (no casting + picking each item by hand)."] = "Für Verzauberer: ein Fenster mit einem Knopf, der deine Taschen-Gegenstände mit je einem Klick entzaubert und sich automatisch durch die Queue arbeitet (kein manuelles Zaubern + Anklicken pro Gegenstand).",
    ["%d item(s) to disenchant"] = "%d Gegenstände zum Entzaubern",
    ["|cff888888Nothing to disenchant.|r"] = "|cff888888Nichts zum Entzaubern.|r",
    ["You need the Enchanting profession (Disenchant) to use this."] = "Du brauchst den Beruf Verzauberkunst (Entzaubern) dafür.",
    ["This module is disabled."] = "Dieses Modul ist deaktiviert.",
    ["Disenchant"] = "Entzaubern",
    ["Skip"] = "Überspringen",
    ["Disenchanting…"] = "Entzaubere…",
    ["|cffaaaaaaA window with one button that disenchants your bag items one click each and auto-advances through the queue. WoW does not allow fully unattended disenchanting, so this is one click per item — but you never have to cast and pick each item by hand again.|r"] = "|cffaaaaaaEin Fenster mit einem Knopf, der deine Taschen-Gegenstände mit je einem Klick entzaubert und automatisch zum nächsten springt. WoW erlaubt keine vollautomatische Entzauberung, also ist es ein Klick pro Gegenstand – aber du musst nie wieder pro Gegenstand zaubern und anklicken.|r",
    ["|cff1eff00You know Disenchant.|r"] = "|cff1eff00Du beherrschst Entzaubern.|r",
    ["|cffff5555You are not an enchanter — this tool will do nothing.|r"] = "|cffff5555Du bist kein Verzauberer – dieses Werkzeug tut nichts.|r",
    ["Open disenchant queue"] = "Entzauber-Queue öffnen",
    ["|cff888888Also: /disenchant or /entzaubern|r"] = "|cff888888Auch: /disenchant oder /entzaubern|r",
    ["Quality range"] = "Qualitätsbereich",
    ["Lowest quality"] = "Niedrigste Qualität",
    ["Highest quality"] = "Höchste Qualität",
    ["|cff888888Only weapons and armour are listed. Each item is shown before you click, so you always see what you are about to disenchant.|r"] = "|cff888888Nur Waffen und Rüstung werden gelistet. Jeder Gegenstand wird vor dem Klick angezeigt – du siehst also immer, was du gleich entzauberst.|r",
    ["Ignore"] = "Ignorieren",
    ["Skip this item for now (it comes back next time)."] = "Diesen Gegenstand vorerst überspringen (kommt nächstes Mal wieder).",
    ["Never disenchant this item (add it to the ignore list)."] = "Diesen Gegenstand nie entzaubern (zur Ignorier-Liste hinzufügen).",
    ["Ignored items"] = "Ignorierte Gegenstände",
    ["|cff888888No ignored items yet. Use the Ignore button in the window to protect an item.|r"] = "|cff888888Noch keine ignorierten Gegenstände. Nutze den Ignorieren-Knopf im Fenster, um einen Gegenstand zu schützen.|r",
    ["|cff888888Click an entry to remove it from the ignore list.|r"] = "|cff888888Klicke einen Eintrag an, um ihn aus der Ignorier-Liste zu entfernen.|r",
    ["Clear ignore list"] = "Ignorier-Liste leeren",

    -- Sidebar pages
    ["Enabled"] = "Aktiviert",
    ["Windows & Professions"] = "Fenster & Berufe",
    ["Quest log, profession windows and the disenchant queue, all in one place."] = "Questlog, Berufe-Fenster und Entzauber-Queue – alles an einem Ort.",
    ["Gold & Vendors"] = "Gold & Händler",
    ["Gold tracking and automatic buying at vendors."] = "Gold-Verfolgung und automatischer Einkauf bei Händlern.",
    ["Chat & Tooltips"] = "Chat & Tooltips",
    ["Chat spam filter and tooltip IDs."] = "Chat-Spamfilter und Tooltip-IDs.",

    -- /vcui help
    ["VuloClassicUI — commands:"] = "VuloClassicUI — Befehle:",
    ["jump to that module's page"] = "zur Seite dieses Moduls springen",
    ["list all modules with on/off state"] = "alle Module mit An/Aus-Status auflisten",
    ["toggle a name on/off the spam-filter whitelist"] = "Namen auf der Spam-Filter-Whitelist umschalten",
    ["reset the gold tracker session"] = "Gold-Tracker-Sitzung zurücksetzen",
    ["Type |cff9b6cff/vcui help|r for the full command list."] = "Tippe |cff9b6cff/vcui help|r für die komplette Befehlsliste.",
    ["Spam filter not available."] = "Spam-Filter nicht verfügbar.",
    ["Usage: /vcui spam <name> — toggle a name on/off the spam-filter whitelist."] = "Benutzung: /vcui spam <Name> — Namen auf der Spam-Filter-Whitelist umschalten.",

    -- Swing Timer
    ["Swing Timer"] = "Waffen-Swingtimer",
    ["MH"] = "MH",
    ["OH"] = "OH",
    ["Weapon swing timer for your melee auto-attacks (any melee class). Shows a main-hand bar and, while dual-wielding, an off-hand bar."] = "Waffen-Swingtimer für deine Nahkampf-Autoangriffe (jede Nahkampfklasse). Zeigt eine Waffenhand-Leiste und beim beidhändigen Kämpfen eine Nebenhand-Leiste.",
    ["|cffaaaaaaShows when your next melee auto-attack lands (any melee class). The off-hand bar only appears while dual-wielding. The bar fills up toward the swing; the number is the time left.|r"] = "|cffaaaaaaZeigt, wann dein nächster Nahkampf-Autoangriff trifft (jede Nahkampfklasse). Die Nebenhand-Leiste erscheint nur beim beidhändigen Kämpfen. Die Leiste füllt sich bis zum Schlag; die Zahl ist die verbleibende Zeit.|r",
    ["Enable swing timer"] = "Swingtimer aktivieren",
    ["Foreground texture"] = "Vordergrund-Textur",
    ["Foreground transparency"] = "Vordergrund-Transparenz",
    ["Background texture"] = "Hintergrund-Textur",
    ["Background transparency"] = "Hintergrund-Transparenz",
    ["|cffffffffSWING TIMER|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffffSWINGTIMER|r\n|cffaaaaaaZiehen oder Pfeiltasten|r",
    ["|cffffffffLOADOUTS SIDEBAR|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffffLOADOUTS-LEISTE|r\n|cffaaaaaaZiehen oder Pfeiltasten|r",
    ["Swing Timer position: x=%.0f, y=%.0f"] = "Swingtimer-Position: x=%.0f, y=%.0f",
    ["Swing Timer mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Test' again to finish."] = "Swingtimer-Verschiebemodus aktiv. |cff9b6cffLila Kasten ziehen|r oder |cff9b6cffPfeiltasten|r (SHIFT = 5px). 'Entsperren / Test' erneut klicken zum Beenden.",
    ["Swing Timer mover disabled."] = "Swingtimer-Verschiebemodus deaktiviert.",
    ["Show off-hand bar (while dual-wielding)"] = "Nebenhand-Leiste zeigen (beim beidhändigen Kämpfen)",
    ["Show time remaining"] = "Verbleibende Zeit anzeigen",
    ["Only show while attacking"] = "Nur beim Angreifen zeigen",
    ["Hides the bars unless you're auto-attacking. Turn off to always show them."] = "Versteckt die Leisten, außer du führst Autoangriffe aus. Ausschalten, um sie immer zu zeigen.",
    ["Bar color"] = "Balkenfarbe",
    ["Gap between bars"] = "Abstand zwischen Leisten",
    ["Blue"] = "Blau",
    ["Violet"] = "Violett",
    ["Cyan"] = "Türkis",
    ["Green"] = "Grün",
    ["Gold"] = "Gold",
    ["Red"] = "Rot",

    -- Module display names
    ["Fishing"] = "Angeln",
    ["Mail"]    = "Post",

    -- Loadouts
    ["Loadouts"] = "Ausrüstungs-Sets",
    ["Save and quickly equip gear sets for different specs, content, or roles."] = "Speichere und wechsle schnell zwischen Ausrüstungs-Sets für verschiedene Skillungen, Content oder Rollen.",
    ["Save your current equipment as named gear sets and quickly switch between them. Equipping requires you to be out of combat — items in your bags are auto-equipped via Use."] = "Speichere deine aktuelle Ausrüstung als benannte Sets und wechsle schnell dazwischen. Equippen erfordert dass du außerhalb des Kampfes bist — Items in deinen Taschen werden automatisch via 'Benutzen' equipt.",
    ["Save current equipment as a new loadout. Enter name:"] = "Aktuelle Ausrüstung als neues Set speichern. Name eingeben:",
    ["Confirm before deleting a loadout"] = "Bestätigen vor dem Löschen eines Sets",
    ["Saved Loadouts"] = "Gespeicherte Sets",
    ["Equip"] = "Anlegen",
    ["Overwrite"] = "Überschreiben",
    ["Delete"] = "Löschen",
    ["Save"] = "Speichern",
    ["Cancel"] = "Abbrechen",
    ["Yes"] = "Ja",
    ["No"] = "Nein",
    ["items"] = "Items",
    ["Please provide a name for the loadout."] = "Bitte einen Namen für das Set angeben.",
    ["Loadout '%s' saved (%d items)."] = "Set '%s' gespeichert (%d Items).",
    ["Loadout '%s' updated with current gear."] = "Set '%s' wurde mit aktueller Ausrüstung aktualisiert.",
    ["Loadout '%s' deleted."] = "Set '%s' gelöscht.",
    ["Loadout '%s' does not exist."] = "Set '%s' existiert nicht.",
    ["Rename..."] = "Umbenennen...",
    ["Rename loadout '%s'. Enter new name:"] = "Set '%s' umbenennen. Neuer Name:",
    ["A loadout named '%s' already exists."] = "Ein Set namens '%s' existiert bereits.",
    ["Loadout '%s' renamed to '%s'."] = "Set '%s' heißt jetzt '%s'.",
    ["On"] = "An",
    ["Select all"] = "Alle auswählen",
    ["Deselect all"] = "Alle abwählen",
    ["Interface layout (window positions and links)"] = "Oberflächen-Layout (Fensterpositionen und Verknüpfungen)",
    ["Fonts & colors (account-wide)"] = "Schriftarten & Farben (kontoweit)",
    ["Also carries your account-wide font and color settings; they apply immediately when the string is imported."] = "Nimmt auch deine kontoweiten Schrift- und Farbeinstellungen mit; sie greifen sofort, wenn die Zeichenfolge importiert wird.",
    ["|cffaaaaaaThe export will include %d of %d modules.|r"] = "|cffaaaaaaDer Export umfasst %d von %d Modulen.|r",
    ["Nothing selected to export."] = "Nichts zum Exportieren ausgewählt.",
    ["|cffaaaaaaUntick modules to share only a part - a partial string merges onto the importer's active profile.|r"] = "|cffaaaaaaModule abwählen, um nur einen Teil zu teilen - eine Teil-Zeichenfolge verschmilzt beim Empfänger mit dessen aktivem Profil.|r",
    ["Standard Action Bars"] = "Standard-Aktionsleisten",
    ["Modern"] = "Modern",
    ["|cffaaaaaaThe game's own action bars stay in place. Frame style and Dark Mode below come from the Dark Skin module and style Blizzard's buttons directly.|r"] = "|cffaaaaaaDie spieleigenen Aktionsleisten bleiben. Rahmenstil und Dunkelmodus darunter kommen aus dem Dark-Skin-Modul und gestalten Blizzards Knöpfe direkt.|r",
    ["Apply layout to all bars"] = "Layout auf alle Leisten anwenden",
    ["Copies this bar's layout - scale, icon size, buttons per row, spacing, direction - to every other bar."] = "Kopiert das Layout dieser Leiste - Skalierung, Symbolgröße, Knöpfe je Reihe, Abstand, Richtung - auf alle anderen.",
    ["Layout applied to all bars."] = "Layout auf alle Leisten angewendet.",
    ["Text sizes"] = "Textgrößen",
    ["Bar Display"] = "Leistenanzeige",
    ["Menu, Bags & XP Bar"] = "Menü, Taschen & EP-Leiste",
    ["|cffaaaaaaOnly active in Modern mode (Bar Display tab).|r"] = "|cffaaaaaaWirkt nur im Modern-Modus (Tab Leistenanzeige).|r",
    ["Click: layout settings. Right-click: text sizes."] = "Klick: Layout-Einstellungen. Rechtsklick: Textgrößen.",
    ["Bar Animations"] = "Leistenanimationen",
    ["Tint the pressed state"] = "Gedrückt-Zustand einfärben",
