    ["Tint the hover highlight"] = "Hervorhebung einfärben",
    ["Colours the glow a button shows under the mouse."] = "Färbt das Leuchten, das ein Knopf unter dem Zeiger zeigt.",
    ["Use class colour"] = "Klassenfarbe nutzen",
    ["Enable bar background"] = "Leistenhintergrund aktivieren",
    ["A flat colour panel behind the bar, sized with it."] = "Eine einfarbige Fläche hinter der Leiste, die mit ihr wächst.",
    ["Padding"] = "Rand",
    ["Flat (default)"] = "Einfarbig (Standard)",
    ["Loadout '%s' equipped (%d items swapped)."] = "Set '%s' angelegt (%d Items gewechselt).",
    ["Loadout '%s' equipped (%d swapped, %d missing from bags)."] = "Set '%s' angelegt (%d gewechselt, %d fehlen in den Taschen).",
    ["Loadout '%s': %d items missing from bags, nothing swapped."] = "Set '%s': %d Items fehlen in den Taschen, nichts gewechselt.",
    ["Loadout '%s' already equipped."] = "Set '%s' bereits angelegt.",
    ["Delete loadout '%s'?"] = "Set '%s' löschen?",
    ["Cannot change equipment in combat."] = "Ausrüstung kann nicht im Kampf geändert werden.",
    ["Equipment swap API not available on this client."] = "Equipment-Swap-API auf diesem Client nicht verfügbar.",
    ["No loadouts saved yet."] = "Noch keine Sets gespeichert.",
    ["|cffaaaaaaNo loadouts saved yet. Use the button above to save your current gear.|r"] = "|cffaaaaaaNoch keine Sets gespeichert. Nutze den Button oben um deine aktuelle Ausrüstung zu speichern.|r",
    ["Saved loadouts:"] = "Gespeicherte Sets:",
    ["Usage: /loadout equip <name> | save <name> | delete <name> | list"] = "Benutzung: /loadout equip <Name> | save <Name> | delete <Name> | list",
    ["Usage: /loadout delete <name>"] = "Benutzung: /loadout delete <Name>",
    ["|cffaaaaaaSlash commands: /loadout save <name>, /loadout equip <name>, /loadout delete <name>, /loadout list. Short alias: /lo|r"] = "|cffaaaaaaSlash-Befehle: /loadout save <Name>, /loadout equip <Name>, /loadout delete <Name>, /loadout list. Kurzform: /lo|r",
    ["No account-wide loadouts to import."] = "Keine accountweiten Sets zum Importieren vorhanden.",
    ["Imported %d account-wide loadout(s) onto this character."] = "%d accountweite(s) Set(s) auf diesen Charakter importiert.",
    ["You have account-wide loadouts from an older version. Type /lo import to copy them onto this character."] = "Du hast accountweite Sets aus einer älteren Version. Tippe /lo import um sie auf diesen Charakter zu kopieren.",
    ["Import from older version"] = "Aus älterer Version importieren",
    ["|cffaaaaaaYou have gear sets saved account-wide by an older version. Loadouts are now per-character — import copies them onto THIS character.|r"] = "|cffaaaaaaDu hast Ausrüstungs-Sets, die eine ältere Version accountweit gespeichert hat. Sets sind jetzt pro Charakter — der Import kopiert sie auf DIESEN Charakter.|r",
    ["Import account-wide loadouts"] = "Accountweite Sets importieren",
    ["Head"] = "Kopf", ["Neck"] = "Hals", ["Shoulder"] = "Schulter",
    ["Chest"] = "Brust", ["Waist"] = "Taille", ["Legs"] = "Beine",
    ["Feet"] = "Füße", ["Wrist"] = "Handgelenk", ["Hands"] = "Hände",
    ["Finger 1"] = "Finger 1", ["Finger 2"] = "Finger 2",
    ["Trinket 1"] = "Schmuckstück 1", ["Trinket 2"] = "Schmuckstück 2",
    ["Both trinkets"] = "Beide Schmuckstücke",
    ["Set focus"] = "Fokus setzen",
    ["Healing potion"] = "Heiltrank",
    ["Macro Factory"] = "Makro-Factory",
    ["|cffaaaaaaOne click builds a ready-made macro (per character). Then open |cffffffff/macro|r and drag it onto your action bar. Works on any client — uses item slots / IDs, no English needed.|r"] = "|cffaaaaaaEin Klick baut ein fertiges Makro (pro Charakter). Dann |cffffffff/macro|r öffnen und auf die Aktionsleiste ziehen. Funktioniert auf jedem Client – nutzt Item-Slots / IDs, kein Englisch nötig.|r",
    ["Macro Factory: can't create macros in combat."] = "Makro-Factory: Makros können im Kampf nicht erstellt werden.",
    ["Macro Factory: nothing to build (e.g. no healing potion in your bags)."] = "Makro-Factory: nichts zu bauen (z. B. kein Heiltrank in den Taschen).",
    ["Macro Factory: couldn't create it (character macro slots full?)."] = "Makro-Factory: konnte nicht erstellt werden (Charakter-Makroplätze voll?).",
    ["Macro '%s' updated — drag it from |cffffffff/macro|r onto your action bar."] = "Makro '%s' aktualisiert – aus |cffffffff/macro|r auf die Aktionsleiste ziehen.",
    ["Macro '%s' created — open |cffffffff/macro|r and drag it onto your action bar."] = "Makro '%s' erstellt – |cffffffff/macro|r öffnen und auf die Aktionsleiste ziehen.",
    ["Back"] = "Rücken",
    ["Main Hand"] = "Haupthand", ["Off Hand"] = "Schildhand", ["Ranged"] = "Distanz",
    ["Save All..."] = "Alles speichern...",
    ["Save Trinkets..."] = "Schmuckstücke speichern...",
    ["Save Weapons..."] = "Waffen speichern...",
    ["Save current as new..."] = "Aktuelle Ausrüstung als neu speichern...",
    ["Save trinkets only..."] = "Nur Schmuckstücke speichern...",
    ["Save weapons only..."] = "Nur Waffen speichern...",
    ["Settings..."] = "Einstellungen...",
    ["Minimap Button"] = "Minimap-Button",
    ["Left-click for a quick set-switcher menu, right-click to open settings, drag to reposition."] = "Linksklick öffnet ein Schnellwahl-Menü, Rechtsklick öffnet die Einstellungen, Ziehen zum Verschieben.",
    ["Left-click: switch set"] = "Linksklick: Set wechseln",
    ["Right-click: settings"] = "Rechtsklick: Einstellungen",
    ["Drag: reposition"] = "Ziehen: Verschieben",
    ["Auto-Switch on Stance/Form"] = "Auto-Wechsel bei Haltung/Gestalt",
    ["Enable auto-switching"] = "Auto-Wechsel aktivieren",
    ["Automatically equips a loadout when your stance/form changes (warrior stances, druid forms). Out-of-combat only — if a stance change happens in combat, the swap is deferred until combat ends."] = "Legt automatisch ein Set an, wenn deine Haltung/Gestalt wechselt (Krieger-Haltungen, Druiden-Gestalten). Nur außerhalb des Kampfes — bei einem Wechsel im Kampf wird der Swap bis nach dem Kampf verschoben.",
    ["Auto-equip on form"] = "Auto-Anlegen bei Gestalt",
    ["Equip this loadout automatically when the chosen stance/form is activated."] = "Legt dieses Set automatisch an, wenn die gewählte Haltung/Gestalt aktiviert wird.",
    ["Auto-Switch on Dual Spec"] = "Auto-Wechsel bei Dual-Spec",
    ["Enable spec auto-switching"] = "Spec-Auto-Wechsel aktivieren",
    ["Automatically equips a loadout when you switch between Spec 1 and Spec 2 (dual spec). Bind each loadout to a spec below. Requires dual spec to be active."] = "Legt automatisch ein Set an, wenn du zwischen Spec 1 und Spec 2 wechselst (Dual-Spec). Binde unten jedes Set an eine Spec. Erfordert aktive Dual-Spec.",
    ["Auto-equip on spec"] = "Auto-Anlegen bei Spec",
    ["Equip this loadout automatically when you switch to this spec."] = "Legt dieses Set automatisch an, wenn du zu dieser Spec wechselst.",
    ["None"] = "Keine",
    ["No Form"] = "Keine Gestalt",
    ["Form %d"] = "Gestalt %d",
    ["Character Frame Sidebar"] = "Charakterfenster-Sidebar",
    ["Show sidebar on character frame"] = "Sidebar am Charakterfenster anzeigen",
    ["Attach a quick-access sidebar to the right of the character window. Click a set to select, double-click or button to equip, right-click for context menu."] = "Hängt eine Schnellzugriffs-Sidebar rechts neben das Charakterfenster. Klick auf ein Set zum Auswählen, Doppelklick oder Button zum Anlegen, Rechtsklick für Kontextmenü.",
    ["|cffaaaaaaTip: with the character window open, enable edit mode (Unlock) to drag the sidebar; right-click the purple box to reset its position.|r"] = "|cffaaaaaaTipp: Bei geöffnetem Charakterfenster den Bearbeiten-Modus (Entsperren) aktivieren, um die Sidebar zu ziehen; Rechtsklick auf den lila Kasten setzt die Position zurück.|r",
    ["New Set"] = "Neues Set",
    ["Left-click: select"] = "Linksklick: Auswählen",
    ["Double-click / Right-click menu: equip"] = "Doppelklick / Rechtsklick-Menü: Anlegen",
    ["Change icon..."] = "Symbol ändern...",
    ["Icon for: %s"] = "Symbol für: %s",
    ["Bind to %s"] = "An %s binden",
    ["'%s' bound to %s."] = "'%s' an %s gebunden.",
    ["'%s' unbound from spec."] = "'%s' von Spec gelöst.",
    ["Replace: %s"] = "Ersetzen: %s",
    ["Remove from set"] = "Aus Set entfernen",
    ["Loadout '%s': slot updated."] = "Set '%s': Slot aktualisiert.",
    ["SlotPicker module is required for editing item slots."] = "Das SlotPicker-Modul ist nötig um Item-Slots zu bearbeiten.",
    ["Empty: %s"] = "Leer: %s",
    ["in the bank"] = "in der Bank",
    ["in bags, equip failed"] = "in den Taschen, Anlegen fehlgeschlagen",
    ["not found"] = "nicht gefunden",
    ["missing"] = "fehlt",
    ["Part of set: %s"] = "Teil von Set: %s",
    ["Add a slot"] = "Slot hinzufügen",
    ["Re-adds an ignored slot to this set."] = "Fügt dem Set einen ignorierten Slot wieder hinzu.",
    ["Right-click: remove this slot from the set."] = "Rechtsklick: entfernt diesen Slot aus dem Set.",
    ["Left-click to pick an item from your bags"] = "Linksklick um ein Item aus den Taschen zu wählen",
    ["(equipped)"] = "(angelegt)",

    ["Slot Picker"] = "Slot-Auswahl",
    ["Enable slot picker"] = "Slot-Auswahl aktivieren",
    ["|cffaaaaaaRight-click an equipment slot in the character window to see all compatible items from your bags and click one to equip it.|r"] = "|cffaaaaaaRechtsklick auf einen Ausrüstungs-Slot im Charakterfenster zeigt alle passenden Items aus deinen Taschen — Klick zum Anlegen.|r",
    ["Hover an equipment slot in the Character frame for a compact flyout of compatible bag items, or modifier-click for a larger pinnable picker. Click an item to equip it (out-of-combat)."] = "Über einen Ausrüstungs-Slot im Charakterfenster hovern öffnet ein kompaktes Flyout mit passenden Items aus den Taschen; Modifier-Klick öffnet die größere anheftbare Auswahl. Klick zum Anlegen (außerhalb des Kampfes).",
    ["Flyout on hover"] = "Flyout beim Hovern",
    ["Hovering an equipment slot pops out a compact strip of items you can swap in — the paperdoll flyout look. Turn off to use only the modifier-click picker."] = "Über einen Ausrüstungs-Slot hovern klappt eine kompakte Item-Leiste zum Wechseln aus — der Paperdoll-Flyout-Look. Aus lassen, um nur den Modifier-Klick zu nutzen.",
    ["Activation modifier"] = "Aktivierungs-Modifier",
    ["Choose which key combination opens the item picker when you click an equipment slot."] = "Wähle welche Tastenkombination die Item-Auswahl beim Klick auf einen Slot öffnet.",
    ["Shift + Right-click"] = "Shift + Rechtsklick",
    ["Alt + Right-click"] = "Alt + Rechtsklick",
    ["Ctrl + Right-click"] = "Strg + Rechtsklick",
    ["Right-click only"] = "Nur Rechtsklick",
    ["Grid columns"] = "Spalten im Raster",
    ["How many item icons per row in the picker popup."] = "Wie viele Item-Icons pro Reihe im Auswahl-Popup.",
    ["Items for: %s"] = "Items für: %s",
    ["Close automatically on mouse-out"] = "Automatisch schließen beim Verlassen",
    ["The picker closes itself shortly after the mouse leaves it. Drag it once to pin it open until you close it manually."] = "Die Auswahl schließt sich kurz nachdem die Maus sie verlassen hat. Einmal ziehen pinnt sie fest, bis du sie manuell schließt.",
    ["No matching items in your bags."] = "Keine passenden Items in deinen Taschen.",
    ["Item scanning API not available on this client."] = "Item-Scan-API auf diesem Client nicht verfügbar.",

