    ["Auto (client language)"] = "Automatisch (Client-Sprache)",
    ["Choose the language for the VuloClassicUI interface. 'Auto' uses your WoW client's language (German clients see German, all others see English).\n\n|cffaaaaaaRequires /reload to apply.|r"] = "Wähle die Sprache der VuloClassicUI-Oberfläche. 'Automatisch' nutzt die Sprache deines WoW-Clients (deutsche Clients sehen Deutsch, alle anderen sehen Englisch).\n\n|cffaaaaaaErfordert /reload um wirksam zu werden.|r",
