    ["Comma-separated values, e.g. 30,60 — draws a line at each (great for tick or breakpoint marks)."] = "Kommagetrennte Werte, z.B. 30,60 — zeichnet an jedem eine Linie (praktisch für Tick- oder Breakpoint-Marken).",
