    ["|cffff5555Error enabling module '%s':|r %s"] = "|cffff5555Fehler beim Aktivieren von Modul '%s':|r %s",
    ["|cffff5555Error disabling '%s':|r %s"] = "|cffff5555Fehler beim Deaktivieren von '%s':|r %s",
    ["Module '%s' disabled. /reload recommended for full effect."] = "Modul '%s' deaktiviert. /reload empfohlen für vollen Effekt.",
    ["|cffff5555LibSharedMedia-3.0 not found, Media Registry will be skipped.|r"] = "|cffff5555LibSharedMedia-3.0 nicht gefunden, Media Registry wird übersprungen.|r",

    -- Profile system
    ["Profiles"] = "Profile",
    ["Manage profiles with different settings. A default profile can be assigned per class and is loaded automatically on login."] = "Profile mit verschiedenen Einstellungen verwalten. Pro Klasse kann ein Standardprofil festgelegt werden, das beim Einloggen automatisch geladen wird.",
    ["Active Profile"] = "Aktives Profil",
    ["You are currently using: |cff9b6cff%s|r  (Class: %s)"] = "Du verwendest aktuell: |cff9b6cff%s|r  (Klasse: %s)",
    ["Switch Profile"] = "Profil wechseln",
    ["Profile for this character"] = "Profil für diesen Charakter",
    ["|cffaaaaaaPins a profile to THIS character only. At login it beats the class assignment and the account-wide selection - so every character can keep its own minimap, bars and window settings.|r"] = "|cffaaaaaaLegt ein Profil nur für DIESEN Charakter fest. Beim Einloggen hat es Vorrang vor der Klassen-Zuweisung und der kontoweiten Auswahl – so behält jeder Charakter seine eigenen Minimap-, Leisten- und Fenster-Einstellungen.|r",
    ["This character"] = "Dieser Charakter",
    ["Create New Profile"] = "Neues Profil erstellen",
    ["Name"] = "Name",
    ["Copy Settings From"] = "Einstellungen übernehmen von",
    ["- empty profile (defaults) -"] = "- leeres Profil (Standard) -",
    ["- none -"] = "- keines -",
    ["Create Profile"] = "Profil erstellen",
    ["|cffff5555Please enter a name.|r"] = "|cffff5555Bitte einen Namen eingeben.|r",
    ["|cffff5555Please enter a new name.|r"] = "|cffff5555Bitte einen neuen Namen eingeben.|r",
    ["Error."] = "Fehler.",
    ["Share Profile"] = "Profil teilen",
    ["|cffaaaaaaExport the current profile as a text string - as a backup or to share it. Importing always creates a NEW profile and never overwrites anything.|r"] = "|cffaaaaaaExportiert das aktuelle Profil als Text-String – als Sicherung oder zum Weitergeben. Der Import legt immer ein NEUES Profil an und überschreibt nie etwas.|r",
    ["Export as string"] = "Als String exportieren",
    ["Import from string"] = "Aus String importieren",
    ["This is not a VuloClassicUI profile string."] = "Das ist kein VuloClassicUI-Profil-String.",
    ["The profile string is damaged."] = "Der Profil-String ist beschädigt.",
    ["Profile '%s' imported. Activate it via 'Switch Profile'."] = "Profil '%s' importiert. Über 'Profil wechseln' aktivieren.",
    ["Manage Profiles"] = "Profile verwalten",
    ["Delete..."] = "Löschen...",
    ["Reset to defaults..."] = "Auf Standard zurücksetzen...",
    ["Delete profile '%s'? This cannot be undone."] = "Profil '%s' löschen? Das kann nicht rückgängig gemacht werden.",
    ["Reset profile '%s' to the default settings? This cannot be undone."] = "Profil '%s' auf die Standardeinstellungen zurücksetzen? Das kann nicht rückgängig gemacht werden.",
    ["Profile changed. Reload the UI now so every module picks it up?"] = "Profil gewechselt. UI jetzt neu laden, damit alle Module es übernehmen?",
    ["|cffff5555Profile '%s' could not be loaded:|r %s"] = "|cffff5555Profil '%s' konnte nicht geladen werden:|r %s",
    ["Rename to"] = "Umbenennen in",
    ["Rename"] = "Umbenennen",
    ["|cffff5555Default profile cannot be deleted.|r"] = "|cffff5555Standardprofil kann nicht gelöscht werden.|r",
    ["Apply to Active Class"] = "Auf aktive Klasse anwenden",
    ["Sets the current profile as the default for %s."] = "Legt das aktuelle Profil als Standard für %s fest.",
    ["'%s' is now the default profile for %s."] = "'%s' ist jetzt das Standardprofil für %s.",
    ["Per-class profile (quick setup)"] = "Pro-Klasse-Profil (Schnell-Einrichtung)",
    ["|cffaaaaaaOne click: makes a profile named after your class (copied from the current one) and loads it for this class automatically. Run it once on each character — every class then keeps its own cooldown bars, frames and settings.|r"] = "|cffaaaaaaEin Klick: legt ein Profil mit dem Namen deiner Klasse an (Kopie des aktuellen) und lädt es automatisch für diese Klasse. Einmal pro Charakter ausführen — jede Klasse behält dann eigene Cooldown-Leisten, Frames und Einstellungen.|r",
    ["Set up a %s profile"] = "%s-Profil einrichten",
    ["'%s' is now the %s profile. |cffffff00/reload|r to apply."] = "'%s' ist jetzt das %s-Profil. |cffffff00/reload|r zum Anwenden.",
    ["Profile Assignment per Class"] = "Profilzuweisung pro Klasse",
    ["Choose a default profile for each class. When logging in with a character of that class, the profile will be loaded automatically."] = "Wähle für jede Klasse ein Standardprofil. Beim Einloggen mit einem Charakter dieser Klasse wird das Profil automatisch geladen.",
    ["Settings migrated to profile system (all settings are in profile '%s')."] = "Einstellungen ins Profilsystem migriert (alle Einstellungen liegen in Profil '%s').",
    ["Bar setups are now stored once for the whole account: %d kept, %d duplicates merged."] = "Leisten-Belegungen liegen jetzt einmal für den ganzen Account: %d behalten, %d Doppelte zusammengeführt.",
    ["Trinket window settings now live in this addon's own database."] = "Die Einstellungen des Schmuck-Fensters liegen jetzt in der eigenen Datenbank.",
    ["Auto queue: top slot"] = "Auto-Warteschlange: oberer Platz",
    ["Auto queue: bottom slot"] = "Auto-Warteschlange: unterer Platz",
    ["Auto queue for this slot"] = "Auto-Warteschlange für diesen Platz",
    ["Same switch as alt-clicking the slot. While on, the queue swaps this trinket in combat, following the order below."] = "Derselbe Schalter wie Alt+Klick auf den Platz. Eingeschaltet tauscht die Warteschlange im Kampf nach der Reihenfolge unten.",
    ["Order"] = "Reihenfolge",
    ["The queue works through this list from the top. Pick an entry to move it or to change its settings."] = "Die Warteschlange arbeitet diese Liste von oben ab. Wähle einen Eintrag, um ihn zu verschieben oder seine Einstellungen zu ändern.",
    ["- empty -"] = "— leer —",
    ["— queue stops here —"] = "— ab hier wird nicht getauscht —",
    ["Up"] = "Nach oben",
    ["Down"] = "Nach unten",
    ["Add from bags"] = "Aus Taschen hinzufügen",
    ["Adds a trinket you are carrying to the end of this list."] = "Hängt ein Schmuckstück aus deinen Taschen ans Ende der Liste.",
    ["Swap delay"] = "Wechselverzögerung",
    ["Seconds this trinket stays equipped before the queue swaps it out again. 0 = no wait."] = "Sekunden, die dieses Schmuckstück angelegt bleibt, bevor die Warteschlange wieder tauscht. 0 = kein Warten.",
    ["This trinket is swapped in ahead of the ones above it once it is ready."] = "Dieses Schmuckstück wird vor den darüberstehenden eingewechselt, sobald es bereit ist.",
    ["Pause while equipped"] = "Pausieren, solange angelegt",
    ["While this trinket is worn the queue holds still - for a trinket whose effect you do not want cut short."] = "Solange dieses Schmuckstück getragen wird, hält die Warteschlange still — für Effekte, die man nicht abschneiden will.",
    ["|cffaaaaaaTip: left click a slot to use the trinket, right click for the list. Alt-click arms the auto queue for that slot.|r"] = "|cffaaaaaaTipp: Linksklick auf einen Platz benutzt das Schmuckstück, Rechtsklick zeigt die Auswahl. Alt+Klick schaltet die Auto-Warteschlange für diesen Platz scharf.|r",
    ["%d snapshot(s) had the same name but different contents and were kept under a new name."] = "%d Aufnahme(n) hatten denselben Namen bei anderem Inhalt und wurden unter einem neuen Namen behalten.",
    ["|cffff5555Profile '%s' does not exist.|r"] = "|cffff5555Profil '%s' existiert nicht.|r",
    ["Profile '%s' created%s."] = "Profil '%s' erstellt%s.",
    [" (copy of '%s')"] = " (Kopie von '%s')",
    ["Name cannot be empty."] = "Name darf nicht leer sein.",
    ["Profile already exists."] = "Profil existiert bereits.",
    ["Default profile cannot be deleted."] = "Standardprofil kann nicht gelöscht werden.",
    ["Profile does not exist."] = "Profil existiert nicht.",
    ["Active profile deleted. Default loaded. /reload recommended."] = "Aktives Profil gelöscht. Standard geladen. /reload empfohlen.",
    ["Profile '%s' deleted."] = "Profil '%s' gelöscht.",
    ["Default profile cannot be renamed."] = "Standardprofil kann nicht umbenannt werden.",
    ["New name already exists."] = "Neuer Name existiert bereits.",
    ["Profile '%s' renamed to '%s'."] = "Profil '%s' umbenannt in '%s'.",
    ["Profile '%s' loaded. |cffffff00/reload|r recommended so all modules use the new settings."] = "Profil '%s' geladen. |cffffff00/reload|r empfohlen, damit alle Module die neuen Einstellungen verwenden.",
    ["Settings imported from VuloFontBars."] = "Einstellungen aus VuloFontBars importiert.",
    ["Settings imported from ArenaEnemyEdit."] = "Einstellungen aus ArenaEnemyEdit importiert.",
    ["Settings imported from BetterBlizzQueue."] = "Einstellungen aus BetterBlizzQueue importiert.",
    ["Settings imported from idTip."] = "Einstellungen aus idTip importiert.",
    ["|cffff5555Profile module not loaded.|r"] = "|cffff5555Profil-Modul nicht geladen.|r",

    ["Warrior"] = "Krieger",
    ["Paladin"] = "Paladin",
    ["Hunter"] = "Jäger",
    ["Rogue"] = "Schurke",
    ["Priest"] = "Priester",
    ["Shaman"] = "Schamane",
