    ["Sort tab"] = "Tab sortieren",
    ["Sorts the current tab (mode from the bag options). Needs withdraw rights on the tab."] = "Sortiert den aktuellen Tab (Modus aus den Taschen-Optionen). Benötigt Abheberechte auf dem Tab.",
