    ["Shows who deposited or withdrew guild money."] = "Zeigt, wer Gildengold eingezahlt oder entnommen hat.",
    ["No transactions yet."] = "Noch keine Transaktionen.",
    ["Show your bank in a matching window when you visit a banker. Off = the default bank window."] = "Zeigt deine Bank beim Bankier in einem passenden Fenster. Aus = das Standard-Bankfenster.",
