    ["Show crowd control (separate row)"] = "Massenkontrolle anzeigen (eigene Reihe)",
    ["A separate, prominent row for crowd-control effects (Polymorph, Fear, Sap, …) on the unit, from anyone."] = "Eine eigene, auffällige Reihe für Massenkontroll-Effekte (Verwandlung, Furcht, Sappen, …) auf der Einheit, von beliebiger Quelle.",
    ["CC icon size"] = "CC-Symbolgröße",
    ["Max CC"] = "Max. CC",
    ["Highlight your focus"] = "Fokus hervorheben",
    ["A second, distinct glow ring on your focus target's nameplate."] = "Ein zweiter, eigener Leuchtring auf der Namensplakette deines Fokusziels.",
    ["Focus highlight colour"] = "Farbe der Fokus-Hervorhebung",
    ["Glow stealable / dispellable buffs"] = "Stehlbare / bannbare Stärkungen hervorheben",
    ["Glows enemy buffs you can remove (Spellsteal / Purge / Dispel Magic). Only for classes that can."] = "Hebt gegnerische Stärkungen hervor, die du entfernen kannst (Zauberraub / Reinigung / Magie bannen). Nur für Klassen, die das können.",
    ["Dispel glow colour"] = "Farbe der Bann-Hervorhebung",
