    -- Action Bars
    ["Always shown"] = "Immer sichtbar",
    ["Mouseover"] = "Mouseover",
    ["In combat"] = "Im Kampf",
    ["Out of combat"] = "Außerhalb des Kampfes",
    ["Faded opacity"] = "Deckkraft (ausgeblendet)",
    ["Fade speed (sec.)"] = "Ausblend-Geschwindigkeit (Sek.)",
    ["|cffff5555Action Bars: leaving combat to restore Blizzard's bars…|r"] = "|cffff5555Aktionsleisten: stelle Blizzards Leisten nach Kampfende wieder her …|r",
    ["|cffaaaaaaOwn buttons for every action bar (1-5): real combat / mouseover show-hide, scale and grid layout, correct main-bar paging (druid/rogue/warrior/priest forms) and your keybinds. Move each in Edit Mode (/vedit). After disabling, /reload to fully restore Blizzard's bars.|r"] = "|cffaaaaaaEigene Buttons für jede Aktionsleiste (1-5): echtes Kampf-/Mouseover-Ein-/Ausblenden, Skalierung und Raster-Layout, korrektes Paging der Hauptleiste (Druiden-/Schurken-/Krieger-/Priester-Gestalten) und deine Tastenbelegungen. Jede im Edit Mode bewegen (/vedit). Nach dem Deaktivieren /reload für Blizzards Leisten.|r",
    ["Action Bar 1 (Main)"] = "Aktionsleiste 1 (Haupt)",
    ["Action Bar 2"] = "Aktionsleiste 2",
    ["Action Bar 3"] = "Aktionsleiste 3",
    ["Action Bar 4"] = "Aktionsleiste 4",
    ["Action Bar 5"] = "Aktionsleiste 5",
    ["Action Bar 6 (Extra)"] = "Aktionsleiste 6 (Extra)",
    ["Grow from"] = "Wachsen ab",
    ["Left edge (rightwards)"] = "Linker Kante (nach rechts)",
    ["Right edge (leftwards)"] = "Rechter Kante (nach links)",
    ["Rows grow"] = "Reihen wachsen",
    ["Mouseover reveals all mouseover bars"] = "Mouseover zeigt alle Mouseover-Leisten",
    ["Hovering ANY mouseover bar shows every bar set to mouseover at once."] = "Das Überfahren EINER Mouseover-Leiste blendet alle auf Mouseover gestellten Leisten gleichzeitig ein.",
    ["Button text styling"] = "Button-Text-Gestaltung",
    ["|cffaaaaaaColours and fine offsets for the button texts, on every bar.|r"] = "|cffaaaaaaFarben und Fein-Versätze für die Button-Texte, auf allen Leisten.|r",
    ["Keybind text colour"] = "Tastenkürzel-Farbe",
    ["Macro text colour"] = "Makrotext-Farbe",
    ["Count text colour"] = "Anzahl-Farbe",
    ["Keybind offset X"] = "Kürzel Versatz X",
    ["Keybind offset Y"] = "Kürzel Versatz Y",
    ["Macro offset X"] = "Makro Versatz X",
    ["Macro offset Y"] = "Makro Versatz Y",
    ["Count offset X"] = "Anzahl Versatz X",
    ["Count offset Y"] = "Anzahl Versatz Y",
    ["0 = use the game's default size."] = "0 = Standardgröße des Spiels verwenden.",
    ["Vertical layout"] = "Vertikale Anordnung",
    ["Reverse order"] = "Reihenfolge umkehren",
    ["Hide keybind text"] = "Tastenkürzel ausblenden",
    ["Hide macro text"] = "Makrotext ausblenden",
    ["|cff9b6cffButton border / icon style lives in the Dark Skin module (Action Bars > Bar style): square, accent edge, shadow and more.|r"] = "|cff9b6cffButton-Rahmen / Icon-Stil sind im Dark-Skin-Modul (Action Bars > Bar-Stil): quadratisch, Akzentrahmen, Schatten und mehr.|r",
    ["Game Menu"] = "Spielmenü",
    ["Game menu: VuloUI look"] = "Spielmenü: VuloUI-Optik",
    ["Restyles the Escape menu to match the addon look: dark panel, flat buttons, accent title. Changing this needs a /reload."] = "Gestaltet das Escape-Menü im Addon-Stil: dunkles Panel, flache Buttons, Akzent-Titel. Änderung erfordert /reload.",
    ["Game menu: VuloClassicUI button"] = "Spielmenü: VuloClassicUI-Knopf",
    ["Adds a VuloClassicUI button to the Escape menu that opens the options window. Turning this off needs a /reload."] = "Fügt dem Escape-Menü einen VuloClassicUI-Knopf hinzu, der das Optionsfenster öffnet. Ausschalten erfordert /reload.",
    ["Hide the FPS / latency bar"] = "FPS-/Latenz-Leiste ausblenden",
    ["Hides Blizzard's small green performance (FPS / latency) bar."] = "Blendet Blizzards kleine grüne Leistungsanzeige (FPS/Latenz) aus.",
    ["Micro menu style"] = "Micromenü-Stil",
    ["World map"] = "Weltkarte",
    ["Friends list"] = "Freundesliste",
    ["Group finder"] = "Gruppensuche",
    ["Bag bar style"] = "Taschenleisten-Stil",
    ["Key ring"] = "Schlüsselbund",
    ["Timer decimals below 10 seconds"] = "Timer-Kommastelle unter 10 Sekunden",
    ["Interrupted by %s"] = "Unterbrochen von %s",
    ["Value + percent"] = "Wert + Prozent",
    ["Value + percent layout"] = "Anordnung Wert + Prozent",
    ["Short values (12.3k)"] = "Kurzwerte (12.3k)",
    ["Show percent sign"] = "Prozentzeichen anzeigen",
    ["Smooth health changes"] = "Weiche Lebensänderungen",
    ["The bar glides to the new value; a bright trail marks health draining away."] = "Der Balken gleitet zum neuen Wert; eine helle Spur markiert gerade verlorenes Leben.",
    ["Tint background with bar colour"] = "Hintergrund in Balkenfarbe tönen",
    ["The empty part of the bar shows a darkened shade of the bar colour instead of plain dark grey."] = "Der leere Teil des Balkens zeigt eine abgedunkelte Variante der Balkenfarbe statt einfachem Dunkelgrau.",

    ["Glow at the bar edge"] = "Leuchten an der Balkenkante",
    ["A soft glow rides the end of the fill, tinted in the bar's own colour. Also applies to the cast bar."] = "Ein weiches Leuchten begleitet das Ende der Füllung, getönt in der Farbe des Balkens. Gilt auch für die Zauberleiste.",
    ["Edge glow width"] = "Breite des Kantenleuchtens",
    ["Rounded bar corners"] = "Abgerundete Balkenecken",
    ["Clips the fill and background to a rounded shape. The line border stays square, so a thin border may show slightly at the corners."] = "Beschneidet Füllung und Hintergrund rund. Der Linienrahmen bleibt eckig, daher kann ein dünner Rahmen an den Ecken leicht hervorschauen.",
    ["Overall plate scale (%)"] = "Gesamtgröße der Plates (%)",
    ["Scales every plate at once, on top of each individual size."] = "Skaliert alle Plates gemeinsam, zusätzlich zu den Einzelgrößen.",
    ["Vertical offset"] = "Höhenversatz",
    ["Moves every plate up or down relative to its unit."] = "Verschiebt jedes Plate relativ zu seiner Einheit nach oben oder unten.",

    ["Font outline"] = "Schriftkontur",
    ["How plate text is lifted off the background."] = "Wie sich der Text der Plates vom Hintergrund abhebt.",
    ["Thick outline"] = "Dicke Kontur",
    ["Show level"] = "Stufe anzeigen",
    ["Shows the unit level to the left of the name; ?? means the level is far above yours."] = "Zeigt die Stufe links vom Namen; ?? bedeutet, die Stufe liegt weit über deiner.",
    ["Mark rare and elite"] = "Selten und Elite kennzeichnen",
    ["Appends a rank to the level and turns it gold: + elite, R rare, R+ rare elite, B world boss."] = "Hängt einen Rang an die Stufe an und färbt sie golden: + Elite, R selten, R+ selten-elite, B Weltboss.",
    ["Level size"] = "Größe der Stufe",
    ["0 = uses the name size."] = "0 = nutzt die Namensgröße.",

    ["Emphasise casting units"] = "Zaubernde Einheiten hervorheben",
    ["While a unit casts, its plate grows a little and stays readable even when something else is targeted."] = "Während eine Einheit zaubert, wächst ihr Plate etwas und bleibt lesbar, auch wenn etwas anderes anvisiert ist.",
    ["Casting scale (%)"] = "Größe beim Zaubern (%)",
    ["Casting opacity (%)"] = "Deckkraft beim Zaubern (%)",

    ["Colour border by school"] = "Rahmen nach Zauberart färben",
    ["Aura borders take the colour of their school: magic blue, curse purple, disease orange, poison green."] = "Aura-Rahmen nehmen die Farbe ihrer Zauberart an: Magie blau, Fluch lila, Krankheit orange, Gift grün.",
    ["Flash before running out"] = "Blinken vor Ablauf",
    ["The icon pulses over the last part of its duration, so you can see when to refresh."] = "Das Symbol pulsiert im letzten Teil seiner Laufzeit, damit du siehst, wann du nachlegen musst.",
    ["Flash below (%)"] = "Blinken ab (%)",

    ["Your Own Debuffs"] = "Deine eigenen Debuffs",
    ["|cffaaaaaaA separate row for the harmful auras you cast yourself - your damage-over-time timers, kept away from everything else on the target.|r"] = "|cffaaaaaaEine eigene Reihe für die schädlichen Auren, die du selbst gewirkt hast – deine Schaden-über-Zeit-Timer, getrennt von allem anderen auf dem Ziel.|r",
    ["Show your own debuffs (separate row)"] = "Eigene Debuffs zeigen (eigene Reihe)",
    ["Max icons"] = "Maximale Symbole",
    ["Icons per line"] = "Symbole pro Zeile",
    ["0 = one line. Otherwise the row wraps after this many icons."] = "0 = eine Zeile. Sonst bricht die Reihe nach so vielen Symbolen um.",
    -- Erinnerungen
    ["Reminders"] = "Erinnerungen",
    ["|cffaaaaaaShows a short row of icons for what you are missing right now. Out of combat a click casts or uses the fix; hovering explains what it wants. The row holds still during combat.|r"] = "|cffaaaaaaZeigt in einer kurzen Symbolreihe, was dir gerade fehlt. Außerhalb des Kampfes wirkt ein Klick den Zauber bzw. benutzt den Gegenstand; ein Zeigen darauf erklärt, worum es geht. Im Kampf bleibt die Reihe unverändert stehen.|r",
    ["Also warn about empty equipment slots"] = "Auch vor leeren Ausrüstungsplätzen warnen",
    ["Off by default: a ring, trinket or cloak is often legitimately empty while levelling."] = "Standardmäßig aus: Ring, Schmuckstück oder Umhang sind beim Aufsteigen oft berechtigt leer.",
    ["Shows what you are missing - class buffs, weapon enchants, food, stance, pet, ammo, durability, empty gear slots and unspent talent points."] = "Zeigt, was dir fehlt – Klassenbuffs, Waffenverzauberungen, Nahrung, Haltung, Begleiter, Munition, Haltbarkeit, leere Ausrüstungsplätze und nicht vergebene Talentpunkte.",
    ["What to watch"] = "Worauf achten",
    ["Class buffs"] = "Klassenbuffs",
    ["Weapon enchants"] = "Waffenverzauberungen",
    ["Stance and aura"] = "Haltung und Aura",
    ["Food and flask"] = "Nahrung und Fläschchen",
    ["Ammo, durability, gear, talents"] = "Munition, Haltbarkeit, Ausrüstung, Talente",
    ["Most icons at once"] = "Höchstens Symbole gleichzeitig",
    ["Anything past this is bundled into a single counter instead of adding another icon."] = "Alles darüber hinaus wird zu einem einzelnen Zähler gebündelt, statt ein weiteres Symbol anzuhängen.",
    ["Show labels"] = "Beschriftungen zeigen",
    ["Settle time (seconds)"] = "Beruhigungszeit (Sekunden)",
    ["How long something must stay missing before an icon appears. Stops it flickering between casts."] = "Wie lange etwas fehlen muss, bevor ein Symbol erscheint. Verhindert Flackern zwischen zwei Zaubern.",
    ["Warn when under (seconds)"] = "Warnen ab Restzeit (Sekunden)",
    ["Also warn while a buff or weapon enchant is about to run out. 0 = only warn when it is gone."] = "Warnt auch, während ein Buff oder eine Waffenverzauberung bald ausläuft. 0 = erst warnen, wenn sie weg ist.",
    ["Durability below (%)"] = "Haltbarkeit unter (%)",
    ["Ammo below"] = "Munition unter",
    ["Quiet while resting"] = "Ruhe in Erholungszonen",
