    ["Unspent talent points: %d"] = "Nicht vergebene Talentpunkte: %d",

    -- Arena PvP extras
    ["Racials"] = "Volksfähigkeiten",
    ["Racial Cooldowns"] = "Volksfähigkeiten-Cooldowns",
    ["Shows the opponent's racial ability and its cooldown once they use it. These are this expansion's cooldowns, and no racial shares one with the PvP trinket yet."] = "Zeigt die Volksfähigkeit des Gegners und deren Abklingzeit, sobald er sie einsetzt. Es sind die Werte dieser Erweiterung – und noch teilt sich keine Volksfähigkeit eine Abklingzeit mit dem PvP-Schmuckstück.",
    ["Show racial cooldown"] = "Volksfähigkeiten-Cooldown zeigen",
    ["Shadow Sight"] = "Schattensicht",
    ["Shadow Sight up"] = "Schattensicht verfügbar",
    ["Shadow Sight up - next in %d s"] = "Schattensicht verfügbar – nächste in %d s",
    ["Shadow Sight in %d s"] = "Schattensicht in %d s",
    ["Counts down the arena orbs: the first pair appears 95 seconds after the gates open, and each one returns 122 seconds after it is taken."] = "Zählt die Arenakugeln herunter: Das erste Paar erscheint 95 Sekunden nach dem Öffnen der Tore, jede weitere 122 Sekunden nach dem Aufnehmen.",
    ["Show Shadow Sight timer"] = "Schattensicht-Timer zeigen",
    ["Aura on the class icon"] = "Aura auf dem Klassensymbol",
    ["Puts the single most relevant aura on the opponent's class icon: an immunity outranks crowd control, which outranks a defensive, which outranks an offensive cooldown."] = "Legt die eine wichtigste Aura des Gegners auf sein Klassensymbol: Immunität schlägt Kontrolle, Kontrolle schlägt Verteidigung, Verteidigung schlägt Angriffs-Cooldown.",
    ["Show aura on the class icon"] = "Aura auf dem Klassensymbol zeigen",
    ["Crowd control only"] = "Nur Kontrolleffekte",
    ["Dispels"] = "Entzaubern",
    ["Dispel Cooldowns"] = "Entzauber-Cooldowns",
    ["|cffaaaaaaMost dispels have no cooldown in this expansion, so only Mass Dispel and the felhunter's Devour Magic can ever show up here.|r"] = "|cffaaaaaaDie meisten Entzauber-Zauber haben in dieser Erweiterung gar keine Abklingzeit – hier können daher nur Massenbannung und Magie verschlingen des Teufelsjägers auftauchen.|r",
    ["Show dispel cooldown"] = "Entzauber-Cooldown zeigen",
    ["Range"] = "Reichweite",
    ["Fades the frame while the opponent is out of reach, measured with a spell your class knows rather than a fixed distance."] = "Blendet das Fenster ab, solange der Gegner außer Reichweite ist – gemessen an einem Zauber deiner Klasse statt an einer festen Entfernung.",
    ["Fade out-of-range opponents"] = "Gegner außer Reichweite abblenden",

    ["Discard changes and revert every window to the last save point, or to how it was when Edit Mode opened."] = "Verwirft die Änderungen und stellt jedes Fenster auf den letzten Speicherpunkt zurück – oder auf den Stand beim Öffnen des Edit-Modus.",
    ["Discard all changes made since the last save?"] = "Alle seit dem letzten Speichern vorgenommenen Änderungen verwerfen?",

    ["Grey out when you walk out of range"] = "Ausgrauen, wenn du außer Reichweite bist",
    ["Drains the colour while you are outside a totem's radius, and restores it when you step back in. Recognised from the buff the totem puts on you, so totems that grant no buff (Searing, Magma, Tremor, ...) always stay lit."] = "Nimmt die Farbe heraus, solange du außerhalb des Radius eines Totems bist, und gibt sie zurück, sobald du wieder hineingehst. Erkannt am Buff, den das Totem auf dich legt – Totems ohne Buff (Feuerstoß, Magma, Erdstoß …) bleiben deshalb immer farbig.",

    ["Limit to"] = "Beschränken auf",
    ["Everything"] = "Alles",
    ["Only mine"] = "Nur eigene",
    ["Only removable"] = "Nur entfernbare",
    ["Narrows this row to auras you cast yourself, or to ones that can be removed."] = "Beschränkt diese Reihe auf Auren, die du selbst gewirkt hast, oder auf entfernbare.",
    ["Nudges every aura row at once, on top of each row's own offset."] = "Verschiebt alle Auren-Reihen gemeinsam, zusätzlich zum eigenen Versatz jeder Reihe.",
    ["Share of the remaining duration at which the pulse starts."] = "Anteil der Restlaufzeit, ab dem das Pulsieren beginnt.",
    ["Own colour while your interrupt is ready"] = "Eigene Farbe solange dein Interrupt bereit ist",
    ["Interruptible casts paint in this colour while your interrupt is off cooldown — kick at will."] = "Unterbrechbare Zauber färben sich so, solange dein Interrupt nicht auf Cooldown ist — freie Bahn zum Kicken.",
    ["Interrupt-ready colour"] = "Interrupt-bereit-Farbe",
    ["Own colour while channelling"] = "Eigene Farbe beim Kanalisieren",
    ["Channel colour"] = "Kanalisieren-Farbe",
    ["Own colour when the cast targets YOU"] = "Eigene Farbe wenn der Zauber auf DICH zielt",
    ["The bar turns this colour while the caster's target is you."] = "Der Balken nimmt diese Farbe an, solange das Ziel des Zaubernden du bist.",
    ["Targets-you colour"] = "Zielt-auf-dich-Farbe",
    ["Show who interrupted"] = "Unterbrecher anzeigen",
    ["The interrupt flash shows the name of whoever landed the interrupt."] = "Das Unterbrechungs-Aufblitzen zeigt den Namen dessen, der den Interrupt gelandet hat.",
    ["On: 9.9, 3.4 … Off: whole seconds (9, 3)."] = "An: 9.9, 3.4 … Aus: ganze Sekunden (9, 3).",
    ["Modern puts the real bag buttons on a flat dark strip in the VuloUI look — opening, swapping and tooltips stay identical."] = "Modern setzt die echten Taschenknöpfe auf eine flache dunkle Leiste im VuloUI-Look — Öffnen, Tauschen und Tooltips bleiben identisch.",
    ["Modern replaces Blizzard's buttons with a flat dark icon strip in the VuloUI look. Clicks and tooltips stay identical."] = "Modern ersetzt Blizzards Knöpfe durch eine flache dunkle Icon-Leiste im VuloUI-Look. Klicks und Tooltips bleiben identisch.",
    ["Classic (Blizzard buttons)"] = "Klassisch (Blizzard-Knöpfe)",
    ["Modern (flat icon strip)"] = "Modern (flache Icon-Leiste)",
    ["Hide the micro menu"] ="Micromenü ausblenden",
    ["Hides the row of menu buttons (character, spellbook, …)."] = "Blendet die Reihe der Menü-Knöpfe aus (Charakter, Zauberbuch, …).",
    ["Hide the bag bar"] = "Taschenleiste ausblenden",
    ["Hides the backpack and bag slots."] = "Blendet den Rucksack und die Taschenplätze aus.",
    ["|cff9b6cffThe micro menu, bag bar, FPS/latency bar and the XP bar below are movable in Edit Mode (/vedit) like the action bars.|r"] = "|cff9b6cffMicromenü, Taschenleiste, FPS-/Latenz-Leiste und die Erfahrungsleiste unten sind im Edit Mode (/vedit) bewegbar wie die Aktionsleisten.|r",
    ["Micro menu"] = "Micromenü",
