    ["Execute line"] = "Hinrichten-Linie",
    ["A thin marker line on the bar at the chosen health percentage (e.g. 20 for Execute)."] = "Eine dünne Markierungslinie auf der Leiste beim gewählten Lebensprozentwert (z. B. 20 für Hinrichten).",
    ["Execute line only on your target"] = "Hinrichten-Linie nur auf deinem Ziel",
    ["Execute line colour"] = "Hinrichten-Linien-Farbe",
    ["Execute line percent"] = "Hinrichten-Linie Prozent",
    ["Show remaining cast time"] = "Verbleibende Zauberzeit anzeigen",
    ["Own colour while your interrupt is on cooldown"] = "Eigene Farbe, solange dein Unterbrechen auf Cooldown ist",
    ["Interruptible casts paint differently while YOUR interrupt ability is still on cooldown — you see at a glance whether kicking is even possible."] = "Unterbrechbare Zauber färben sich anders, solange DEINE Unterbrechen-Fähigkeit noch auf Cooldown ist — du siehst sofort, ob ein Kick überhaupt möglich ist.",
    ["Interrupt-on-cooldown colour"] = "Farbe bei Unterbrechen-Cooldown",
    ["Own bar colour on your target"] = "Eigene Leisten-Farbe auf deinem Ziel",
    ["Your current target's health bar uses this colour instead of reaction / class / threat colours."] = "Die Lebensleiste deines aktuellen Ziels nutzt diese Farbe statt Reaktions-/Klassen-/Bedrohungs-Farben.",
    ["Target bar colour"] = "Ziel-Leisten-Farbe",
    ["Mouseover highlight"] = "Mouseover-Aufhellung",
    ["Lightens the health bar of the plate under your mouse cursor."] = "Hellt die Lebensleiste der Plakette unter deinem Mauszeiger auf.",
    ["Target plate scale"] = "Ziel-Plaketten-Skalierung",
    ["Your target's plate is drawn this much larger (100 = off)."] = "Die Plakette deines Ziels wird um diesen Faktor größer gezeichnet (100 = aus).",
    ["Behaviour"] = "Verhalten",
    ["|cffaaaaaaThese are the game's own nameplate settings, changed live (not part of the profile). Not changeable in combat.|r"] = "|cffaaaaaaDas sind die spieleigenen Namensplaketten-Einstellungen, live geändert (nicht Teil des Profils). Im Kampf nicht änderbar.|r",
    ["Plate motion"] = "Plaketten-Anordnung",
    ["Overlapping"] = "Überlappend",
    ["Stacking"] = "Gestapelt",
    ["Stacked spacing"] = "Stapel-Abstand",
    ["Vertical distance between stacked plates (a tenth of the game value)."] = "Vertikaler Abstand gestapelter Plaketten (ein Zehntel des Spielwerts).",
    ["Line-of-sight opacity"] = "Sichtlinien-Deckkraft",
    ["Opacity of plates whose unit is out of your line of sight."] = "Deckkraft von Plaketten, deren Einheit außerhalb deiner Sichtlinie ist.",
    ["Plate view distance"] = "Plaketten-Sichtweite",
    ["|cffaaaaaaWhile the key is held (or your target matches), the main bar shows the chosen bar's abilities instead. Fully secure — works in combat.|r"] = "|cffaaaaaaSolange die Taste gehalten wird (oder dein Ziel passt), zeigt die Hauptleiste stattdessen die Fähigkeiten der gewählten Leiste. Vollständig sicher — funktioniert im Kampf.|r",
    ["Shift held"] = "Shift gehalten",
    ["Ctrl held"] = "Strg gehalten",
    ["Alt held"] = "Alt gehalten",
    ["Friendly target"] = "Freundliches Ziel",
    ["Hostile target"] = "Feindliches Ziel",
    ["Group visibility"] = "Gruppen-Sichtbarkeit",
    ["Always"] = "Immer",
    ["Only in a group"] = "Nur in einer Gruppe",
    ["Only in a party"] = "Nur in einer 5er-Gruppe",
    ["Only solo"] = "Nur solo",
    ["Hide when mounted"] = "Ausblenden wenn aufgesessen",
    ["Hide without target"] = "Ausblenden ohne Ziel",
    ["Hide without enemy target"] = "Ausblenden ohne feindliches Ziel",
    ["Quick keybind mode (/vkb)"] = "Schnell-Belegen-Modus (/vkb)",
    ["Hover an action button and press a key to bind it. Hidden bars are shown while binding."] = "Maus auf einen Aktionsbutton und Taste drücken = belegt. Versteckte Leisten werden beim Belegen eingeblendet.",
    ["Swipe colour"] = "Wischer-Farbe",
    ["Icon opacity on cooldown"] = "Icon-Deckkraft bei Cooldown",
    ["Dims the whole icon while the ability is on cooldown (100 = off)."] = "Dunkelt das ganze Icon ab, solange die Fähigkeit auf Cooldown ist (100 = aus).",
    ["Show cooldown numbers"] = "Cooldown-Zahlen anzeigen",
    ["The game's own countdown numbers on cooldowns (a game setting, changed live)."] = "Die spieleigenen Countdown-Zahlen auf Cooldowns (eine Spieleinstellung, wird live geändert).",
    ["|cffaaaaaaApplies to every action bar.|r"] = "|cffaaaaaaGilt für alle Aktionsleisten.|r",
    ["Cooldown swipe opacity"] = "Cooldown-Wischer-Deckkraft",
    ["How dark the cooldown sweep overlay is (0 = invisible)."] = "Wie dunkel die Cooldown-Überblendung ist (0 = unsichtbar).",
    ["Desaturate icons on cooldown"] = "Icons bei Cooldown entsättigen",
    ["Out-of-range colouring"] = "Außer-Reichweite-Färbung",
    ["Tints the whole icon while your target is out of range."] = "Färbt das ganze Icon ein, solange dein Ziel außer Reichweite ist.",
    ["Tooltips"] = "Tooltips",
    ["Hide in combat"] = "Im Kampf ausblenden",
    ["Hide always"] = "Immer ausblenden",
    ["A movable, resizable experience bar with rested overlay. Hidden at max level. Replaces Blizzard's bar while on."] = "Eine bewegbare Erfahrungsleiste mit einstellbarer Größe und Erholt-Anzeige. Auf Maximalstufe ausgeblendet. Ersetzt Blizzards Leiste, solange aktiv.",
    ["Hide Blizzard's XP / reputation bar"] = "Blizzards Erfahrungs-/Rufleiste ausblenden",
    ["Removes the leftover blue experience / reputation bar under the action bar."] = "Entfernt die übrige blaue Erfahrungs-/Rufleiste unter der Aktionsleiste.",
    ["Stance bar"] = "Haltungsleiste",
    ["Pet bar"] = "Begleiterleiste",
    ["Takes over every action bar with its own movable frames: real combat/mouseover show-hide, scale and grid layout per bar, correct main-bar paging (druid/rogue/warrior/priest forms) and your keybinds. EXPERIMENTAL — test ability clicks and paging in combat; /reload after disabling."] = "Übernimmt jede Aktionsleiste mit eigenem, frei beweglichem Rahmen: echtes Ein-/Ausblenden (Kampf/Mouseover), Skalierung und Raster-Layout pro Leiste, korrektes Paging der Hauptleiste (Druiden-/Schurken-/Krieger-/Priester-Gestalten) und deine Tastenbelegungen. EXPERIMENTELL — teste Fähigkeiten-Klicks und Paging im Kampf; /reload nach dem Deaktivieren.",
    ["|cffffcc00Action Bars disabled — type /reload to fully restore the default bars.|r"] = "|cffffcc00Aktionsleisten deaktiviert — /reload eingeben, um die Standardleisten vollständig wiederherzustellen.|r",
    ["Buttons per row"] = "Buttons pro Reihe",
    ["Button spacing"] = "Button-Abstand",
    ["Reset ALL VuloClassicUI settings for every character on this account? This cannot be undone."] = "Wirklich ALLE Einstellungen von VuloClassicUI für jeden Charakter dieses Accounts zurücksetzen? Das lässt sich nicht rückgängig machen.",
    ["Swing Timer switched off: it only tracks melee auto-attacks, which this character's talents do not use."] = "Waffen-Swingtimer abgeschaltet: Er verfolgt nur Nahkampf-Autoangriffe, die dieser Charakter mit seinen Talenten nicht nutzt.",
    ["|cffff5555Settings migration %s failed:|r %s"] = "|cffff5555Einstellungs-Migration %s fehlgeschlagen:|r %s",
    ["Plays a raid warning sound the moment an opponent uses their PvP trinket."] = "Spielt einen Schlachtzugswarnton, sobald ein Gegner seinen PvP-Schmuck benutzt.",
    ["Flashes the icon briefly when an opponent uses their PvP trinket."] = "Lässt das Symbol kurz aufleuchten, wenn ein Gegner seinen PvP-Schmuck benutzt.",
    ["Icon gap"] = "Symbolabstand",
    ["Distance between the icon and the bar."] = "Abstand zwischen Symbol und Leiste.",
    ["Accent colour"] = "Akzentfarbe",
    ["Used for the bar while the fill mode is not a texture, and for channelled casts on Blizzard's own castbar."] = "Wird für die Leiste verwendet, solange der Füllmodus keine Textur ist, und für Kanalzauber auf Blizzards eigener Zauberleiste.",
    ["Cast finished"] = "Zauber beendet",
    ["The bar flashes in this colour when a cast completes."] = "Die Leiste blitzt in dieser Farbe auf, wenn ein Zauber fertig wird.",
    ["Cast interrupted"] = "Zauber unterbrochen",
    ["The bar flashes in this colour when a cast is interrupted or fails."] = "Die Leiste blitzt in dieser Farbe auf, wenn ein Zauber unterbrochen wird oder fehlschlägt.",
    ["Fade-in time"] = "Einblendzeit",
    ["How long an icon takes to appear. 0 makes it show instantly."] = "Wie lange ein Symbol zum Erscheinen braucht. 0 zeigt es sofort.",
    [" and %d item(s)"] = " und %d Gegenstand/Gegenstände",
    ["/vlfg toggles the group board."] = "/vlfg öffnet die Gruppensuche.",
    ["Auto-apply a lure when the pole has none"] = "Köder automatisch anlegen, wenn die Angel keinen hat",
    ["Auto-equip a fishing pole if none is worn"] = "Angel automatisch anlegen, wenn keine ausgerüstet ist",
    ["Auto-loot while fishing"] = "Auto-Plündern während des Angelns",
    ["Bags are full — some items were left in the mail."] = "Taschen voll — einige Gegenstände blieben in der Post.",
    ["Boost fishing sound (hear the bite clearly)"] = "Angel-Sound verstärken (Biss klar hören)",
    ["Burning Crusade Dungeons"] = "BC-Dungeons",
    ["Burning Crusade Raids"] = "BC-Schlachtzüge",
    ["Can't change the fishing key in combat."] = "Angel-Taste kann im Kampf nicht geändert werden.",
    ["Classic Dungeons"] = "Classic-Dungeons",
