    ["Slot %d"] = "Slot %d",
    ["Speed (seconds between actions)"] = "Tempo (Sekunden zwischen Aktionen)",
    ["Take item attachments"] = "Gegenstands-Anhänge nehmen",
    ["Take money"] = "Geld nehmen",
    ["While the bobber is out, maxes effect + master volume and dims music/ambience so the splash is easy to hear. Restored when you reel in."] = "Während der Bobber draußen ist, werden Effekt- + Master-Lautstärke maximiert und Musik/Ambiente abgesenkt, damit das Platschen gut hörbar ist. Wird beim Einholen wiederhergestellt.",
    ["While the bobber is out, the same key interacts with it to reel in. Needs soft-target interaction, which is enabled only while fishing and restored afterwards."] = "Während der Bobber draußen ist, holt dieselbe Taste ihn ein. Braucht Soft-Target-Interaktion — wird nur beim Angeln aktiviert und danach wiederhergestellt.",
    ["Whisper"] = "Flüstern",
    ["Who"] = "Wer",
    ["Your characters"] = "Deine Charaktere",
    ["now"] = "jetzt",
    ["|cffaaaaaaAdds an 'Open All' button to the mailbox. It takes every attachment and coin, skipping CoD and GM mail. Shift-click the button to ignore the filters and take everything.|r"] = "|cffaaaaaaFügt dem Briefkasten einen 'Alle öffnen'-Knopf hinzu. Nimmt alle Anhänge und Münzen, überspringt Nachnahme- und GM-Post. Shift-Klick ignoriert die Filter und nimmt alles.|r",
    ["|cffaaaaaaItems or macros also used by the key while fishing — only when ready (off cooldown, buff missing, conditions met), then it goes back to casting. Type an item name or ID, shift-click an item into the box, or paste a /macro.|r"] = "|cffaaaaaaItems oder Makros, die die Taste beim Angeln mitbenutzt — nur wenn bereit (kein Cooldown, Buff fehlt, Bedingungen erfüllt), danach wird wieder ausgeworfen. Item-Name oder -ID eintippen, ein Item per Shift-Klick einfügen, oder ein /Makro einfügen.|r",
    ["|cffaaaaaaOne key does it all: cast, reel in, and apply a lure — then auto-loots. Set a key below, face some water, and press it.|r"] = "|cffaaaaaaEine Taste macht alles: auswerfen, einholen und Köder anlegen — danach Auto-Plündern. Unten eine Taste festlegen, aufs Wasser schauen, drücken.|r",
    ["|cffff5555Arena submodule OnDisable error:|r %s"] = "|cffff5555Arena-Submodul OnDisable-Fehler:|r %s",
    -- Patch notes, module descriptions, anchors, embedded engine (sweep 2026-07)
    ["Languages"] = "Sprachen",
    ["Reminders (new module)"] = "Erinnerungen (neues Modul)",
    ["Arena"] = "Arena",
    ["Totems"] = "Totems",
    ["Fixes"] = "Fixes",
    ["Resource Bar"] = "Ressourcenleiste",
    ["Settings Window"] = "Einstellungsfenster",
    ["Character Window"] = "Charakterfenster",
    ["Nameplates (German: Namensplaketten)"] = "Namensplaketten",
    ["German client"] = "Deutscher Client",
    ["Performance"] = "Performance",
    ["Equipment Sets"] = "Ausrüstungssets",
    ["Spanish, French, Italian, Portuguese, Russian and Korean. All six are complete — every one of the 2244 texts is translated, nothing falls back to English. Spanish also serves Latin American clients. Choose your language under General, or leave it on Auto."] = "Spanisch, Französisch, Italienisch, Portugiesisch, Russisch und Koreanisch. Alle sechs sind vollständig — jeder der 2244 Texte ist übersetzt, nichts fällt auf Englisch zurück. Spanisch bedient auch lateinamerikanische Clients. Wähle deine Sprache unter Allgemein oder lass sie auf Auto.",
    ["Shows what you are missing before a pull: weapon oils and stones, blessings, food and flask buffs, the aura or stance you forgot to set. Click a reminder to cast or use it. Off by default, found under Quality of Life."] = "Zeigt vor einem Pull, was dir fehlt: Waffenöle und -steine, Segen, Essens- und Fläschchenbuffs, die Aura oder Haltung, die du vergessen hast. Klicke eine Erinnerung, um sie zu wirken oder zu benutzen. Standardmäßig aus, zu finden unter Lebensqualität.",
    ["A spark at the bar's fill point, rounded corners, aura rows you can assign freely, and your own damage-over-time effects on a row of their own."] = "Ein Funke am Füllpunkt der Leiste, abgerundete Ecken, frei belegbare Aura-Reihen und deine eigenen DoTs in einer separaten Reihe.",
    ["Aura borders take the colour of their spell school, and an aura flashes shortly before it runs out."] = "Aura-Rahmen nehmen die Farbe ihrer Zauberschule an, und eine Aura blinkt kurz, bevor sie ausläuft.",
    ["Level and elite text, plus overall scale and vertical offset per plate."] = "Stufen- und Elite-Text, dazu Gesamtskalierung und vertikaler Versatz pro Plakette.",
    ["A window can take its width or height from another window and keep it."] = "Ein Fenster kann seine Breite oder Höhe von einem anderen Fenster übernehmen und behalten.",
    ["Save button. While dragging, hold Shift to lock one axis."] = "Speichern-Button. Halte beim Ziehen Shift, um eine Achse zu sperren.",
    ["Trinket and racial cooldowns, Shadow Sight timer, a ring on the class icon for the most important aura, and range checking."] = "Trinket- und Volksfähigkeiten-Cooldowns, Schattensicht-Timer, ein Ring am Klassen-Icon für die wichtigste Aura und Reichweiten-Check.",
    ["Totem icons grey out once you leave the totem's range and regain their colour when you come back."] = "Totem-Icons werden grau, sobald du die Reichweite des Totems verlässt, und bekommen ihre Farbe zurück, wenn du zurückkommst.",
    ["The character sheet and spellbook open in combat again. The action bars no longer set a protected field from our own code, which was the real cause."] = "Charakterfenster und Zauberbuch öffnen sich im Kampf wieder. Die Aktionsleisten setzen kein geschütztes Feld mehr aus unserem eigenen Code — das war die eigentliche Ursache.",
    ["The melee swing timer is off by default and only loads for melee classes and specialisations."] = "Der Nahkampf-Swingtimer ist standardmäßig aus und lädt nur für Nahkampfklassen und -spezialisierungen.",
    ["Sliders got a proper look: soft edges, an inner shadow and a smoother hover."] = "Slider haben jetzt einen ordentlichen Look: weiche Kanten, ein Innenschatten und ein sanfteres Hover.",
    ["Own icons for the three collection pages, and class icons on the class tabs."] = "Eigene Icons für die drei Sammlungsseiten und Klassen-Icons auf den Klassen-Tabs.",
    ["Anchor a window to another one's edge (left/right/top/bottom) — the gap is kept edge-to-edge, so it survives either window being resized."] = "Verankere ein Fenster an der Kante eines anderen (links/rechts/oben/unten) — der Abstand wird Kante zu Kante gehalten und bleibt erhalten, wenn eines der Fenster seine Größe ändert.",
    ["Click-to-anchor: press \"Anchor to window...\" in a window's panel, then click the target window. Loop and self-anchor are blocked."] = "Klick-Ankern: Drücke 'An Fenster ankern...' im Panel eines Fensters und klicke dann das Zielfenster an. Schleifen und Selbst-Ankern sind blockiert.",
    ["While dragging, alignment lines now also show the pixel distance to the window you line up with."] = "Beim Ziehen zeigen die Ausrichtungslinien jetzt auch den Pixelabstand zu dem Fenster, an dem du dich ausrichtest.",
    ["Discard button — snapshots the layout when you open Edit Mode and restores it (positions, scale, anchors and links) if you discard."] = "Verwerfen-Button — macht beim Öffnen des Edit Mode einen Schnappschuss des Layouts und stellt ihn (Positionen, Skalierung, Anker und Verknüpfungen) beim Verwerfen wieder her.",
    ["The drag area now covers the whole dark chat panel down to the edit box, not just the narrow message strip."] = "Der Ziehbereich deckt jetzt das ganze dunkle Chat-Panel bis zum Eingabefeld ab, nicht nur den schmalen Nachrichtenstreifen.",
    ["Fixed right-click on the chat window not opening its settings panel in Edit Mode."] = "Behoben: Rechtsklick auf das Chatfenster öffnete im Edit Mode nicht sein Einstellungs-Panel.",
    ["Interrupt help on the cast bar: own colours while your interrupt is on cooldown or ready, a tick marking where it comes back mid-cast, a shield on uninterruptible casts and an interrupt flash that can show who landed the kick."] = "Unterbrechungshilfe auf der Castbar: eigene Farben, während dein Unterbrechungszauber auf Cooldown oder bereit ist, eine Markierung, die zeigt, wo er mitten im Cast zurückkommt, ein Schild auf nicht unterbrechbaren Casts und ein Unterbrechungs-Blitz, der zeigen kann, wer den Kick gelandet hat.",
    ["Cast bar suite: icon side and scale, remaining time, own background, channel colour, a warning colour when the cast aims at YOU — and on your target the cast bar lines up flush with the health bar including its border."] = "Castbar-Paket: Icon-Seite und -Skalierung, Restzeit, eigener Hintergrund, Kanalisierungs-Farbe, eine Warnfarbe, wenn der Cast auf DICH zielt — und am Ziel schließt die Castbar bündig mit dem Lebensbalken samt Rahmen ab.",
    ["Execute line, target and mouseover effects, crowd control section, combo point shapes and placement, per-element position, size and text-size controls plus a font picker."] = "Execute-Linie, Ziel- und Mouseover-Effekte, Crowd-Control-Bereich, Formen und Platzierung der Kombopunkte, Position, Größe und Textgröße pro Element plus eine Schriftauswahl.",
    ["The options page carries a clickable live preview that stays pinned while you scroll — click any element to jump to its settings."] = "Die Optionsseite trägt eine klickbare Live-Vorschau, die beim Scrollen angeheftet bleibt — klicke ein Element an, um zu seinen Einstellungen zu springen.",
    ["Smooth health movement with a damage trail, value plus percent text layouts with short numbers, and a decimal toggle for aura timers."] = "Sanfte Lebensbewegung mit Schadensspur, Textlayouts mit Wert plus Prozent und Kurzzahlen sowie ein Dezimalstellen-Schalter für Aura-Timer.",
    ["Per-bar visibility conditions (instances, mounted, target, group), modifier paging, quick keybind mode (/vkb), a sixth bar, growth directions, button text styling and cooldown look options."] = "Sichtbarkeitsbedingungen pro Leiste (Instanzen, aufgesessen, Ziel, Gruppe), Seitenwechsel per Modifikator, Schnell-Tastenbelegungsmodus (/vkb), eine sechste Leiste, Wachstumsrichtungen, Button-Text-Gestaltung und Optionen für die Cooldown-Optik.",
    ["Micro menu and bag bar modern style: flat dark strips with an own monochrome icon set, plus world map, friends list, group finder, shop and key ring buttons."] = "Mikromenü und Taschenleiste im modernen Stil: flache dunkle Streifen mit eigenem monochromen Icon-Set, dazu Buttons für Weltkarte, Freundesliste, Gruppensuche, Shop und Schlüsselbund.",
    ["The experience bar width now adjusts in single steps."] = "Die Breite der Erfahrungsleiste lässt sich jetzt in Einzelschritten anpassen.",
    ["Visibility conditions, colour modes with gradient, background and border colours, smooth value changes, hash marks and threshold colouring."] = "Sichtbarkeitsbedingungen, Farbmodi mit Verlauf, Hintergrund- und Rahmenfarben, sanfte Wertänderungen, Markierungen und Schwellwert-Färbung.",
    ["Character sheet stats panel no longer bleeds into other tabs; loadout sidebar aligns with the modern character sheet."] = "Das Werte-Panel des Charakterfensters ragt nicht mehr in andere Tabs hinein; die Set-Sidebar richtet sich am modernen Charakterfenster aus.",
    ["Arena points calculator panel and button wear the addon look and dock beside the character sheet."] = "Arenapunkte-Rechner-Panel und -Button tragen den Addon-Look und docken neben dem Charakterfenster an.",
    ["The Escape menu now wears the dark addon look — flat buttons, accent title — and gains a VuloClassicUI button that opens the options window. Both have their own toggles under General."] = "Das Escape-Menü trägt jetzt den dunklen Addon-Look — flache Buttons, Akzent-Titel — und bekommt einen VuloClassicUI-Button, der das Optionsfenster öffnet. Beide haben eigene Schalter unter Allgemein.",
    ["The add friend dialog is skinned to match: dark panel, accent headline, dark input field and flat buttons."] = "Der Freund-hinzufügen-Dialog ist passend geskinnt: dunkles Panel, Akzent-Überschrift, dunkles Eingabefeld und flache Buttons.",
    ["Guild roster column header hover and click no longer stick out past the flat header row."] = "Die Spaltenüberschriften der Gildenliste stehen bei Hover und Klick nicht mehr über die flache Kopfzeile hinaus.",
    ["The combat log filter bar now shares the exact width and height of the chat tab row, flush with the panel edge."] = "Die Filterleiste des Kampflogs teilt jetzt exakt Breite und Höhe der Chat-Tab-Reihe, bündig mit der Panelkante.",
    ["After an update, a pulsing dot on the \"Patch Notes\" entry points at the new notes until you open them once — account wide, per version."] = "Nach einem Update weist ein pulsierender Punkt auf dem Eintrag 'Patch Notes' auf die neuen Notizen hin, bis du sie einmal öffnest — accountweit, pro Version.",
    ["With the Modern style, the equipment set sidebar now docks to the right of the stats panel at exactly the window's height, instead of overlapping it. Switching styles with the window open moves it immediately."] = "Im Modern-Stil dockt die Ausrüstungsset-Sidebar jetzt rechts vom Werte-Panel an, exakt auf Fensterhöhe, statt es zu überlappen. Ein Stilwechsel bei offenem Fenster verschiebt sie sofort.",
    ["Micro menu buttons that the game hides situationally are shown again, so the row no longer has a gap."] = "Mikromenü-Buttons, die das Spiel situationsbedingt versteckt, werden wieder angezeigt, sodass die Reihe keine Lücke mehr hat.",
    ["The default nameplate no longer shows through as a faint transparent bar under the custom plate — it is now hidden outright and kept hidden while the custom plate is active."] = "Die Standard-Namensplakette scheint nicht mehr als blasser transparenter Balken unter der eigenen Plakette durch — sie wird jetzt komplett versteckt und bleibt versteckt, solange die eigene Plakette aktiv ist.",
    ["All micro menu buttons open their windows again — the emptied default micro menu shell was invisibly swallowing clicks on the relocated buttons."] = "Alle Mikromenü-Buttons öffnen ihre Fenster wieder — die geleerte Standard-Mikromenü-Hülle hat Klicks auf die verschobenen Buttons unsichtbar geschluckt.",
    ["Fixed a blocked-action error when the stance bar updated during combat; stance button visibility now only changes out of combat, while icon tint, cooldown and the active marker keep updating live."] = "Behoben: ein Fehler durch blockierte Aktionen, wenn sich die Haltungsleiste im Kampf aktualisierte; die Sichtbarkeit der Haltungs-Buttons ändert sich jetzt nur noch außerhalb des Kampfes, während Icon-Färbung, Cooldown und aktive Markierung live weiterlaufen.",
    ["An Action Bars module puts every action bar on its own movable frame — action bars 1 to 5, the stance bar and the pet bar — each placed and scaled in Edit Mode and configured on its own."] = "Ein Aktionsleisten-Modul legt jede Aktionsleiste auf einen eigenen verschiebbaren Rahmen — Aktionsleisten 1 bis 5, die Haltungsleiste und die Begleiterleiste — jede im Edit Mode platziert und skaliert und einzeln konfiguriert.",
    ["The main bar pages correctly with druid, rogue, warrior and priest forms, and your keybinds keep working on every bar, with the key shown on the buttons."] = "Die Hauptleiste blättert mit Druiden-, Schurken-, Krieger- und Priester-Formen korrekt um, und deine Tastenbelegungen funktionieren auf jeder Leiste weiter — die Taste wird auf den Buttons angezeigt.",
    ["Per bar: visibility (always, mouseover, in or out of combat), opacity, icon size, buttons per row, spacing, vertical layout, reverse order, and hiding the keybind or macro text — with adjustable text sizes for keybind, macro, count and cooldown numbers."] = "Pro Leiste: Sichtbarkeit (immer, Mouseover, im oder außerhalb des Kampfes), Deckkraft, Icon-Größe, Buttons pro Reihe, Abstand, vertikales Layout, umgekehrte Reihenfolge und das Ausblenden von Tastenbelegungs- oder Makrotext — mit einstellbaren Textgrößen für Tastenbelegung, Makro, Anzahl und Cooldown-Zahlen.",
    ["Empty slots can be hidden and reappear automatically while you drag an ability onto the bar, and a bar can be made click-through."] = "Leere Slots lassen sich ausblenden und erscheinen automatisch wieder, während du eine Fähigkeit auf die Leiste ziehst, und eine Leiste kann durchklickbar gemacht werden.",
    ["Cooldown and look settings for all bars: cooldown sweep darkness, desaturating icons on cooldown, colouring icons while the target is out of range, and hiding button tooltips always or only in combat."] = "Cooldown- und Optik-Einstellungen für alle Leisten: Dunkelheit des Cooldown-Sweeps, Entsättigen von Icons auf Cooldown, Einfärben von Icons, während das Ziel außer Reichweite ist, und das Ausblenden von Button-Tooltips immer oder nur im Kampf.",
    ["An own experience bar with adjustable width, height and colour, rested overlay and progress text — it replaces the default bar while enabled and hides at the level cap."] = "Eine eigene Erfahrungsleiste mit einstellbarer Breite, Höhe und Farbe, Erholt-Overlay und Fortschrittstext — sie ersetzt die Standardleiste, solange sie aktiviert ist, und versteckt sich auf der Maximalstufe.",
    ["The micro menu, the bag bar and the performance bar sit on movable holders, and each of them can be hidden — as can the default experience bar."] = "Mikromenü, Taschenleiste und Performance-Leiste sitzen auf verschiebbaren Haltern, und jeder davon kann versteckt werden — ebenso die Standard-Erfahrungsleiste.",
    ["Off by default: the standard bars stay untouched until you enable the module, and disabling hands everything back (a reload fully restores the default bars)."] = "Standardmäßig aus: Die Standardleisten bleiben unangetastet, bis du das Modul aktivierst, und beim Deaktivieren wird alles zurückgegeben (ein Reload stellt die Standardleisten vollständig wieder her).",
    ["The dark button skin now also covers the new action-bar buttons."] = "Der dunkle Button-Skin deckt jetzt auch die neuen Aktionsleisten-Buttons ab.",
    ["A custom Nameplates module draws its own health bar, cast bar, name and health text over enemy and NPC nameplates — fully configurable, with a live preview that updates as you change each option."] = "Ein eigenes Namensplaketten-Modul zeichnet eigene Lebensbalken, Castbar, Namen und Lebenstext über Gegner- und NPC-Plaketten — voll konfigurierbar, mit einer Live-Vorschau, die sich bei jeder geänderten Option sofort aktualisiert.",
    ["Health bar with your choice of texture, width, height, background, and a border drawn as thin lines or a texture, all in your own colours."] = "Lebensbalken mit Textur, Breite, Höhe und Hintergrund nach Wahl sowie einem Rahmen als dünne Linien oder Textur, alles in deinen eigenen Farben.",
    ["Colouring by reaction (hostile, neutral, friendly, tapped) and by class for players, plus role-based threat colouring for tanks and damage dealers."] = "Färbung nach Reaktion (feindlich, neutral, freundlich, getappt) und nach Klasse bei Spielern, dazu rollenbasierte Bedrohungsfärbung für Tanks und Schadensausteiler.",
    ["Target and focus highlight rings, and an optional fade for plates that are not your target."] = "Ziel- und Fokus-Hervorhebungsringe und ein optionales Verblassen für Plaketten, die nicht dein Ziel sind.",
    ["Cast bar with spell icon, spell name, and a separate colour for casts that cannot be interrupted."] = "Castbar mit Zauber-Icon, Zaubername und einer eigenen Farbe für Casts, die nicht unterbrochen werden können.",
    ["Aura rows: your debuffs (or all of them), enemy buffs, and a separate prominent row for crowd control such as Polymorph, Fear and Sap. A glow marks enemy buffs you can steal or dispel."] = "Aura-Reihen: deine Debuffs (oder alle), Gegner-Buffs und eine eigene prominente Reihe für Crowd Control wie Verwandlung, Furcht und Kopfnuss. Ein Glühen markiert Gegner-Buffs, die du stehlen oder bannen kannst.",
    ["Combo point pips on your target for Rogues and Druids in cat form."] = "Kombopunkt-Pips auf deinem Ziel für Schurken und Druiden in Katzengestalt.",
    ["Raid target markers (skull, cross, and the rest) with adjustable size and position."] = "Schlachtzugszeichen (Totenkopf, Kreuz und der Rest) mit einstellbarer Größe und Position.",
    ["Friendly plates can show name only, the full plate, or nothing — set separately for players and NPCs — and can show a friendly NPC's subtitle under its name."] = "Freundliche Plaketten können nur den Namen, die ganze Plakette oder nichts zeigen — getrennt einstellbar für Spieler und NPCs — und können den Untertitel eines freundlichen NPCs unter seinem Namen anzeigen.",
    ["A single \"Dark Skin\" module now covers the dark action-button and WeakAuras skin plus the optional Dark Mode that darkens Blizzard's default frames — those used to be two separate modules. Your existing settings carry over."] = "Ein einzelnes Modul 'Dunkles Design' deckt jetzt den dunklen Aktionsbutton- und WeakAuras-Skin plus den optionalen Dunkelmodus ab, der Blizzards Standard-Fenster abdunkelt — das waren vorher zwei getrennte Module. Deine bestehenden Einstellungen werden übernommen.",
    ["The reskin modules (skins, character panel, chat, friends list, minimap) are now one tabbed entry, matching how the other groups are already organised."] = "Die Reskin-Module (Skins, Charakterfenster, Chat, Freundesliste, Minimap) sind jetzt ein Eintrag mit Tabs, passend dazu, wie die anderen Gruppen bereits organisiert sind.",
    ["Consolidated groups now list their modules as a vertical, icon-labelled column instead of a wrapping row of tabs — easier to scan when there are many."] = "Zusammengefasste Gruppen listen ihre Module jetzt als vertikale Spalte mit Icon-Beschriftung statt als umbrechende Tab-Reihe — leichter zu überblicken, wenn es viele sind.",
    ["A \"Patch Notes\" page under Overview shows every version's changes right in the game."] = "Eine Seite 'Patch Notes' unter Übersicht zeigt die Änderungen jeder Version direkt im Spiel.",
    ["Cleaner tab names for a few tools: Training, Leisten-Profile, Apexis-Minispiel, Gruppensuche."] = "Sauberere Tab-Namen für ein paar Tools: Training, Leisten-Profile, Apexis-Minispiel, Gruppensuche.",
    ["The target-frame extras and the elite player-frame border are now a single module called \"Player & Target Frame\". Your existing settings and per-character on and off state carry over automatically."] = "Die Zielfenster-Extras und der Elite-Rahmen des Spielerfensters sind jetzt ein einzelnes Modul namens 'Spieler- & Zielfenster'. Deine bestehenden Einstellungen und der An-/Aus-Zustand pro Charakter werden automatisch übernommen.",
    ["Settings now default to a separate profile per class, so what you set on one class no longer changes another. Your current settings are copied into each class profile, and you can still share or pin profiles as before."] = "Einstellungen nutzen jetzt standardmäßig ein eigenes Profil pro Klasse, sodass das, was du auf einer Klasse einstellst, keine andere mehr verändert. Deine aktuellen Einstellungen werden in jedes Klassenprofil kopiert, und du kannst Profile weiterhin wie bisher teilen oder anheften.",
    ["Scrolling messages that fire at the same moment now stack with a gap instead of overlapping."] = "Scrollende Nachrichten, die im selben Moment ausgelöst werden, stapeln sich jetzt mit Abstand, statt sich zu überlappen.",
    ["Fixed an error that could appear when combat started while your line was cast. The sound and interact settings now restore after combat ends instead."] = "Behoben: ein Fehler, der auftreten konnte, wenn der Kampf begann, während deine Angelschnur ausgeworfen war. Die Sound- und Interagieren-Einstellungen werden jetzt stattdessen nach Kampfende wiederhergestellt.",
    ["Lighter cast bar time text, cooldown bars that batch their refreshes during busy moments, a cheaper combat-log check for the cooldown pulse, and a lighter minimap hover check."] = "Leichtgewichtigerer Castbar-Zeittext, Cooldown-Leisten, die ihre Aktualisierungen in hektischen Momenten bündeln, ein günstigerer Kampflog-Check für den Cooldown-Puls und ein leichterer Minimap-Hover-Check.",
    ["The spell stats are ordered spell power, healing, spell crit, then spell hit."] = "Die Zauberwerte sind in der Reihenfolge Zaubermacht, Heilung, Zauberkrit, dann Zaubertreffer angeordnet.",
    ["The Fishing and Mail tabs now read \"Angeln\" and \"Post\"."] = "Die Angel- und Post-Tabs heißen jetzt 'Angeln' und 'Post'.",
    ["A style dropdown at the top of the module options. Classic+ keeps the current look; Modern is a new dark, single-window style."] = "Ein Stil-Dropdown oben in den Modul-Optionen. Classic+ behält den aktuellen Look; Modern ist ein neuer dunkler Ein-Fenster-Stil.",
    ["Modern reskins the whole character window dark with an accent border and a stats panel on the right: a big equipped item level, then collapsible categories — attributes, melee, spell, defense and resistances — with per-stat hover breakdowns and mouse-wheel scrolling."] = "Modern gestaltet das ganze Charakterfenster dunkel um, mit Akzent-Rahmen und einem Werte-Panel rechts: ein groß angezeigtes Item-Level der angelegten Ausrüstung, dann einklappbare Kategorien — Attribute, Nahkampf, Zauber, Verteidigung und Widerstände — mit Hover-Aufschlüsselung pro Wert und Mausrad-Scrollen.",
    ["Under Modern the built-in stats, resistance icons and the model rotate arrows are hidden, and the reputation, skills and player-versus-player sub-tabs plus the bottom tabs are skinned to match. Everything switches back to Classic+ live, and adapts per client (rating stats only where they exist)."] = "Unter Modern sind die eingebauten Werte, die Widerstands-Icons und die Drehpfeile am Modell versteckt, und die Untertabs Ruf, Fertigkeiten und PvP sowie die unteren Tabs sind passend geskinnt. Alles wechselt live zurück zu Classic+ und passt sich pro Client an (Wertungs-Werte nur dort, wo es sie gibt).",
    ["Dark skin for a world-map options window, with its own on and off switch in the Addon Skins options."] = "Dunkler Skin für ein Weltkarten-Optionsfenster, mit eigenem An-/Aus-Schalter in den Addon-Skins-Optionen.",
    ["The clock now sits on the same line as the date and zone instead of floating higher."] = "Die Uhr sitzt jetzt auf derselben Zeile wie Datum und Zone, statt höher zu schweben.",
    ["Dark skin for a loot-distribution addon — its award and roll windows, its settings and overview windows, and the two always-visible roll and bid bars get the house panel, accent border and flat close button."] = "Dunkler Skin für ein Loot-Verteilungs-Addon — seine Vergabe- und Würfelfenster, seine Einstellungs- und Übersichtsfenster und die beiden dauerhaft sichtbaren Würfel- und Bietleisten bekommen das Haus-Panel, den Akzent-Rahmen und den flachen Schließen-Button.",
    ["Dark skin for an attunement tracker — the main window and its buttons match the dark look; the colored status rows stay as they are so the state colors remain readable."] = "Dunkler Skin für einen Attunement-Tracker — Hauptfenster und Buttons passen zum dunklen Look; die farbigen Statuszeilen bleiben, wie sie sind, damit die Statusfarben lesbar bleiben.",
    ["Both are separate on and off switches in the Addon Skins options, next to the others."] = "Beide sind eigene An-/Aus-Schalter in den Addon-Skins-Optionen, neben den anderen.",
    ["NEW:"] = "NEU:",
    ["A single unified inventory window: all bags in one grid, with quality borders, counts, cooldowns, money and free slots. Movable and scalable."] = "Ein einziges vereintes Inventarfenster: alle Taschen in einem Raster, mit Qualitätsrahmen, Anzahl, Cooldowns, Gold und freien Slots. Verschiebbar und skalierbar.",
    ["Fixes stuck inspect bugs (no player inspect possible after a faulty close/timeout). Auto-reset after a timeout, auto-retry when the window stays empty, cleanup when InspectFrame closes + /inspectreset slash command."] = "Behebt hängende Inspect-Bugs (kein Spieler-Inspect möglich nach fehlerhaftem Schließen/Timeout). Auto-Reset nach einem Timeout, Auto-Retry, wenn das Fenster leer bleibt, Cleanup beim Schließen des InspectFrames + /inspectreset Slash-Befehl.",
    ["A modern minimap: round with a clean dark ring and accent line, zone text and clock in a slim panel, mouse-wheel zoom, movable and scalable. Optionally hides other addons' buttons until mouseover."] = "Eine moderne Minimap: rund mit sauberem dunklem Ring und Akzentlinie, Zonentext und Uhr in einem schmalen Panel, Zoomen per Mausrad, verschiebbar und skalierbar. Versteckt optional die Buttons anderer Addons bis zum Mouseover.",
    ["Custom enemy & NPC nameplates with a live preview: health bar, cast bar, name and health text, reaction / class colours, target highlight and threat colouring."] = "Eigene Gegner- & NPC-Namensplaketten mit Live-Vorschau: Lebensbalken, Castbar, Namens- und Lebenstext, Reaktions-/Klassenfarben, Ziel-Hervorhebung und Bedrohungsfärbung.",
    ["Hover an equipment slot for a compact flyout of compatible bag items, or modifier-click for a larger picker. Click an item to equip it."] = "Hovere über einen Ausrüstungs-Slot für ein kompaktes Flyout mit passenden Taschen-Items, oder Modifier-Klick für eine größere Auswahl. Klicke ein Item, um es anzulegen.",
    ["Move every VuloUI window and Blizzard's default frames in one editor."] = "Verschiebe jedes VuloUI-Fenster und Blizzards Standard-Fenster in einem Editor.",
    ["One-key fishing: one key casts, reels and applies a lure, and auto-loots your catch."] = "Ein-Tasten-Angeln: Eine Taste wirft aus, holt ein und trägt einen Köder auf, und dein Fang wird automatisch geplündert.",
    ["Adds an 'Open All' button to your mailbox that collects every attachment and coin in one click."] = "Fügt deinem Briefkasten einen 'Alle öffnen'-Button hinzu, der jeden Anhang und jede Münze mit einem Klick einsammelt.",
    ["Top"] = "Oben",
    ["Bottom"] = "Unten",
    ["Top-Left"] = "Oben links",
    ["Top-Right"] = "Oben rechts",
    ["Bottom-Left"] = "Unten links",
    ["Bottom-Right"] = "Unten rechts",
    ["Trinkets: Cleared all ignored/hidden trinkets."] = "Trinkets: Alle ignorierten/versteckten Schmuckstücke geleert.",
    ["Trinkets usage:"] = "Trinkets-Verwendung:",
    ["/trinket or /Trinkets : toggle the window"] = "/trinket oder /Trinkets : Fenster ein-/ausblenden",
    ["/trinket reset : reset all settings"] = "/trinket reset : setzt alle Einstellungen zurück",
    ["/trinket clear : clear all ignored/hidden trinkets"] = "/trinket clear : leert alle ignorierten/versteckten Schmuckstücke",
    ["/trinket opt : summon options window"] = "/trinket opt : öffnet das Optionsfenster",
    ["/trinket lock|unlock : toggles window lock"] = "/trinket lock|unlock : sperrt/entsperrt das Fenster",
    ["/trinket scale main|menu (number) : sets an exact scale"] = "/trinket scale main|menu (Zahl) : setzt eine exakte Skalierung",
    ["/trinket load top|bottom profilename : loads a profile to top or bottom trinket"] = "/trinket load top|bottom Profilname : lädt ein Profil auf das obere oder untere Schmuckstück",
    ["Are you sure you want to reset Trinkets to default state and reload the UI?"] = "Bist du sicher, dass du Trinkets auf den Standardzustand zurücksetzen und die UI neu laden willst?",
    ["Queued: %s"] = "In der Warteschlange: %s",
    ["Priority"] = "Priorität",
    ["Pause Queue"] = "Warteschlange pausieren",
    ["Parameter must be 0 for top trinket or 1 for bottom."] = "Parameter muss 0 für das obere oder 1 für das untere Schmuckstück sein.",
    ["No profiles saved yet."] = "Noch keine Profile gespeichert.",
    -- Patch notes, module descriptions, anchors, embedded engine (sweep 2026-07)
    -- Patch notes 1.37.1
    ["Visuals"] = "Optik",
    ["The language option under General now actually applies. It silently never took effect — the addon read the client language before your saved choice was loaded. After a /reload every label, dropdown and popup follows your choice."] = "Die Sprachauswahl unter Allgemein greift jetzt wirklich. Sie wirkte stillschweigend nie — das Addon las die Client-Sprache, bevor deine gespeicherte Wahl geladen war. Nach einem /reload folgen alle Beschriftungen, Auswahllisten und Dialoge deiner Wahl.",
    ["The Patch Notes page is translated into all languages, including every past version."] = "Die Patch-Notizen-Seite ist in alle Sprachen übersetzt, einschließlich aller früheren Versionen.",
    ["The trinket panel, its queue window and the /trinket help are translated too."] = "Das Schmuck-Fenster, seine Warteschlange und die /trinket-Hilfe sind ebenfalls übersetzt.",
    ["German: sixteen duplicated translations cleaned up, five of which contradicted each other."] = "Deutsch: sechzehn doppelte Übersetzungen bereinigt, fünf davon widersprachen sich.",
    ["Third pass over the busiest code paths: nameplate auras scan once instead of four times, combat-log and aura events skip a safety wrapper, timer texts only redraw when the shown number changes, and several background listeners now sleep while their feature is off or hidden. Less stutter in raids and arenas."] = "Dritter Durchgang über die meistbelasteten Codepfade: Namensplaketten-Auren werden einmal statt viermal durchsucht, Kampflog- und Auren-Ereignisse sparen sich eine Sicherheitshülle, Timer-Texte zeichnen nur neu, wenn sich die angezeigte Zahl ändert, und mehrere Hintergrund-Zuhörer schlafen, solange ihre Funktion aus oder verborgen ist. Weniger Ruckeln in Schlachtzügen und Arenen.",
    ["The frames can be turned off again without leftovers."] = "Die Fenster lassen sich wieder ohne Rückstände abschalten.",
    ["An interrupted enemy cast now shows INTERRUPTED briefly — it used to vanish the same instant."] = "Ein unterbrochener gegnerischer Zauber zeigt jetzt kurz UNTERBROCHEN — bisher verschwand er im selben Moment.",
    ["Diminishing-returns icons clean up correctly after toggling the tracker mid-arena."] = "Die Symbole des Diminishing-Returns-Trackers räumen korrekt auf, wenn der Tracker mitten in der Arena umgeschaltet wird.",
    ["Seven working settings that were invisible in the options are shown again, and several switches that did nothing are wired up."] = "Sieben funktionierende Einstellungen, die in den Optionen unsichtbar waren, werden wieder angezeigt, und mehrere wirkungslose Schalter sind jetzt angeschlossen.",
    ["Modules tidy up after themselves when disabled: totem range dimming, the inspect window, queue timer, quest log and font bars no longer leave stale pieces behind."] = "Module räumen beim Abschalten hinter sich auf: Totem-Reichweiten-Abdunklung, das Inspizieren-Fenster, Warteschlangen-Timer, Questlog und Schriftleisten hinterlassen keine Reste mehr.",
    ["Three modules got their own sidebar icons instead of the placeholder, and Reminders got a nicer bell."] = "Drei Module haben eigene Seitenleisten-Symbole statt des Platzhalters bekommen, und die Erinnerungen eine schönere Glocke.",
    -- Bags: quest starter marker
    ["Quest starter marker (!)"] = "Quest-Start-Markierung (!)",
    ["Overlays a yellow exclamation mark on items that start a quest you have not accepted yet."] = "Legt ein gelbes Ausrufezeichen über Gegenstände, die eine noch nicht angenommene Quest starten.",
    -- Options page build failure
    ["|cffff5555Options page '%s' failed to build:|r %s"] = "|cffff5555Optionsseite '%s' konnte nicht aufgebaut werden:|r %s",
    ["|cffff5555This page could not be built. /reload, and report it if it persists.|r"] = "|cffff5555Diese Seite konnte nicht aufgebaut werden. /reload, und melde es bitte, falls es bleibt.|r",
    ["|cff888888%.2f ms/frame |cff666666(%.1f%% of ours, peak %.1f ms)|r|r"] = "|cff888888%.2f ms/Bild |cff666666(%.1f%% davon unsere, Spitze %.1f ms)|r|r",
    ["|cffaaaaaaThe header shows how much frame time VuloClassicUI costs. Your client measures this on its own, all the time — no setting and no reload needed.|r"] = "|cffaaaaaaDie Kopfzeile zeigt, wie viel Bildzeit VuloClassicUI kostet. Dein Client misst das von selbst, dauerhaft — ohne Einstellung und ohne Neuladen.|r",
    -- Patch notes 1.37.2
    ["Classic Era, Hardcore and Season of Discovery"] = "Classic Era, Hardcore und Season of Discovery",
    ["Under the hood"] = "Unter der Haube",
    ["The addon loads again without ticking \"Load out of date AddOns\". Blizzard's July interface update moved these realms to a new version number."] = "Das Addon lädt wieder ohne das Häkchen „Veraltete AddOns laden“. Blizzards Oberflächen-Update im Juli hat diese Realms auf eine neue Versionsnummer gehoben.",
    ["Fixed a crash that switched the whole Class Trainer page off on Season of Discovery: one ability the realm does not know took the entire module down with it."] = "Ein Absturz behoben, der in Season of Discovery die ganze Klassenlehrer-Seite abschaltete: eine einzige Fähigkeit, die der Realm nicht kennt, riss das komplette Modul mit.",
    ["The elite border on your player frame sits correctly again. It was placed against the old frame layout, which that same update replaced."] = "Der Elite-Rahmen am Spielerfenster sitzt wieder richtig. Er war an der alten Fensteraufteilung ausgerichtet, die dasselbe Update ersetzt hat.",
    ["Fixed a rare error storm at the end of a fight. Cleanup work in nineteen files could be skipped and the chat filled with error lines."] = "Einen seltenen Fehlerschwall am Kampfende behoben. Aufräumarbeiten in neunzehn Dateien konnten übersprungen werden und der Chat füllte sich mit Fehlerzeilen.",
    ["Combat log features (swing timer, cooldown pulse, combat text, arena tracker, nameplates, mana display) no longer depend on a setting a player can switch off."] = "Kampflog-Funktionen (Schlagtimer, Abklingpuls, Kampftexte, Arena-Verfolger, Namensplaketten, Manaanzeige) hängen nicht mehr an einer Einstellung, die man abschalten kann.",
    ["An interrupted enemy cast now really shows INTERRUPTED for a moment."] = "Ein unterbrochener gegnerischer Zauber zeigt die Unterbrechung jetzt wirklich einen Moment lang an.",
    ["Items that start a quest you have not accepted yet are marked with a yellow exclamation mark, in bags, bank and keyring."] = "Gegenstände, die eine noch nicht angenommene Quest starten, tragen jetzt ein gelbes Ausrufezeichen — in Taschen, Bank und Schlüsselbund.",
    ["Seven of the eight shipped translations no longer build their lookup table at all. Only the language you actually read is assembled, which frees about a megabyte on every login."] = "Sieben der acht mitgelieferten Übersetzungen bauen ihre Nachschlagetabelle gar nicht mehr auf. Nur die Sprache, die du wirklich liest, wird zusammengesetzt — das spart bei jedem Login rund ein Megabyte.",
    ["Edit Mode: three background drivers no longer run permanently, dragging a window allocates far less, and finding a window is a direct lookup instead of a search."] = "Bearbeitungsmodus: drei Hintergrund-Taktgeber laufen nicht mehr dauerhaft, das Ziehen eines Fensters erzeugt deutlich weniger Ballast, und ein Fenster wird direkt nachgeschlagen statt gesucht.",
    ["Disabling a module now detaches it completely — several used to leave listeners running for the rest of the session."] = "Ein abgeschaltetes Modul löst sich jetzt vollständig: mehrere ließen bisher Zuhörer für den Rest der Sitzung weiterlaufen.",
    ["The performance readout in the header uses your client's own always-on measurement, so it needs no setting and no reload."] = "Die Leistungsanzeige in der Kopfzeile nutzt die stets laufende Messung deines Clients und braucht daher weder Einstellung noch Neuladen.",
    -- Built-in profiler
    ["Nothing measured yet. Play for a bit, then read it again."] = "Noch nichts gemessen. Spiel eine Weile und lies es dann erneut aus.",
    ["Measured over %.1f s -- %.1f ms total, %.2f%% of it ours:"] = "Gemessen über %.1f s -- %.1f ms gesamt, davon %.2f%% unsere:",
    ["Measurement off."] = "Messung aus.",
    ["Measurement reset."] = "Messung zurückgesetzt.",
    ["Measurement on. Play, then type /vcuiprof again to read it."] = "Messung an. Spiel eine Weile und tippe dann erneut /vcuiprof.",
    -- Patch notes 1.37.3
    ["Class Trainer page"] = "Klassenlehrer-Seite",
    ["Fixed the page being thrown away again a moment after you opened it, dropping you back on a class tab. The spell book resets its own page whenever your spells change, and our page sits past the last real tab, so it was always the one discarded. Most noticeable on Season of Discovery, where engraving changes spells constantly."] = "Behoben, dass die Seite kurz nach dem Öffnen wieder verworfen wurde und dich auf einem Klassenreiter zurückließ. Das Zauberbuch setzt seine eigene Seite zurück, sobald sich deine Zauber ändern, und unsere sitzt hinter dem letzten echten Reiter — also traf es immer sie. Am deutlichsten in Season of Discovery, wo das Gravieren ständig Zauber ändert.",
    ["`/vcuiprof` measures how much frame time each part of the addon costs, then prints a list. It ships switched off and costs nothing while it is — the measuring code is only put in place when you turn it on. Type it once to start, once more to read."] = "`/vcuiprof` misst, wie viel Bildzeit jeder Teil des Addons kostet, und gibt eine Liste aus. Es wird ausgeschaltet ausgeliefert und kostet in diesem Zustand nichts — die messende Fassung wird erst beim Einschalten eingesetzt. Einmal tippen startet, ein zweites Mal liest aus.",
    -- Patch notes 1.37.4
    ["Clicking a trinket button while that trinket slot is empty no longer throws an error. The game's own shortcut for \"use the item in slot N\" stopped tolerating an empty slot with July's interface update, so the button now takes a different route to the same action."] = "Ein Klick auf einen Schmuck-Knopf mit leerem Schmuckplatz wirft keinen Fehler mehr. Die spieleigene Abkürzung für „benutze den Gegenstand in Platz N“ verträgt seit dem Oberflächen-Update im Juli keinen leeren Platz mehr, also nimmt der Knopf jetzt einen anderen Weg zur selben Handlung.",
    ["Fixed a stutter of almost two frames every time you entered or left combat, if you use WeakAuras and have the WeakAuras skin switched on. Every combat change repainted every aura you have ever saved — including the ones not on screen — with a look that had not changed. Auras are now only repainted when the settings or their size actually changed. Measured: 28 ms down to under 2 ms. The skin itself is unchanged."] = "Ein Stocken von fast zwei Bildern bei jedem Kampfbeginn und -ende behoben, wenn du WeakAuras nutzt und unseren WeakAuras-Anstrich anhast. Bei jedem Kampfwechsel wurde jede je gespeicherte Aura neu bemalt — auch die, die gar nicht auf dem Bildschirm ist — mit einem Aussehen, das sich nicht geändert hatte. Auren werden jetzt nur noch neu bemalt, wenn sich Einstellungen oder Größe wirklich geändert haben. Gemessen: 28 ms auf unter 2 ms. Der Anstrich selbst bleibt gleich.",
    -- Patch notes 1.39.0
    ["Download"] = "Download",
    ["Diminishing Returns Position – Put the DR row on either side of the frame, with its own X and Y offset"] = "Position der Verkettungsanzeige – Legt die Reihe auf eine der beiden Rahmenseiten, mit eigenem Versatz X und Y",
    ["The DR row no longer lands on top of the trinket or racial icon. It used to hang at a fixed distance on the right edge, exactly where the side icon sits, so switching it on stacked the two. The new default clears it, and on the left edge the row grows outward instead of across the frame."] = "Die Reihe der Verkettungsanzeige landet nicht mehr auf dem Schmuck- oder Volksfähigkeitssymbol. Sie hing in festem Abstand an der rechten Kante, genau dort, wo das Seitensymbol sitzt, sodass sich beide beim Einschalten überlagerten. Der neue Standard räumt daran vorbei, und an der linken Kante wächst die Reihe nach außen statt quer über den Rahmen.",
    ["The trinket and racial icons sit further out from the enemy frame and are a little smaller, so the health and mana bars read as the middle of the frame instead of competing with an icon at each shoulder. Both are sliders, so your own values are kept."] = "Die Symbole für Schmuckstück und Volksfähigkeit sitzen weiter vom Gegnerrahmen entfernt und sind etwas kleiner, sodass sich Lebens- und Manaleiste als Mitte des Rahmens lesen, statt gegen ein Symbol an jeder Schulter anzutreten. Beides sind Regler, deine eigenen Werte bleiben also erhalten.",
    ["The addon folder no longer ships build tools and source files that no player needs. The licence files stay where they are."] = "Der Addon-Ordner liefert keine Bauwerkzeuge und Quelldateien mehr mit, die kein Spieler braucht. Die Lizenzdateien bleiben, wo sie sind.",
    ["The release notes on the distribution pages are written in English now."] = "Die Versionshinweise auf den Verteilseiten sind jetzt auf Englisch geschrieben.",
    ["Six languages were missing seven texts that existed in German only. All nine are complete again."] = "Sechs Sprachen fehlten sieben Texte, die es nur auf Deutsch gab. Alle neun sind wieder vollständig.",
    ["The keyword help for the item search was misleading in Chinese: it gave an English type name as the example, which a Chinese client would never have matched. The example is written in the reader's own language now."] = "Die Stichwort-Hilfe der Gegenstandssuche war auf Chinesisch irreführend: Sie nannte als Beispiel einen englischen Typnamen, den ein chinesischer Client nie gefunden hätte. Das Beispiel steht jetzt in der Sprache des Lesers.",
    ["Seal Twist Helper – A swing bar with the twist window marked, plus the next sensible action"] = "Seal-Twist-Hilfe – Eine Schwungleiste mit markiertem Twist-Fenster und der nächsten sinnvollen Aktion",
    ["The bar counts down to your next auto attack with two marks: green is the last moment the second seal can still land, purple is how long a Judgement still fits in front of it. The next action is worked out live from your swing timer, the global cooldown and the seals actually on you — not from a fixed rotation. Crusader Strike is only suggested while there is room for it and the holding seal afterwards. Judgement deliberately gets none: it consumes the seal, and a wrong hint costs more there than no hint. Off by default."] = "Die Leiste zählt bis zu deinem nächsten Autoangriff herunter, mit zwei Marken: Grün ist der letzte Moment, in dem das zweite Siegel noch landen kann, Lila zeigt, wie lange ein Richturteil noch davorpasst. Die nächste Aktion wird live aus deinem Schwungtakt, der globalen Abklingzeit und den tatsächlich anliegenden Siegeln berechnet — nicht aus einem festen Rotationsmuster. Der Kreuzfahrerstoß wird nur vorgeschlagen, solange davor noch Platz für ihn und das Halte-Siegel bleibt. Das Richturteil bekommt bewusst keinen: Es verbraucht das Siegel, und ein falscher Hinweis kostet dort mehr als gar keiner. Standardmäßig aus.",
    -- Sidebar groups (QoL split, 1.40.0)
    ["Bags & Items"] = "Taschen & Gegenstände",
    ["Chat & Social"] = "Chat & Soziales",
    ["Extras"] = "Kleinkram",
    ["Tools"] = "Werkzeuge",
    -- Overview page
    ["peak %.1f ms"] = "Spitze %.1f ms",
    ["%.2f ms"] = "%.2f ms",
    ["%.1f MB"] = "%.1f MB",
    ["%d KB"] = "%d KB",
    ["%d of %d"] = "%d von %d",
    ["moved"] = "verschoben",
    ["Modules"] = "Module",
    ["Frame time"] = "Bildzeit",
    ["Memory"] = "Speicher",
    ["Windows"] = "Fenster",
    ["%d modules are switched off."] = "%d Module sind ausgeschaltet.",
    ["The edit mode grid is switched on."] = "Das Raster im Bearbeitungsmodus ist eingeschaltet.",
    ["There are patch notes you have not read yet."] = "Es gibt Versionshinweise, die du noch nicht gelesen hast.",
    ["What would you like to change?"] = "Was möchtest du einstellen?",
    ["Worth knowing"] = "Wissenswert",
    ["Recently visited"] = "Zuletzt besucht",
    -- Talent overrides
    ["active"] = "aktiv",
    ["Talent Overrides"] = "Übersteuerungen je Talentwahl",
    ["Talent group %d"] = "Talentwahl %d",
    ["%d settings overridden"] = "%d Einstellungen übersteuert",
    ["Forget all overrides for this talent group"] = "Alle Übersteuerungen dieser Talentwahl vergessen",
    ["Overrides apply on their own when you switch talent groups. This client has no specialisations, so the dual talent system is the axis."] = "Übersteuerungen greifen von selbst, sobald du die Talentwahl wechselst. Dieser Client kennt keine Spezialisierungen, deshalb ist die duale Talentwahl die Achse.",
    -- Override groups
    ["Talent group %d (%s)"] = "Talentwahl %d (%s)",
    ["Name for the new group"] = "Name der neuen Gruppe",
    ["Editing as"] = "Bearbeiten als",
    ["Yourself"] = "Ich selbst",
    ["Manage groups..."] = "Gruppen verwalten...",
    ["Owns the current talent group"] = "Gilt für die aktuelle Talentwahl",
    ["Delete this group"] = "Diese Gruppe löschen",
    ["No groups yet."] = "Noch keine Gruppen.",
    -- Anchor points
    ["Centre"] = "Mitte",
    ["Thin outline"] = "Dünne Kontur",
    -- Patch notes 1.40.0
    ["Moved out of the sidebar into Global Settings, as its own tab beside Profiles. Your saved setups were kept."] = "Aus der Seitenleiste heraus in die Globalen Einstellungen umgezogen, als eigener Reiter neben den Profilen. Deine gespeicherten Belegungen sind erhalten.",
    ["They were stored once per class profile — seven copies of one macro library. Stored once now, which cut the settings file by a third. Identical copies are merged, ones that differ are kept side by side."] = "Sie lagen einmal je Klassenprofil — sieben Kopien derselben Makrobibliothek. Jetzt liegen sie einmal, was die Einstellungsdatei um ein Drittel verkleinert hat. Gleiche Kopien werden zusammengelegt, abweichende bleiben nebeneinander erhalten.",
    ["The chat window no longer jumps back the moment you open the edit mode. Switching layouts re-anchors every window the game knows about, including ones we place ourselves."] = "Das Chatfenster springt nicht mehr zurück, sobald du den Bearbeitungsmodus öffnest. Ein Layoutwechsel verankert jedes Fenster neu, das das Spiel kennt — auch die, die wir selbst setzen.",
    ["A dropdown with a long entry no longer wraps into the row below it."] = "Ein Klappmenü mit einem langen Eintrag bricht nicht mehr in die Zeile darunter.",
    ["The first page is a picture of your interface instead of a second sidebar: modules running, frame time and memory, windows you moved, pages you last visited."] = "Die erste Seite zeigt den Zustand deines Interface statt einer zweiten Seitenleiste: laufende Module, Bildzeit und Speicher, verschobene Fenster und die zuletzt besuchten Seiten.",
    ["Talent Overrides – Named groups hold their own value for individual settings and apply when you switch talent specs"] = "Talent-Übersteuerungen – Benannte Gruppen halten eigene Werte für einzelne Einstellungen und greifen beim Wechsel der Talentwahl",
    ["A group can also name a situation — raid, dungeon, arena, battleground, in a group, alone. Anything you change while a group is active is recorded into it, and every overridden row is marked."] = "Eine Gruppe darf zusätzlich eine Situation nennen — Schlachtzug, Instanz, Arena, Schlachtfeld, in einer Gruppe, allein. Alles, was du bei aktiver Gruppe änderst, wird darin mitgeschrieben, und jede übersteuerte Zeile ist markiert.",
    ["Sliders are one row like every other setting, their number can be typed into, and labels line up in a measured column across the page. A long translation no longer pushes a value box into the next column or a button off its card."] = "Regler sind jetzt eine Zeile wie jede andere Einstellung, ihre Zahl lässt sich eintippen, und die Beschriftungen fluchten in einer gemessenen Spalte über die ganze Seite. Eine lange Übersetzung schiebt keinen Wertblock mehr in die Nachbarspalte und keinen Knopf mehr über die Karte hinaus.",
    ["Every section starts closed, so a long page opens as a list of headings."] = "Jeder Abschnitt startet zugeklappt, sodass eine lange Seite als Liste von Überschriften aufgeht.",
    ["The automatic swap queue has controls again — order, delay and the stop marker, on the trinket page. They only ever existed in a window this addon hides."] = "Die automatische Tauschwarteschlange hat wieder eine Bedienung — Reihenfolge, Verzögerung und die Endmarke, auf der Schmuckseite. Sie lag bisher nur in einem Fenster, das dieses Addon versteckt.",
    ["Trinket icons show up again: on the buttons, on the queue marker, and on your worn trinkets right after login instead of only once you click them."] = "Die Schmucksymbole sind wieder da: auf den Knöpfen, auf der Warteschlangenmarke und auf deinen getragenen Schmuckstücken direkt nach dem Anmelden statt erst nach einem Klick.",
    -- Befehlsregistratur
    ["%s has no handler yet — this is a bug, please report it."] = "%s hat noch keine Behandlung — das ist ein Fehler, bitte melde ihn.",
    ["%s belongs to %s, which is switched off."] = "%s gehört zu %s, und das ist ausgeschaltet.",
    ["|cff9b6cffCommands|r — %d in total. Grey ones belong to a module that is switched off."] = "|cff9b6cffBefehle|r — %d insgesamt. Graue gehören zu einem ausgeschalteten Modul.",
    ["%s is also claimed by another addon (%s) — one of the two wins."] = "%s wird auch von einem anderen Addon beansprucht (%s) — eines von beiden gewinnt.",
    ["waiting for a swing"] = "warte auf einen Schlag",
    ["  -  lag %.0fms"] = "  -  Latenz %.0fms",
    ["|cffff8800No seal to twist out of. Only Seal of Command and Seal of Righteousness carry over to a swing after being replaced, so one of the two has to be learned.|r"] = "|cffff8800Kein Siegel, aus dem getwistet werden kann. Nur das Siegel des Befehls und das Siegel der Rechtschaffenheit wirken noch auf einen Schlag, nachdem sie ersetzt wurden — eines von beiden muss gelernt sein.|r",
    ["|cffff8800Only one seal learned. A second one is needed to twist into.|r"] = "|cffff8800Nur ein Siegel gelernt. Zum Twisten wird ein zweites gebraucht.|r",
    ["|cffff8800The seal you hold cannot be twisted out of. Only Seal of Command and Seal of Righteousness carry over to the swing that replaces them.|r"] = "|cffff8800Aus dem Siegel, das du hältst, kann nicht gewechselt werden. Nur das Siegel des Befehls und das Siegel der Rechtschaffenheit wirken noch auf den Schlag, der sie ersetzt.|r",
    ["Only Seal of Command and Seal of Righteousness work here: they are the two whose effect still lands on the swing that replaces them."] = "Hier passen nur das Siegel des Befehls und das Siegel der Rechtschaffenheit: Sie sind die beiden, deren Wirkung noch auf dem Schlag landet, der sie ersetzt.",
    -- Namensplaketten-Vorlage
    ["Nameplate settings replaced. Switch profile to get the old ones back."] = "Die Einstellungen der Namensplaketten wurden ersetzt. Ein Profilwechsel holt die alten zurück.",
    ["Overwrites this profile's nameplate settings with a wide, flat, dark look. Other profiles are untouched."] = "Überschreibt die Namensplaketten-Einstellungen dieses Profils mit einem breiten, flachen, dunklen Aussehen. Andere Profile bleiben unberührt.",
    ["|cffaaaaaaOverwrites this profile's nameplate settings with a wide, flat, dark look. Other profiles are untouched.|r"] = "|cffaaaaaaÜberschreibt die Namensplaketten-Einstellungen dieses Profils mit einem breiten, flachen, dunklen Aussehen. Andere Profile bleiben unberührt.|r",
    ["Apply the wide, flat look"] = "Breites, flaches Aussehen übernehmen",
    -- Plaetze der Namensplaketten
    ["Main positions"] = "Hauptpositionen",
    ["|cffaaaaaaOne thing per slot. Giving a slot something takes it away from the slot that had it.|r"] = "|cffaaaaaaEins pro Platz. Was du einem Platz gibst, verliert der Platz, der es vorher hatte.|r",
    ["Debuffs"] = "Schwächungen",
    ["Buffs"] = "Stärkungen",
    ["Crowd control"] = "Massenkontrolle",
    ["Your own debuffs"] = "Eigene Debuffs",
    -- Leuchten bei wenig Leben, Entzauber-Leuchten
    ["Glow when low on health"] = "Leuchten bei wenig Leben",
    ["A coloured ring around the bar once the unit drops below the mark."] = "Ein farbiger Ring um die Leiste, sobald das Ziel unter die Marke fällt.",
    ["Glow below (%)"] = "Leuchten unter (%)",
    ["Low health colour"] = "Farbe bei wenig Leben",
    ["Glow in the aura's own school colour"] = "Im Schulfarbton des Zaubers leuchten",
    ["Magic blue, curse purple, disease orange, poison green — instead of one colour for everything."] = "Magie blau, Fluch violett, Krankheit orange, Gift grün — statt einer Farbe für alles.",
    -- Absorptionsstil
    ["Absorb style"] = "Absorptionsstil",
    ["Flat colour"] = "Einfarbig",
    -- Zauberziel
    ["Show who the cast is aimed at"] = "Zeigen, auf wen gezaubert wird",
    ["The caster's current target, beside the cast bar. Your own name is coloured."] = "Das aktuelle Ziel des Zaubernden, neben der Zauberleiste. Dein eigener Name wird eingefärbt.",
    ["Cast target size"] = "Größe des Zauberziels",
    -- Zielpfeile
    ["Arrows beside your target"] = "Pfeile neben deinem Ziel",
    ["Two arrows pointing in at the target's bar, one on each side."] = "Zwei Pfeile, die von beiden Seiten auf die Leiste des Ziels zeigen.",
    ["Arrow size"] = "Pfeilgröße",
    ["Arrow distance"] = "Pfeilabstand",
    ["Arrow colour"] = "Pfeilfarbe",
    -- Fokus-Merkzeichen
    ["Mark on the focus plate"] = "Merkzeichen auf der Fokus-Plakette",
    ["A short text on your focus target's plate. A ring says this one is special; the mark says which."] = "Ein kurzer Text auf der Plakette deines Fokusziels. Ein Ring sagt, dass eine besonders ist; das Zeichen sagt, welche.",
    ["Mark text"] = "Text des Merkzeichens",
    ["Mark position"] = "Position des Merkzeichens",
    ["Mark size"] = "Größe des Merkzeichens",
    -- Kleine Plaketten
    ["Back to the small plates"] = "Zurück zu den kleinen Plaketten",
    ["Puts the same settings back to the small plates this addon ships with."] = "Setzt dieselben Einstellungen auf die kleinen Plaketten zurück, die dieses Addon mitbringt.",
    ["|cffaaaaaaHold Seal of Command, then cast the second seal in the last fraction of a second before your auto-attack: that swing carries both. Below level 64 the second seal is Righteousness; Blood and the Martyr replace it from there.|r"] = "|cffaaaaaaHalte das Siegel des Befehls und wirke das zweite Siegel im letzten Sekundenbruchteil vor deinem Autoangriff: dieser Schlag trägt dann beide. Unter Stufe 64 ist das zweite Siegel das der Rechtschaffenheit; ab dort lösen es Blut und Märtyrer ab.|r",
    ["|cffaaaaaaThe bar counts down to the swing in zones: |cff5c8aebblue|r is free for a filler, |cffd93636red|r is the stretch where a cast would still be on the global cooldown when the window opens, and |cff33ff66green|r is the twist window. The last mark inside the green is the late twist, which leaves room for a judgement in front of the seal.|r"] = "|cffaaaaaaDie Leiste zählt in Zonen zum Schlag herunter: |cff5c8aebblau|r ist frei für einen Zwischenzauber, |cffd93636rot|r ist der Abschnitt, in dem ein Zauber beim Öffnen des Fensters noch auf der globalen Abklingzeit läge, und |cff33ff66grün|r ist das Twist-Fenster. Die letzte Marke im Grünen ist der späte Twist, bei dem davor noch ein Richturteil passt.|r",
    ["Late twist window (seconds)"] = "Spätes Twist-Fenster (Sekunden)",
    ["The tail of the twist window, marked separately. Twisting that late still leaves room for a judgement in front of the seal. Set it as long as the twist window to hide the mark."] = "Das Ende des Twist-Fensters, eigens markiert. So spät getwistet passt davor noch ein Richturteil. Genauso lang wie das Twist-Fenster eingestellt, verschwindet die Marke.",
    ["Second cue for the late window"] = "Zweiter Ton für das späte Fenster",
    ["A different sound at the late twist mark, so the two ends of the window can be told apart without looking at the bar."] = "Ein anderer Ton an der Marke des späten Twists, damit sich die beiden Enden des Fensters ohne Hinsehen unterscheiden lassen.",
    ["Shade the zones"] = "Zonen einfärben",
    ["Tints the part of the swing still to come in the colour of the zone it runs into."] = "Färbt den noch kommenden Teil des Schwungs in der Farbe der Zone, in die er läuft.",
    ["Show the marks"] = "Marken zeigen",
    ["The three boundary lines: danger zone, twist window, late twist."] = "Die drei Grenzlinien: Gefahrenzone, Twist-Fenster, später Twist.",
    ["Show seal indicators"] = "Siegel-Anzeigen zeigen",
    ["The seals currently on you and how long they last, right of the bar. Both show while the twist is in -- that overlap is the pay-off."] = "Die Siegel, die gerade auf dir liegen, und ihre Restdauer, rechts der Leiste. Während des Twists stehen beide da -- diese Überschneidung ist der Gewinn.",
    ["Seal icon size"] = "Größe der Siegel-Symbole",
    ["Head start for the prompt (ms)"] = "Vorlauf für den Hinweis (ms)",
    ["Shows the twist prompt and plays its cue this far before the window actually opens, so there is time to see it and press. The colours on the bar stay exact."] = "Zeigt den Twist-Hinweis und spielt seinen Ton um diese Zeit früher, als das Fenster tatsächlich aufgeht, damit du ihn noch sehen und drücken kannst. Die Farben auf der Leiste bleiben exakt.",
    ["auto"] = "Auto",
    ["Twist only"] = "Nur Twist",
    ["Rotation"] = "Rotation",
    ["Show the rotation helper"] = "Rotations-Hilfe zeigen",
    ["A row of steps above the bar: which sequence fits your weapon and haste, and where in it you are. It steps forward on what you actually cast and on your swings."] = "Eine Schrittreihe über der Leiste: welche Abfolge zu deiner Waffe und deinem Tempo passt und wo darin du gerade stehst. Sie rückt weiter, wenn du tatsächlich wirkst und wenn dein Schlag fällt.",
    ["Sequence"] = "Abfolge",
    ["Automatic follows your attack speed and spell haste, which is what decides how many twists fit between two strikes. Pick one by hand to drill a single sequence."] = "Automatisch richtet sich nach Angriffstempo und Zaubertempo — die entscheiden, wie viele Twists zwischen zwei Stößen passen. Von Hand gewählt, um eine einzelne Abfolge zu üben.",
    ["Rotation icon size"] = "Symbolgröße",
    ["Sound when the twist lands"] = "Ton, wenn der Twist sitzt",
    ["Hit sound"] = "Trefferton",
    ["Listen"] = "Anhören",
    ["Chime"] = "Glocke",
    ["Raid warning"] = "Schlachtzugswarnung",
    ["Ready check"] = "Bereitschaftsprüfung",
    ["Click"] = "Klick",
    -- Patch notes 1.41.0
    ["Moving a frame could throw a blocked-action error if you happened to be in combat while the frames were built. The keyboard is only taken over once a mover is on screen."] = "Ein Fenster zu verschieben konnte eine Blockade-Meldung auslösen, wenn du gerade im Kampf warst, während die Fenster gebaut wurden. Die Tastatur wird jetzt erst übernommen, sobald ein Verschieber sichtbar ist.",
    ["The trinket window's settings were being written to the saved file a second time under their old names. They are stored once now."] = "Die Einstellungen des Schmuck-Fensters wurden ein zweites Mal unter ihren alten Namen in die Speicherdatei geschrieben. Sie liegen jetzt nur noch einmal dort.",
    ["42 texts existed in German only, among them the whole talent override interface and the trinket queue. All nine languages are complete again."] = "42 Texte gab es nur auf Deutsch, darunter die gesamte Oberfläche der Talent-Übersteuerungen und die Schmuck-Warteschlange. Alle neun Sprachen sind wieder vollständig.",
    ["Main positions – Six slots around the plate, each holding one thing: debuffs, buffs, crowd control or your own damage-over-time"] = "Hauptpositionen – Sechs Plätze rund um die Plakette, jeder hält genau eines: Schwächungen, Stärkungen, Massenkontrolle oder deine eigenen Schadenszauber",
    ["Glow when low on health – A coloured ring once the unit drops past your mark"] = "Leuchten bei wenig Leben – Ein farbiger Ring, sobald das Ziel unter deine Marke fällt",
    ["Arrows beside your target – Two arrows pointing in at the bar"] = "Pfeile neben deinem Ziel – Zwei Pfeile, die von beiden Seiten auf die Leiste zeigen",
    ["Mark on the focus plate – A short text, so target and focus stay apart at a glance"] = "Merkzeichen auf der Fokus-Plakette – Ein kurzer Text, damit Ziel und Fokus auf einen Blick auseinanderbleiben",
    ["Preset – One click for a wide, flat, dark look, and one to put the small plates back"] = "Vorlage – Ein Klick für ein breites, flaches, dunkles Aussehen, und einer zurück zu den kleinen Plaketten",
    ["Two of the six slots sit beside the plate as a column, which was not possible before. And two rows can no longer land on top of each other: giving a slot something takes it away from the slot that had it."] = "Zwei der sechs Plätze stehen als Spalte neben der Plakette, was vorher nicht ging. Und zwei Reihen können nicht mehr übereinander landen: was du einem Platz gibst, verliert der Platz, der es vorher hatte.",
    ["The cast bar can name who the cast is aimed at, your own name coloured."] = "Die Zauberleiste kann nennen, auf wen gezaubert wird — dein eigener Name eingefärbt.",
    ["Twist zones – The swing bar answers what you may press now instead of counting down"] = "Twist-Zonen – Die Schwungleiste beantwortet, was du jetzt drücken darfst, statt herunterzuzählen",
    ["Rotation helper – A short sequence rather than a single next step, worked out from your weapon and cast speed"] = "Rotations-Hilfe – Eine kurze Abfolge statt eines einzelnen nächsten Schritts, berechnet aus deinem Waffen- und Zaubertempo",
    ["The seal you twist into may be any other seal, not only the two that arrive at level 64."] = "Das Siegel, in das du wechselst, darf jedes andere Siegel sein, nicht nur die beiden, die auf Stufe 64 kommen.",
    ["Sections no longer fold away. Long pages fold at the gear on a row instead, which says something a section expander never could: the rows behind it belong to the switch it sits on."] = "Abschnitte klappen nicht mehr zu. Lange Seiten klappen stattdessen am Zahnrad einer Zeile auf, und das sagt etwas, was ein Abschnitts-Aufklapper nie konnte: die Zeilen dahinter gehören dem Schalter, auf dem es sitzt.",
    ["Controls line up down a page now, and a switch sits in the middle of its row."] = "Bedienelemente fluchten jetzt untereinander, und ein Schalter sitzt mittig in seiner Zeile.",
    -- Vier Nachzuegler
    ["Darken enemies out of combat"] = "Gegner außerhalb des Kampfes abdunkeln",
    ["Dims enemies that are not fighting anyone, so the ones that are stand out. Never your own target."] = "Dunkelt Gegner ab, die gegen niemanden kämpfen, damit die kämpfenden hervortreten. Nie dein eigenes Ziel.",
    ["Darken to (%)"] = "Abdunkeln auf (%)",
    ["Cast bars in front of other plates"] = "Zauberleisten vor anderen Plaketten",
    ["In a pull the plates overlap and a cast bar can end up behind the plate in front of it."] = "Beim Pull überlappen die Plaketten, und eine Zauberleiste kann hinter der Plakette davor verschwinden.",
    ["Highlight strength"] = "Stärke der Hervorhebung",
    ["Hitbox width (%)"] = "Trefferfläche Breite (%)",
    ["Clickable plate area. 100 leaves the game's own size untouched. Stored in the profile."] = "Anklickbare Fläche der Plakette. 100 lässt die Größe des Spiels unangetastet. Liegt im Profil.",
    ["Hitbox height (%)"] = "Trefferfläche Höhe (%)",
    -- Wechsel verloren
    -- Gewehrschuss
    ["Rifle"] = "Gewehrschuss",
    -- Aktionszeile
    ["Action text size"] = "Größe der Aktionszeile",
    ["The line that names what to press. 0 follows the general text size."] = "Die Zeile, die sagt, was zu drücken ist. 0 folgt der allgemeinen Textgröße.",
    -- Tempo- und Siegel-Timer-Groesse
    ["Seal timer text size"] = "Größe des Siegel-Timers",
    ["The countdown on the seal icons. 0 scales it with the icon."] = "Der Countdown auf den Siegelsymbolen. 0 richtet ihn nach der Symbolgröße.",
    -- Warnzeile
    ["Warning text size"] = "Größe der Warnzeile",
    ["The red and yellow warnings on the bar. 0 follows the action text size."] = "Die roten und gelben Warnungen auf der Leiste. 0 folgt der Größe der Aktionszeile.",
    -- Bedingungen je Eintrag
    ["Narrows this icon to a number of stacks, or to the last seconds before it runs out."] = "Schränkt dieses Symbol auf eine Stapelzahl ein, oder auf die letzten Sekunden vor dem Ablaufen.",
    ["Only from stacks"] = "Erst ab Stapeln",
    ["0 = any number of stacks."] = "0 = jede Stapelzahl.",
    ["Only in the last seconds"] = "Nur in den letzten Sekunden",
    ["0 = at any time. Otherwise the icon appears only this close to running out."] = "0 = jederzeit. Sonst erscheint das Symbol erst so kurz vor dem Ablaufen.",
    -- Einheit je Gruppe
    ["Watch this unit"] = "Diese Einheit beobachten",
    ["Whose auras this group reads. The default is what the group type has always used."] = "Wessen Auren diese Gruppe liest. Der Standard ist das, was die Gruppenart schon immer benutzt hat.",
    ["You"] = "Du",
    ["Target"] = "Ziel",
    ["Focus"] = "Fokus",
    -- Nur eigene Auren
    ["Only what I cast myself"] = "Nur was ich selbst gewirkt habe",
    ["Off counts the aura no matter who put it there - for a raid debuff that anyone may apply."] = "Ausgeschaltet zählt die Aura, egal wer sie gesetzt hat — für eine Schlachtzugs-Schwächung, die jeder auflegen darf.",
    -- Sortierung
    ["Fixed keeps the order you added them in. The other two reorder live by what is left."] = "Fest behält die Reihenfolge, in der du sie hinzugefügt hast. Die beiden anderen ordnen laufend nach der Restzeit.",
    ["As added"] = "Wie hinzugefügt",
    ["Least time left first"] = "Kürzeste Restzeit zuerst",
    ["Most time left first"] = "Längste Restzeit zuerst",
    -- Patch notes 1.42.0
    ["Practice – A swing clock that runs on its own, with your own keys and a verdict on every swing"] = "Übung – Eine Schlaguhr, die von allein läuft, mit deinen eigenen Tasten und einem Urteil auf jeden Schlag",
    ["Next action – An icon of the one thing to press, wherever you put it"] = "Nächste Aktion – Ein Symbol für das eine, was du drücken sollst, an einer Stelle deiner Wahl",
    ["Latency – Calibrate the delay a twist has to beat, with its own multiplier and offset"] = "Latenz – Kalibriere die Verzögerung, die ein Twist schlagen muss, mit eigenem Multiplikator und Versatz",
    ["Shade the deadzone – The tail of the swing a cast can no longer cross"] = "Totzone einfärben – Das Ende des Schlags, das ein Wirkvorgang nicht mehr überqueren kann",
    ["Show the global cooldown bar – A strip reaching to the moment the cooldown frees up"] = "Leiste der globalen Abklingzeit zeigen – Ein Streifen bis zu dem Moment, in dem die Abklingzeit frei wird",
    ["When to show the bar – Always, in combat, while a seal is up, or either"] = "Wann die Leiste erscheint – Immer, im Kampf, solange ein Siegel liegt, oder beides",
    ["Colour the bar by – The zone the swing is in, or the seal you are carrying"] = "Leiste einfärben nach – Der Zone, in der der Schlag steht, oder dem Siegel, das du trägst",
    ["Detach from the bar – The seal icons take their own position, with a cooldown sweep"] = "Von der Leiste lösen – Die Siegelsymbole bekommen eine eigene Position, mit Abklingzeit-Wischer",
    ["Suggest Judgement – Offered only with room to re-seal afterwards, and off until you ask"] = "Richturteil vorschlagen – Nur mit Platz zum Nachsiegeln danach, und aus, bis du es einschaltest",
    ["Textures, border, font, frame layer, marker width and the two readouts inside the bar are yours to set, and every seal has its own colour."] = "Texturen, Rand, Schrift, Rahmenebene, Markenbreite und die beiden Anzeigen in der Leiste liegen bei dir, und jedes Siegel hat seine eigene Farbe.",
    -- Patch notes 1.42.0
    ["The twist is now called twist in every language, the word paladins use themselves. German called it Siegelwechsel; the helper and its window are named after the twist instead."] = "Der Twist heißt jetzt in jeder Sprache Twist, so wie Paladine ihn selbst nennen. Im Deutschen hieß er Siegelwechsel; die Hilfe und ihr Fenster sind stattdessen nach dem Twist benannt.",
    ["The cue for a landed twist no longer guesses. It used to fire the moment a seal went out inside the window, which is a prediction the server can disagree with. Now the combat log has to show a swing landing with both seals up and the held seal's own damage behind it. Without that, nothing sounds."] = "Die Rückmeldung für einen gelandeten Twist rät nicht mehr. Früher kam sie, sobald ein Siegel im Fenster hinausging — eine Vorhersage, der der Server widersprechen kann. Jetzt muss das Kampflog einen Schlag zeigen, der mit beiden Siegeln landet, und dahinter den Schaden des gehaltenen Siegels. Ohne das bleibt es still.",
    -- Patch notes 1.42.0
    ["Switching the module off used to leave the bag bar, the latency bar and Action Bar 1's twelve buttons behind until a /reload. All three come back on their own now."] = "Das Modul abzuschalten ließ die Taschenleiste, die Latenzleiste und die zwölf Knöpfe von Aktionsleiste 1 bis zu einem /reload zurück. Alle drei kommen jetzt von allein wieder.",
    ["Rows that span the page now start their control where their neighbours do, instead of each sizing its own label."] = "Zeilen über die ganze Seitenbreite beginnen ihr Bedienelement jetzt dort, wo ihre Nachbarn es tun, statt jede ihre eigene Beschriftung zu bemessen.",
    -- Patch notes 1.42.0
    ["Watch this unit – A group can follow your target, your focus or your pet instead of you"] = "Diese Einheit beobachten – Eine Gruppe darf deinem Ziel, deinem Fokus oder deinem Begleiter folgen statt dir",
    ["Only what I cast myself – A group can require the aura to be your own, not anyone's"] = "Nur was ich selbst gewirkt habe – Eine Gruppe darf verlangen, dass die Aura deine eigene ist und nicht irgendeine",
    ["Order – Sort a group by the time left instead of the order you added things in"] = "Reihenfolge – Eine Gruppe nach der Restzeit sortieren statt nach der Reihenfolge, in der du sie gefüllt hast",
    ["Conditions belong to the individual entry now, not only to the kind of group it sits in. One entry can ask for a stack count or for the last few seconds while its neighbours ask for nothing."] = "Bedingungen gehören jetzt zum einzelnen Eintrag, nicht mehr nur zur Art der Gruppe, in der er steht. Ein Eintrag darf eine Stapelzahl oder die letzten Sekunden verlangen, während seine Nachbarn nichts verlangen.",
    ["Cast bars in front of other plates – So the cast you are watching is not hidden behind the plate beside it"] = "Zauberleisten vor anderen Plaketten – Damit der Zauber, den du beobachtest, nicht hinter der Plakette daneben verschwindet",
    ["Darken enemies out of combat – With its own strength, so an idle mob reads as idle at a glance"] = "Gegner außerhalb des Kampfes abdunkeln – Mit eigener Stärke, damit ein untätiger Gegner auf einen Blick untätig aussieht",
    ["Highlight strength – How far the plate under your cursor lifts out of the row"] = "Stärke der Hervorhebung – Wie weit sich die Plakette unter dem Zeiger aus der Reihe hebt",
    ["The clickable area is measured from the plate now instead of assumed, so the width and height settings land where your cursor really is."] = "Die anklickbare Fläche wird jetzt an der Plakette gemessen statt angenommen, also landen die Regler für Breite und Höhe dort, wo dein Zeiger wirklich ist.",
    ["A dropdown with more entries than fit on screen scrolls instead of running off the bottom, and a label that had grown too long fits its row again."] = "Ein Klappmenü mit mehr Einträgen, als auf den Bildschirm passen, scrollt jetzt statt unten hinauszulaufen, und eine zu lang gewordene Beschriftung passt wieder in ihre Zeile.",
    -- Patch notes 1.43.0
    ["Compatibility"] = "Kompatibilität",
    ["The character window stayed empty on clients we had never named. The panel asked whether the client called itself one of two specific versions and refused every other one, including clients that have exactly the frames it needs. It now asks for the one thing it cannot work without. Enchants, sockets and item stats were missing for the same reason and return with it."] = "Das Charakterfenster blieb auf Clients leer, die wir nie benannt hatten. Die Anzeige fragte, ob der Client sich als eine von zwei bestimmten Versionen ausgibt, und wies jede andere ab, auch solche, die genau die Fenster haben, die sie braucht. Jetzt fragt sie nach der einen Sache, ohne die sie nicht arbeiten kann. Verzauberungen, Sockel und Gegenstandswerte fehlten aus demselben Grund und kommen mit zurück.",
    ["Hit rating, haste rating and spell hit rating appear on Wrath-based clients too. They were tied to a single version by name, although the game there has those stats."] = "Trefferwertung, Tempowertung und Zaubertrefferwertung erscheinen jetzt auch auf Clients, die auf Wrath beruhen. Sie hingen namentlich an einer einzigen Version, obwohl das Spiel dort diese Werte hat.",
    ["The stat rows Wrath draws in pages with two dropdowns are hidden underneath our own panel now, instead of showing through it."] = "Die Wertezeilen, die Wrath geblättert mit zwei Klappmenüs zeichnet, liegen jetzt versteckt unter unserer eigenen Anzeige, statt durch sie hindurchzuscheinen.",
    ["Titan Reforged – The addon no longer reports itself out of date on the Chinese client, whose build is listed now"] = "Titan Reforged – Das Addon meldet sich auf dem chinesischen Client nicht mehr als veraltet, dessen Version steht jetzt mit in der Liste",
    ["Version detection falls back to the build number whenever a client reports an identifier we have no name for. Such a client used to end up with every version flag false, which left it worse off than a client with no identifier at all, because that one at least fell back to something."] = "Die Versionserkennung fällt auf die Build-Nummer zurück, sobald ein Client eine Kennung meldet, für die wir keinen Namen haben. Ein solcher Client hatte vorher jede Versionsflagge auf falsch stehen und war damit schlechter dran als einer ganz ohne Kennung, denn der fiel wenigstens auf etwas zurück.",
    ["242 texts that nothing in the interface looks up any more are gone from all nine language files, roughly eight percent of each. Renamed settings left them behind: the action bars were given clearer names a while ago and the old entries simply stayed. A check now asks the reverse question after every change, whether every translated text is still in use, so they cannot pile up again."] = "242 Texte, die niemand in der Oberfläche mehr nachschlägt, sind aus allen neun Sprachdateien verschwunden, rund acht Prozent je Datei. Umbenannte Einstellungen ließen sie liegen: die Aktionsleisten bekamen vor einer Weile klarere Namen, und die alten Einträge blieben einfach stehen. Eine Prüfung stellt jetzt nach jeder Änderung die Gegenfrage, ob jeder übersetzte Text noch benutzt wird, damit sich das nicht wieder ansammelt.",
    ["Call button – A fifth totem button for the spells that summon a whole saved totem set, shown only to characters who know one"] = "Ruf-Knopf – Ein fünfter Totemknopf für die Zauber, die ein ganzes gespeichertes Totem-Set stellen, sichtbar nur für Charaktere, die einen davon können",
    ["Icon Strip"] = "Icon-Leiste",
    ["Distance from frame"] = "Abstand vom Fenster",
    ["Spacing between icons"] = "Abstand zwischen Icons",
    ["Racial, PvP trinket and the DR row sit on the same edge of the frame and are placed one after the other, in that order, outwards from the frame."] = "Volksfähigkeit, PvP-Trinket und die DR-Reihe sitzen an derselben Kante des Fensters und werden in dieser Reihenfolge nacheinander nach außen gesetzt.",
    ["Where it sits is set once for all three trackers under Layout, Icon Strip."] = "Wo sie sitzt, wird für alle drei Anzeigen gemeinsam unter Layout, Icon-Leiste eingestellt.",
    ["Gap below each frame. The opponent's pet bar hangs off the bottom of the frame, so a small gap lets it reach into the next one."] = "Abstand unter jedem Fenster. Die Begleiterleiste des Gegners hängt unten aus dem Fenster heraus, bei kleinem Abstand ragt sie also in das nächste hinein.",
    ["Arena: racial, PvP trinket and the DR row now share one icon strip; your chosen side was kept."] = "Arena: Volksfähigkeit, PvP-Trinket und DR-Reihe teilen sich jetzt eine Icon-Leiste; deine gewählte Seite wurde übernommen.",
    ["|cffff5555Arena layout failed:|r %s"] = "|cffff5555Arena-Layout fehlgeschlagen:|r %s",
    ["|cffff5555Arena icon strip error:|r %s"] = "|cffff5555Fehler in der Arena-Icon-Leiste:|r %s",
    ["Drag to reorder. Right-click removes it."] = "Ziehen zum Umsortieren. Rechtsklick entfernt es.",
    ["That icon is added automatically — switch off auto-tracking to remove it."] = "Dieses Symbol kommt automatisch dazu — schalte die automatische Verfolgung aus, um es zu entfernen.",
    ["Drag to reorder. Right-click an icon to remove it."] = "Ziehen zum Umsortieren. Rechtsklick auf ein Symbol entfernt es.",
    ["Nothing in this bar yet. Add a spell or trinket below, or drag one onto the bar."] = "Noch nichts auf dieser Leiste. Füge unten einen Zauber oder Schmuck hinzu, oder zieh einen auf die Leiste.",
    ["+  New cooldown bar"] = "+  Neue Cooldown-Leiste",
    ["+  New buff / proc bar"] = "+  Neue Leiste für Stärkungszauber und Prozesse",
    ["+  New target debuff bar"] = "+  Neue Leiste für Schwächungszauber am Ziel",
    ["+  New missing-buff reminder"] = "+  Neue Erinnerung an fehlende Stärkungszauber",
    ["Buffs & Procs"] = "Stärkungszauber und Prozesse",
    ["Target debuffs"] = "Schwächungszauber am Ziel",
    ["Missing buffs"] = "Fehlende Stärkungszauber",
    ["New name for this bar"] = "Neuer Name für diese Leiste",
    ["Delete this bar and everything on it?"] = "Diese Leiste mit allem darauf löschen?",
    ["That is the last bar — there has to be one."] = "Das ist die letzte Leiste — eine muss bleiben.",
    ["Drag to reorder bars"] = "Ziehen zum Umsortieren der Leisten",
    ["Rename this bar"] = "Diese Leiste umbenennen",
    ["Delete this bar"] = "Diese Leiste löschen",
    ["Duplicate bar"] = "Leiste duplizieren",
    ["Copies the selected bar with all entries and layout settings."] = "Kopiert die gewählte Leiste mit allen Einträgen und Layout-Einstellungen.",
    ["Bar layout"] = "Leistenlayout",
    ["Icon appearance"] = "Aussehen der Symbole",
    ["Icon display"] = "Symbolanzeige",
    ["Movable cooldown bars grouped however you like — procs, defensives, offensives, each with its own look and position."] = "Verschiebbare Cooldown-Leisten, gruppiert wie du willst — Procs, Defensives, Offensives, jede mit eigenem Aussehen und Platz.",
    ["Which IDs should be shown in tooltips? Some types do not exist on this game version and are ignored (e.g. TraitNodeID, SourceID)."] = "Welche IDs sollen in Tooltips angezeigt werden? Manche Typen gibt es auf dieser Spielversion nicht, sie werden ignoriert (z.B. TraitNodeID, SourceID).",
    ["CDM Bars"] = "CDM-Leisten",
    ["Bug Fixes"] = "Fehlerbehebungen",
    ["Bar Glows"] = "Leistenleuchten",
    ["Click to edit this icon's glow."] = "Klicken, um das Leuchten dieses Symbols zu bearbeiten.",
    ["Click an icon to edit its glow."] = "Klicke ein Symbol an, um sein Leuchten zu bearbeiten.",
    ["Nothing in this bar yet. Add a spell or trinket on the CDM Bars tab first."] = "Noch nichts auf dieser Leiste. Füge zuerst im Tab CDM-Leisten einen Zauber oder Schmuck hinzu.",
    ["|cffaaaaaaEach icon can glow while a buff of yours is active — or missing. Click an icon in the preview above, then add one or more watchers; the first whose condition holds paints the icon.|r"] = "|cffaaaaaaJedes Symbol kann leuchten, solange ein Stärkungszauber von dir aktiv ist — oder fehlt. Klicke oben in der Vorschau ein Symbol an und füge einen oder mehrere Wächter hinzu; der erste, dessen Bedingung zutrifft, färbt das Symbol.|r",
    ["|cff888888No icon picked yet.|r"] = "|cff888888Noch kein Symbol gewählt.|r",
    ["Glows: %s"] = "Leuchten: %s",
    ["Glow when"] = "Leuchten wenn",
    ["Buff is active"] = "Stärkungszauber ist aktiv",
    ["Buff is missing"] = "Stärkungszauber fehlt",
    ["Action button glow"] = "Aktionsknopf-Leuchten",
    ["Pulsing fill"] = "Pulsierende Füllung",
    ["Gold (default)"] = "Gold (Standard)",
    ["Pick color..."] = "Farbe wählen …",
    ["Remove this glow"] = "Dieses Leuchten entfernen",
    ["Watches: %s"] = "Wacht über: %s",
    ["Add watcher (buff name / ID)"] = "Wächter hinzufügen (Zaubername / ID)",
    ["|cffaaaaaaNo watcher yet. Most spells put a buff of the same name on you when used — one click below makes this icon glow while that buff is on you. Or type any other buff into the field.|r"] = "|cffaaaaaaNoch kein Wächter. Die meisten Zauber legen beim Wirken einen gleichnamigen Stärkungszauber auf dich — ein Klick unten lässt dieses Symbol leuchten, solange dieser Buff auf dir liegt. Oder trag ins Feld einen beliebigen anderen Buff ein.|r",
    ["Glow while '%s' is on me"] = "Leuchten, solange ‚%s‘ auf mir liegt",
    -- Patch notes 1.44.0
    ["Icon Strip – Racial, trinket and the diminishing-returns row share one edge of the frame in a fixed order, with one set of controls — they can no longer land on top of each other"] = "Icon-Leiste – Volksfähigkeit, Schmuck und die DR-Reihe teilen sich eine Kante des Fensters in fester Reihenfolge, mit einem Satz Regler — sie können nicht mehr aufeinander landen",
    ["The frame layout — order, spacing, grow direction — never actually applied: its hooks were installed before the arena interface had loaded. The frames now report their own moves and the layout follows; during a fight they are protected, so a move mid-round is corrected when it ends."] = "Das Layout der Arenarahmen — Reihenfolge, Abstand, Wuchsrichtung — griff nie: seine Haken wurden gesetzt, bevor die Arena-Oberfläche geladen war. Die Rahmen melden ihre Bewegungen jetzt selbst und das Layout zieht nach; im Kampf sind sie geschützt, ein Zug mitten in der Runde wird an ihrem Ende korrigiert.",
    ["The default gap between frames clears the opponent's pet bar, and the drag box in edit mode covers the whole stack instead of a fixed area."] = "Der Standardabstand zwischen den Rahmen lässt die Begleiterleiste des Gegners frei, und die Ziehfläche im Bearbeiten-Modus deckt den ganzen Stapel ab statt eines festen Bereichs.",
    ["Bar Glows – Any icon can glow while a buff of yours is active or missing: three styles, gold, class or custom color, and one click watches the spell's own buff"] = "Leistenleuchten – Jedes Symbol kann leuchten, solange ein Stärkungszauber von dir aktiv ist oder fehlt: drei Stile, Gold, Klassenfarbe oder eigene Farbe, und ein Klick überwacht den eigenen Buff des Zaubers",
    ["The page is built around a preview that stays put while you scroll: the bar picker with rename, delete and drag-to-reorder on top, under it every icon of the bar at its real size and shape with the real cooldown sweep. Drag reorders, right-click removes."] = "Die Seite ist um eine Vorschau gebaut, die beim Rollen stehen bleibt: oben die Leistenauswahl mit Umbenennen, Löschen und Ziehen zum Umsortieren, darunter jedes Symbol der Leiste in echter Größe und Form mit der echten Abklingspirale. Ziehen sortiert um, Rechtsklick entfernt.",
    ["The page is split into tabs, and the resource bar moved in as one of them. Spells you add belong to the class that added them and no longer show up on your other characters."] = "Die Seite ist in Tabs geteilt, und die Ressourcenleiste ist als einer davon eingezogen. Zauber, die du hinzufügst, gehören der Klasse, die sie angelegt hat, und tauchen auf deinen anderen Charakteren nicht mehr auf.",
    ["The third extra-item slot no longer stretches across the page with its box flung to the far edge."] = "Der dritte Extra-Item-Platz streckt sich nicht mehr über die ganze Seite, mit dem Feld an die äußerste Kante geworfen.",
    ["The interface no longer compares itself with the other game version anywhere; a check keeps such wording out for good."] = "Die Oberfläche vergleicht sich nirgendwo mehr mit der anderen Spielversion; eine Prüfung hält solche Formulierungen dauerhaft draußen.",
    ["Modules with several pages show them as a tab row along the top; when the tabs outgrow the row, two arrows page through it instead of wrapping into a second line."] = "Module mit mehreren Seiten zeigen sie als Tab-Zeile am oberen Rand; wachsen die Tabs über die Zeile hinaus, blättern zwei Pfeile hindurch, statt in eine zweite Zeile umzubrechen.",
    ["The sidebar got shorter: player and target frames, font bars, castbar and cooldown pulse are one entry now, and a new General entry under Reminders collects the former Extras, Character and Bug Fixes rows — the bug fixes as a single tab."] = "Die Seitenleiste ist kürzer geworden: Spieler- und Zielfenster, Font-Bars, Castbar und Cooldown-Pulse sind jetzt ein Eintrag, und ein neuer Eintrag Allgemein unter Erinnerungen sammelt die früheren Zeilen Kleinkram, Charakter und Fehlerbehebungen — die Fehlerbehebungen als ein einziger Tab.",
    ["Typing into an add field and then clicking the button beside it silently did nothing; the typed text only counted after pressing Enter. Buttons now take the field's text with them."] = "In ein Hinzufügen-Feld zu tippen und daneben auf den Knopf zu klicken tat still gar nichts; der getippte Text zählte erst nach der Eingabetaste. Knöpfe nehmen den Text des Feldes jetzt mit.",
    -- Patch notes 1.45.0
    ["The item level on equipment links sits after the link now, not inside its brackets. Some clients re-check link text against their own data, and the changed text turned the link into the name of whatever quest carried that number."] = "Die Gegenstandsstufe an Ausrüstungslinks steht jetzt hinter dem Link, nicht mehr in seinen Klammern. Manche Clients prüfen Linktexte gegen ihre eigenen Daten neu, und der veränderte Text machte aus dem Link den Namen der Quest mit dieser Nummer.",
    ["A spell no longer shows up on another class just because that class owns a different spell with the same name. Entries respect their class stamp on the bars, and old entries are adopted by spell ID instead of by name."] = "Ein Zauber taucht nicht mehr bei einer anderen Klasse auf, nur weil die einen anderen Zauber mit demselben Namen besitzt. Einträge achten auf den Leisten auf ihren Klassenstempel, und alte Einträge werden über die Zauberkennung zugeordnet statt über den Namen.",
    ["The bundled media library silently dropped font registrations when no other addon shipped a newer copy of it; the addon font now registers on every install."] = "Die mitgelieferte Medienbibliothek verwarf Schrift-Registrierungen still, wenn kein anderes Addon eine neuere Kopie von ihr mitbrachte; die Addon-Schrift registriert sich jetzt bei jeder Installation.",
    ["Rename... – In the set's right-click menu and on the sets page; icon, contents and talent binding move along with the name"] = "Umbenennen... – Im Rechtsklick-Menü des Sets und auf der Sets-Seite; Symbol, Inhalt und Talentwahl-Bindung ziehen mit dem Namen um",
    ["Optimize My FPS and Graphics – A proven set of graphics settings with a one-time backup; the restore button next to it brings your old values back"] = "Meine FPS und Grafik optimieren – Ein bewährter Satz Grafikeinstellungen mit einmaliger Sicherung; der Wiederherstellen-Knopf daneben bringt deine alten Werte zurück",
    ["Fonts & Colors – A new tab: global font with outline mode, optionally for all game texts, plus class and resource colors with a reset on every row"] = "Schriftarten & Farben – Ein neuer Tab: globale Schriftart mit Konturmodus, auf Wunsch für alle Spieltexte, dazu Klassen- und Ressourcenfarben mit Zurücksetzen an jeder Zeile",
    ["Developer – Suppress Lua errors, switch tooltip IDs and reset all settings from a new section on the General tab"] = "Entwickler – Lua-Fehler unterdrücken, Tooltip-IDs schalten und alle Einstellungen zurücksetzen, in einem neuen Abschnitt des Allgemein-Tabs",
    ["The General tab is organised in sections on a two-column grid like the rest of the window. The new tab ships a texture file: restart the client once after updating, a /reload alone will not show the reset arrows."] = "Der Allgemein-Tab ist in Abschnitte auf einem zweispaltigen Raster gegliedert wie der Rest des Fensters. Der neue Tab bringt eine Texturdatei mit: den Client nach dem Update einmal neu starten, ein /reload allein zeigt die Zurücksetzen-Pfeile nicht.",
    ["The enlargement stays off on Wrath-based clients (Titan Reforged): their quest log is already the wide two-pane frame, and enlarging it pushed the detail pane into the button row."] = "Die Vergrößerung bleibt auf Wrath-basierten Clients (Titan Reforged) aus: deren Questlog ist bereits das breite zweispaltige Fenster, und die Vergrößerung schob die Detailseite in die Knopfreihe.",
    ["Long dropdown lists open upwards when there is no room below. They used to run off the bottom edge of the screen, where the last entries could never be scrolled into view."] = "Lange Klappmenüs öffnen nach oben, wenn unter ihnen kein Platz ist. Sie liefen bisher über die untere Bildschirmkante hinaus, wo sich die letzten Einträge nie ins Bild rollen ließen.",
    ["Core"] = "Kern",
    ["Opacity"] = "Deckkraft",
    ["Durability"] = "Haltbarkeit",
    ["Talent points"] = "Talentpunkte",
    ["Pulse"] = "Pulsieren",
    ["Steady"] = "Dauerhaft",
    ["Background"] = "Hintergrund",
    ["Low"] = "Niedrig",
    ["Medium"] = "Mittel",
    ["High"] = "Hoch",
    ["Dialog"] = "Dialog",
    ["Click an icon to jump to its settings."] = "Ein Klick auf ein Symbol springt zu seiner Einstellung.",
    ["Middle-click: hide until the next loading screen."] = "Mittelklick: bis zum nächsten Ladebildschirm ausblenden.",
    ["Nothing to preview: every reminder is switched off."] = "Nichts anzuzeigen: alle Erinnerungen sind ausgeschaltet.",
    ["Show effects missing on others"] = "Fehlende Effekte bei anderen anzeigen",
    ["Scans your party or raid for class buffs you could cast and reminds you when someone lacks one."] = "Durchsucht Gruppe oder Schlachtzug nach Klassenbuffs, die du wirken könntest, und erinnert dich, wenn sie jemandem fehlen.",
    ["Missing on %s: %s"] = "Fehlt bei %s: %s",
    ["In raids (minutes)"] = "Im Schlachtzug (Minuten)",
    ["In dungeons (minutes)"] = "In Instanzgruppen (Minuten)",
    ["0 uses the global warn threshold."] = "0 nutzt die globale Warnschwelle.",
    ["Preferred food"] = "Bevorzugte Nahrung",
    ["Preferred flask or elixir"] = "Bevorzugtes Fläschchen oder Elixier",
    ["Preferred weapon enhancement"] = "Bevorzugte Waffenverstärkung",
    ["Automatic (best in bags)"] = "Automatisch (bestes im Beutel)",
    ["Click to use."] = "Klicken zum Benutzen.",
    ["Attach reminders to the cursor"] = "Erinnerungen am Cursor verankern",
    ["Shows small copies of the current reminders next to the mouse cursor."] = "Zeigt kleine Kopien der aktuellen Erinnerungen neben dem Mauszeiger.",
    ["Helpers"] = "Helfer",
    ["Queue countdown, buff minigame helper and class trainer book in one place."] = "Warteschlangen-Countdown, Minispiel-Helfer und Trainer-Buch an einem Ort.",
    ["Open group board"] = "Gruppensuche öffnen",
    ["Scans chat for people forming groups and lists them by Classic/TBC instance in a window (/vlfg or the button below)."] = "Durchsucht den Chat nach Leuten, die Gruppen bilden, und listet sie nach Classic-/TBC-Instanz in einem Fenster (/vlfg oder der Knopf unten).",
    ["Show minimap button"] = "Minimap-Button anzeigen",
    ["PvP Settings"] = "PvP-Einstellungen",
    ["Fullscreen"] = "Vollbild",
    ["Fullscreen dialog"] = "Vollbild-Dialog",
    ["Tooltip"] = "Tooltip",
    ["Orientation"] = "Ausrichtung",
    ["Horizontal"] = "Horizontal",
    ["Vertical (up)"] = "Vertikal (aufwärts)",
    ["Vertical (down)"] = "Vertikal (abwärts)",
    ["Fill opacity"] = "Füll-Deckkraft",
    ["Below 100 the world shows through the filled part of the bar."] = "Unter 100 scheint die Spielwelt durch den gefüllten Teil der Leiste.",
    ["The fill fades into a second colour towards its end."] = "Die Füllung geht zum Ende hin in eine zweite Farbe über.",
    ["Name inside the bar"] = "Name in der Leiste",
    ["Anchors the name at the left edge inside the health bar instead of above it — the right edge stays free for the health text."] = "Verankert den Namen am linken Rand in der Gesundheitsleiste statt darüber — der rechte Rand bleibt für den Gesundheitstext frei.",
    ["Show plates for enemy pets"] = "Plaketten für feindliche Begleiter anzeigen",
    ["Divider line on the target's bar"] = "Teilungslinie auf der Ziel-Leiste",
    ["Draws a thin vertical line at the given percent of the health bar — an execute marker."] = "Zeichnet eine dünne senkrechte Linie beim angegebenen Prozentwert der Gesundheitsleiste — eine Hinrichtungs-Markierung.",
    ["Line position (%)"] = "Position der Linie (%)",
    ["Only on your target"] = "Nur bei deinem Ziel",
    ["Spell name"] = "Zaubername",
    ["Colour the last tick"] = "Letzten Tick einfärben",
    ["Show latency text"] = "Latenztext anzeigen",
    ["Vertical"] = "Vertikal",
    ["Automatic stacks a side slot as a column and a top or bottom slot as a row."] = "Automatisch stapelt einen seitlichen Platz als Spalte und einen oberen oder unteren Platz als Reihe.",
    ["Show older versions"] = "Ältere Versionen anzeigen",
    ["%d broken numeric values were removed from the settings so they can be saved again."] = "%d defekte Zahlenwerte wurden aus den Einstellungen entfernt, damit sie wieder gespeichert werden können.",
    ["Widen window"] = "Fenster verbreitern",
    ["Extra width for the friends window so long names, notes and zones fit on one line. 0 keeps Blizzard's width."] = "Zusätzliche Breite für das Freundesfenster, damit lange Namen, Notizen und Zonen in eine Zeile passen. 0 behält Blizzards Breite.",
    ["Classic+ keeps Blizzard's layout with extras. Modern adds the dark chrome and moves all stats into a panel on the right of the character window."] = "Classic+ behält Blizzards Aufbau mit Extras. Modern ergänzt die dunkle Optik und verschiebt alle Werte in ein Panel rechts am Charakterfenster.",
    ["Overrides the group switch for this entry alone - e.g. to track a buff someone else casts on you."] = "Übersteuert den Gruppenschalter nur für diesen Eintrag - z. B. um einen Stärkungszauber zu verfolgen, den jemand anderes auf dich wirkt.",
    ["Group default"] = "Gruppenstandard",
    ["Anyone's"] = "Von jedem",
    ["Use conditions"] = "Bedingungen verwenden",
    ["Unticked parks this entry: it keeps its settings but never shows. The gear holds moving, removing and per-entry settings."] = "Ohne Häkchen ist dieser Eintrag geparkt: Er behält seine Einstellungen, wird aber nie angezeigt. Das Zahnrad enthält Verschieben, Entfernen und Einstellungen je Eintrag.",
    ["Talent Window"] = "Talentfenster",
    ["Shows all three talent trees side by side in one window."] = "Zeigt alle drei Talentbäume nebeneinander in einem Fenster.",
    ["Points left: %d"] = "Punkte übrig: %d",
    ["TALENTS"] = "TALENTE",
    ["Open Blizzard's talent window"] = "Blizzards Talentfenster öffnen",
    ["For glyphs and everything this window does not cover."] = "Für Glyphen und alles, was dieses Fenster nicht abdeckt.",
    ["|cffaaaaaaAll three talent trees side by side, with live ranks and click-to-learn. Glyphs stay in Blizzard's window, one button away.|r"] = "|cffaaaaaaAlle drei Talentbäume nebeneinander, mit Live-Rängen und Lernen per Klick. Glyphen bleiben in Blizzards Fenster, einen Knopf entfernt.|r",
    ["Replace Blizzard's talent window"] = "Blizzards Talentfenster ersetzen",
    ["Opening talents shows this window instead. Turn it off to get Blizzard's one-tree window back."] = "Beim Öffnen der Talente erscheint stattdessen dieses Fenster. Schalte es aus, um Blizzards Ein-Baum-Fenster zurückzubekommen.",
    ["Open talent window"] = "Talentfenster öffnen",
    ["See-through"] = "Durchsichtig",
    ["Hide the box fill and labels while editing, so you can see the interface you are aligning. The thin borders stay."] = "Blendet Füllung und Beschriftung der Kästen beim Bearbeiten aus, damit du die Oberfläche siehst, die du ausrichtest. Die dünnen Ränder bleiben.",
    -- Patch notes 1.46.0
    ["Options"] = "Optionen",
    ["Talents"] = "Talente",
    ["The page opens with two modes: Standard keeps Blizzard's bars with the skin rows, Modern runs the addon's own bars with a live preview, a per-bar background, button press and hover tints and an XP bar texture"] = "Die Seite öffnet mit zwei Modi: Standard behält Blizzards Leisten samt Anstrich-Zeilen, Modern betreibt die addon-eigenen Leisten mit Live-Vorschau, Hintergrund je Leiste, Druck- und Schwebe-Tönung der Knöpfe und einer Textur für die Erfahrungsleiste",
    ["Modern – Third player cast bar style: flat look with name and timer on the bar, plus bar texture, border, a coloured last tick and a latency readout"] = "Modern – Dritter Stil der Spieler-Zauberleiste: flache Optik mit Name und Zeit auf dem Balken, dazu Balkentextur, Rahmen, ein gefärbter letzter Tick und eine Latenzanzeige",
    ["The options page carries a live preview; clicking its icon or bar jumps to the matching section"] = "Die Optionsseite trägt eine Live-Vorschau; ein Klick auf ihr Symbol oder ihren Balken springt zum passenden Abschnitt",
    ["Enchant and gem displays no longer displace each other on non-English clients, and Chinese enchant text is no longer cut mid-character"] = "Verzauberungs- und Sockelanzeige verdrängen einander auf nicht-englischen Clients nicht mehr, und chinesischer Verzauberungstext wird nicht mehr mitten im Zeichen abgeschnitten",
    ["Tracked entries sit two per row, each with a gear: park an entry without deleting it, move or remove it, set conditions, and override Only what I cast myself for that entry alone"] = "Verfolgte Einträge stehen zu zweit je Zeile, jeder mit Zahnrad: einen Eintrag parken statt löschen, verschieben oder entfernen, Bedingungen setzen und Nur was ich selbst gewirkt habe für diesen Eintrag allein übersteuern",
    ["See-through – Hides the box fill and labels while editing, so you can see the interface you are aligning"] = "Durchsichtig – Blendet Füllung und Beschriftung der Kästen beim Bearbeiten aus, damit du die Oberfläche siehst, die du ausrichtest",
    ["Coordinates appear on the box while dragging or nudging, and the window being snapped to pulses white"] = "Beim Ziehen und Feinrücken stehen die Koordinaten direkt am Kasten, und das Fenster, an dem eingerastet wird, pulsiert weiß",
    ["The loot window can be moved on Wrath clients"] = "Das Beutefenster lässt sich auf Wrath-Clients verschieben",
    ["Widen window – Extra width so long names, notes and zones fit on one line"] = "Fenster verbreitern – Zusatzbreite, damit lange Namen, Notizen und Gebiete in eine Zeile passen",
    ["The close glyph of every window is larger now"] = "Das Schließen-Zeichen aller Fenster ist jetzt größer",
    ["Three tabs with a pinned live preview, a name-in-bar option and thousands separators on health numbers"] = "Drei Tabs mit angepinnter Live-Vorschau, einer Name-in-der-Leiste-Option und Tausendertrennern bei den Gesundheitszahlen",
    ["Gear rows open inside their own column, aura rows align per row, helper tools share one tab, and the pinned page header of the last visited tab is cleared on switching"] = "Zahnrad-Zeilen öffnen in ihrer eigenen Spalte, Auren-Zeilen richten sich je Zeile aus, Helfer-Werkzeuge teilen sich einen Tab, und der angepinnte Seitenkopf des zuletzt besuchten Tabs wird beim Wechseln weggeräumt",
    ["Only the last five versions build at once; a button loads the older ones"] = "Es werden nur die letzten fünf Versionen auf einmal aufgebaut; ein Knopf lädt die älteren nach",
    ["Orientation, fill opacity, frame strata and a live preview on the options page"] = "Ausrichtung, Füll-Deckkraft, Rahmenebene und eine Live-Vorschau auf der Optionsseite",
    ["A profile string can carry a selection: chosen modules, the window layout, talent overrides, and the account-wide fonts and colours"] = "Eine Profilzeichenkette kann eine Auswahl tragen: gewählte Module, das Fensterlayout, Talent-Übersteuerungen und die kontoweiten Schriften und Farben",
    ["Per-rule switches with class-coloured names, a group scan for missing buffs, preferred food, flask and weapon oil, raid and dungeon thresholds, glow styles, scale and a live preview; middle-click hides a reminder until the next loading screen"] = "Schalter je Regel mit klassengefärbten Namen, ein Gruppenscan für fehlende Stärkungszauber, bevorzugtes Essen, Fläschchen und Waffenöl, Schwellen für Schlachtzug und Dungeon, Leuchtstile, Skalierung und eine Live-Vorschau; Mittelklick versteckt eine Erinnerung bis zum nächsten Ladebildschirm",
    ["Broken numeric values are removed before saving and reported at the next login. A single such value used to reset every setting of the account to defaults"] = "Defekte Zahlenwerte werden vor dem Speichern entfernt und beim nächsten Anmelden gemeldet. Ein einziger solcher Wert setzte bisher sämtliche Einstellungen des Kontos auf die Standardwerte zurück",
    ["Totemic Recall stands as its own button after the elements on Wrath clients"] = "Der Totem-Rückruf steht auf Wrath-Clients als eigener Knopf hinter den Elementen",
    ["Talent Window – All three talent trees side by side with live ranks and click-to-learn on Wrath clients; glyphs stay one button away"] = "Talentfenster – Alle drei Talentbäume nebeneinander mit Live-Rängen und Lernen per Klick auf Wrath-Clients; Glyphen bleiben einen Knopf entfernt",
    ["The string is selected - press Ctrl+C to copy it."] = "Die Zeichenkette ist markiert – Strg+C kopiert sie.",
    ["%d characters"] = "%d Zeichen",
    ["Paste the string here with Ctrl+V."] = "Füge die Zeichenkette hier mit Strg+V ein.",
    ["String captured - %d characters."] = "Zeichenkette erfasst – %d Zeichen.",
    ["Partial string: anything missing is taken from your active profile."] = "Teil-Zeichenkette: Fehlendes wird aus deinem aktiven Profil übernommen.",
    ["Unticked parts keep your current settings."] = "Abgewählte Teile behalten deine aktuellen Einstellungen.",
    ["Profile '%s' imported. Switch to it now and reload the UI?"] = "Profil „%s“ importiert. Jetzt wechseln und die Oberfläche neu laden?",
    ["Switch and reload"] = "Wechseln und neu laden",
    ["Save a backup copy"] = "Sicherungskopie anlegen",
    ["Creates a dated copy of the active profile as a restore point. Nothing switches - the copy just sits in the profile list."] = "Legt eine datierte Kopie des aktiven Profils als Wiederherstellungspunkt an. Es wird nichts gewechselt – die Kopie steht einfach in der Profilliste.",
    ["Backup '%s' created."] = "Sicherung „%s“ angelegt.",
    ["Go back"] = "Zurück",
    ["Pixel-true plate size"] = "Pixelgenaue Plakettengröße",
    ["Sizes the plates in screen pixels instead of interface units: height 27 is then 27 pixels on any monitor and UI scale."] = "Bemisst die Plaketten in Bildschirmpixeln statt in Interface-Einheiten: Höhe 27 ist dann auf jedem Monitor und bei jeder UI-Skala 27 Pixel.",
    -- Patch notes 1.47.0
    ["The boxes now cover their window exactly, in the same dark look as the rest of the interface, with the name centred and shown in orange when the window is docked to another one"] = "Die Kästen decken ihr Fenster jetzt exakt ab, im selben dunklen Stil wie der Rest der Oberfläche, mit mittigem Namen, der orange wird, wenn das Fenster an ein anderes angedockt ist",
    ["Outside the editor the small drag handle stays, so an unlocked cooldown bar still accepts dropped spells and test previews stay visible"] = "Außerhalb des Editors bleibt der kleine Greifkasten, damit eine entsperrte Abklingzeiten-Leiste weiter abgelegte Zauber annimmt und Testvorschauen sichtbar bleiben",
    ["The cloak equipment slot was translated with the navigation word for back in six languages and now reads correctly everywhere"] = "Der Umhang-Ausrüstungsplatz war in sechs Sprachen mit dem Navigationswort für Zurück übersetzt und heißt jetzt überall richtig",
    ["Pixel-true plate size – Sizes the plates in screen pixels, so height 27 is 27 pixels on any monitor and interface scale"] = "Pixelgenaue Plakettengröße – Bemisst die Plaketten in Bildschirmpixeln; Höhe 27 ist damit auf jedem Monitor und bei jeder Oberflächen-Skalierung 27 Pixel",
    ["Plate sizes now mean exactly what the sliders say: the game no longer secretly enlarges the target's plate or shrinks distant ones, and the live preview matches the game — making the target larger is now solely the job of the target plate scale option"] = "Plakettengrößen bedeuten jetzt exakt, was die Regler sagen: das Spiel vergrößert die Plakette des Ziels nicht mehr heimlich und verkleinert entfernte nicht mehr, und die Live-Vorschau stimmt mit dem Spiel überein — das Ziel größer zu zeichnen ist jetzt allein Sache der Ziel-Skalierungs-Option",
    ["Save a backup copy – One click keeps a dated copy of the active profile as a restore point"] = "Sicherungskopie anlegen – Ein Klick legt eine datierte Kopie des aktiven Profils als Wiederherstellungspunkt ab",
    ["Exporting opens a proper window with the string already selected, and importing shows a preview first: rename the profile and untick the parts you do not want before anything is written"] = "Der Export öffnet ein richtiges Fenster mit bereits markierter Zeichenkette, und der Import zeigt zuerst eine Vorschau: Profil umbenennen und Unerwünschtes abwählen, bevor irgendetwas geschrieben wird",
    ["Export strings are compressed to a fraction of their old length and fit in a chat message; strings from older versions still import"] = "Export-Zeichenketten sind komprimiert und nur noch ein Bruchteil so lang, sie passen in eine Chatnachricht; Zeichenketten aus älteren Versionen lassen sich weiter importieren",
    ["On the Wrath client the talent tooltip showed a placeholder instead of the description, and the talent key would open the window but not close it — both fixed"] = "Auf dem Wrath-Client zeigte der Talent-Tooltip einen Platzhalter statt der Beschreibung, und die Talent-Taste öffnete das Fenster, schloss es aber nicht — beides behoben",
    ["%s Locked"] = "%s gesperrt",
    ["|cffffffffLOSS OF CONTROL|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffffKEINE KONTROLLE|r\n|cffaaaaaaZiehen oder Pfeiltasten|r",
    ["%.1f seconds"] = "%.1f Sekunden",
    ["Loss of control mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Press the button again to finish."] = "Regler für Keine Kontrolle aktiv. |cff9b6cffZiehe den lila Kasten|r oder benutze die |cff9b6cffPfeiltasten|r (UMSCHALT = 5 Pixel). Drücke den Knopf erneut, um fertig zu werden.",
    ["Preview"] = "Vorschau",
    ["Loss of Control"] = "Keine Kontrolle",
    ["Shows what is controlling you right now -- stun, fear, root, silence, disarm or a school lockout -- with the effect icon, its name and the time left. Where two effects run at once the one that matters is shown large, and the next one as a small icon beside it."] = "Zeigt, was dich gerade kontrolliert – Betäubung, Furcht, Wurzeln, Stille, Entwaffnung oder eine gesperrte Zauberschule – mit dem Symbol des Effekts, seinem Namen und der Restzeit. Laufen zwei Effekte gleichzeitig, steht der wichtigere groß da und der nächste als kleines Symbol daneben.",
    ["Show loss of control alert"] = "Anzeige für Keine Kontrolle einblenden",
    ["Show in"] = "Anzeigen in",
    ["Arena and battlegrounds"] = "Arena und Schlachtfelder",
    ["Arena only"] = "Nur Arena",
    ["Name font size"] = "Schriftgröße Name",
    ["Timer font size"] = "Schriftgröße Restzeit",
    ["Background and red lines"] = "Hintergrund und rote Linien",
    ["Show the next effect"] = "Nächsten Effekt anzeigen",
    ["Profile changed. Use /reload when you are out of combat."] = "Profil gewechselt. Benutze /reload, sobald du aus dem Kampf bist.",
    ["Profile keybind"] = "Profil-Tastenbelegung",
    ["Switches to this profile outside combat and then asks to reload the UI. Override bindings are restored at login."] = "Wechselt außerhalb des Kampfes zu diesem Profil und fragt danach, ob die Oberfläche neu geladen werden soll. Die Belegungen werden beim Anmelden wiederhergestellt.",
    ["Use the global font"] = "Die global eingestellte Schrift",
    ["Name color"] = "Farbe des Namens",
    ["Timer color"] = "Farbe der Restzeit",
    ["|cffffffffINTERRUPTS|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffffUNTERBRECHEN|r\n|cffaaaaaaZiehen oder Pfeiltasten|r",
    ["Interrupt bar mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Press the button again to finish."] = "Regler für die Unterbrechen-Leiste aktiv. |cff9b6cffZiehe den lila Kasten|r oder benutze die |cff9b6cffPfeiltasten|r (UMSCHALT = 5 Pixel). Drücke den Knopf erneut, um fertig zu werden.",
    ["Interrupts"] = "Unterbrechen",
    ["Watches the combat log for enemy interrupts and starts a cooldown for each one, tracked per caster -- two enemies of the same class get an icon each. The border carries the caster's class colour."] = "Verfolgt im Kampfprotokoll die Unterbrechungen der Gegner und startet für jede eine Abklingzeit, getrennt nach Wirker – zwei Gegner derselben Klasse bekommen je ein Symbol. Der Rahmen trägt die Klassenfarbe des Wirkers.",
    ["Show interrupt bar"] = "Unterbrechen-Leiste anzeigen",
    ["Show interrupts that are still ready"] = "Auch einsatzbereite Unterbrechungen anzeigen",
    ["Timer text on the icons"] = "Restzeit auf den Symbolen",
    ["Cooldown swipe on the icons"] = "Abklingzeit-Wisch auf den Symbolen",
    ["Only take over the key while a fishing pole is worn"] = "Taste nur belegen, solange eine Angel angelegt ist",
    ["Without a pole in hand the key keeps whatever you bound it to, so it stays usable outside fishing. A cast already in the water keeps the key. This switches off auto-equipping a pole, which needs the key exactly while none is worn."] = "Ohne Angel in der Hand behält die Taste das, was du ihr zugewiesen hast – sie bleibt außerhalb des Angelns also normal nutzbar. Eine bereits ausgeworfene Schnur behält die Taste. Das schaltet das automatische Anlegen der Angel ab, denn das braucht die Taste genau dann, wenn keine angelegt ist.",
    ["Stand-in for an enemy frame: the side strip is placed by the settings below."] = "Platzhalter für ein Gegnerfenster: Der Symbolstreifen wird von den Einstellungen darunter gesetzt.",
    -- Patch notes 1.48.0
    ["Options Window"] = "Optionsfenster",
    ["Loss of Control – Shows the stun, fear, root, silence or lockout holding you, with its icon, its name and the time left"] = "Keine Kontrolle – Zeigt die Betäubung, Furcht, Wurzeln, Stille oder Zauberschulsperre, die dich hält, mit Symbol, Namen und Restzeit",
    ["Interrupts – Tracks enemy interrupts from the combat log, one icon per caster, bordered in the caster's class colour"] = "Unterbrechen – Verfolgt die Unterbrechungen der Gegner im Kampfprotokoll, ein Symbol je Wirker, umrandet in seiner Klassenfarbe",
    ["Timer Text On The Icons – Seconds left on the interrupt icons, with their own font, outline and colour"] = "Restzeit auf den Symbolen – Verbleibende Sekunden auf den Unterbrechen-Symbolen, mit eigener Schrift, Kontur und Farbe",
    ["Cooldown Swipe On The Icons – Drop the sweeping shade and keep only the number"] = "Abklingzeit-Wisch auf den Symbolen – Den wandernden Schatten weglassen und nur die Zahl behalten",
    ["The icon strip beside the enemy frames has a live preview on the General tab. Those frames exist only inside an arena, so its sliders used to move something you could not see."] = "Der Symbolstreifen neben den Gegnerfenstern hat im Reiter Allgemein eine Live-Vorschau. Diese Fenster gibt es nur in einer Arena, seine Regler verschoben also bisher etwas, das man nicht sehen konnte.",
    ["An unlocked mover box no longer vanished a moment after the button put it there. The box and a running preview now ignore the zone filter: you place a bar where you are standing, and that is rarely an arena."] = "Ein entsperrter Verschiebekasten verschwindet nicht mehr einen Augenblick, nachdem der Knopf ihn eingeblendet hat. Kasten und laufende Vorschau übergehen jetzt den Zonenfilter: Ausgerichtet wird da, wo man steht, und das ist selten eine Arena.",
    ["The pinned icon strip also appears on the Layout tab, where icon size, spacing, shape and zoom read back off it while the slider moves."] = "Der angepinnte Symbolstreifen erscheint jetzt auch im Reiter Layout, wo Symbolgröße, Abstand, Form und Zoom beim Ziehen des Reglers daran ablesbar sind.",
    ["Moving Blizzard frames no longer marks every Edit Mode window as touched by this addon, which had the pet frame refused in combat. Selecting a layout caused it, and that ran on every editor entry even when nothing had been placed."] = "Blizzard-Fenster zu verschieben markiert nicht mehr jedes Fenster des Bearbeitungsmodus als von diesem Addon angefasst, wodurch das Begleiterfenster im Kampf abgewiesen wurde. Ursache war das Auswählen eines Layouts, und das lief bei jedem Einstieg in den Editor, selbst wenn nie etwas platziert worden war.",
    ["The icon picker has a close button, and no longer floats over the game after the character sheet is shut."] = "Der Symbolwähler hat einen Schließen-Knopf und schwebt nicht mehr über dem Spiel, nachdem das Charakterfenster zu ist.",
    ["Only Take Over The Key While A Fishing Pole Is Worn – Without a pole the key keeps whatever you bound it to"] = "Taste nur belegen, solange eine Angel angelegt ist – Ohne Angel behält die Taste das, was du ihr zugewiesen hast",
    ["The mouse wheel scrolls the sidebar and the page. The window also shrinks to fit a screen smaller than itself, which is what left it undraggable on a high interface scale."] = "Das Mausrad rollt Seitenleiste und Seite. Das Fenster verkleinert sich außerdem auf einen Bildschirm, der kleiner ist als es selbst — genau das ließ es bei hoher Oberflächenskalierung unverschiebbar werden.",
    ["Profile Keybind – Put a profile on a key and switch to it out of combat"] = "Profil-Tastenbelegung – Ein Profil auf eine Taste legen und außerhalb des Kampfes dorthin wechseln",
    ["The bag sweep behind the food, flask and weapon oil reminders is kept until the bags change, instead of walking every bag three times over twice a second."] = "Der Taschendurchlauf hinter den Erinnerungen für Essen, Fläschchen und Waffenöl wird behalten, bis sich die Taschen ändern, statt zweimal pro Sekunde dreimal über alle Taschen zu laufen.",
    ["The modern player frame style no longer reaches into the pet and totem frames."] = "Der moderne Spielerfenster-Stil greift nicht mehr in das Begleiter- und das Totemfenster hinein.",
    ["Fine tuning for this slot"] = "Feineinstellungen für diesen Platz",
    ["Slot settings"] = "Platzeinstellungen",
    ["Border settings"] = "Rahmeneinstellungen",
    ["Border size"] = "Rahmengröße",
    ["How solid the empty part of the bar is."] = "Wie deckend der leere Teil der Leiste ist.",
    ["Absorb settings"] = "Absorptionseinstellungen",
    ["Border around the cast bar"] = "Rahmen um die Zauberleiste",
    ["Off leaves the cast bar without its own outline; the health bar keeps one."] = "Aus lässt die Zauberleiste ohne eigene Umrandung; die Lebensleiste behält ihre.",
    ["Top text"] = "Oberer Text",
    ["Left text"] = "Linker Text",
    ["Right text"] = "Rechter Text",
    ["Centred text"] = "Zentrierter Text",
    ["Unit name"] = "Einheitenname",
    ["Main text positions"] = "Haupt-Textpositionen",
    ["|cffaaaaaaOne thing per slot. The level rides at the name's left edge and follows it.|r"] = "|cffaaaaaaEins pro Platz. Die Stufe sitzt links am Namen und folgt ihm.|r",
    ["Health and cast bar"] = "Gesundheits- und Zauberleiste",
    ["Health bar width"] = "Breite der Lebensleiste",
    ["Health bar height"] = "Höhe der Lebensleiste",
    ["Cast icon"] = "Zaubersymbol",
    ["Cast icon settings"] = "Zaubersymbol-Einstellungen",
    ["Cast background"] = "Zauberhintergrund",
    ["Cast bar border"] = "Zauberleistenrahmen",
    ["Thickness of the cast bar's own border. 0 removes it; the health bar keeps its own."] = "Stärke des eigenen Rahmens der Zauberleiste. 0 entfernt ihn; die Lebensleiste behält ihren.",
    ["Cast bar border colour"] = "Farbe des Zauberleistenrahmens",
    ["Cast timer"] = "Zauberzeitmesser",
    ["Cast timer settings"] = "Zeitmesser-Einstellungen",
    ["Cast bar Y offset"] = "Zauberleiste Y-Versatz",
    ["Cast colours and effects"] = "Zauberfarben und Effekte",
    ["The bar's colour while a spell is being cast."] = "Die Farbe der Leiste, während ein Zauber gewirkt wird.",
    ["More cast colours"] = "Weitere Zauberfarben",
    ["Interrupt ready"] = "Unterbrechung bereit",
    ["Interrupt flash"] = "Unterbrechungsblitz",
    ["Interrupt-ready hint"] = "Hinweis: Unterbrechung bereit",
    ["Show cast bars in front of nameplates"] = "Zauberleisten vor Namensplaketten anzeigen",
    ["Casts draw above every plate, so a cast you care about is never hidden behind another unit's bar."] = "Zauber werden über allen Plaketten gezeichnet, damit ein wichtiger Zauber nie hinter der Leiste einer anderen Einheit verschwindet.",
    ["The enemy's cast bar flashes and reads 'Interrupted' for a moment when their cast is stopped."] = "Die Zauberleiste des Gegners blitzt auf und zeigt kurz „Unterbrochen“, wenn sein Zauber gestoppt wird.",
    ["Interrupt flash settings"] = "Einstellungen zum Unterbrechungsblitz",
    ["Target, focus and hover effects"] = "Ziel-, Fokus- und Hovereffekte",
    ["Target effect"] = "Zieleffekt",
    ["A coloured edge around the plate you have targeted."] = "Ein farbiger Rand um die Plakette, die du im Ziel hast.",
    ["Target effect settings"] = "Einstellungen zum Zieleffekt",
    ["Target arrows"] = "Zielpfeile",
    ["Arrow settings"] = "Pfeileinstellungen",
    ["Target bar colour on"] = "Zielfarbe aktivieren",
    ["Focus bar colour on"] = "Fokusfarbe aktivieren",
    ["A coloured edge around the plate you have set as your focus."] = "Ein farbiger Rand um die Plakette, die du als Fokus gesetzt hast.",
    ["Mouseover effect"] = "Mouseover-Effekt",
    ["Mouseover effect settings"] = "Einstellungen zum Mouseover-Effekt",
    ["General text"] = "Allgemeiner Text",
    ["Debuff duration"] = "Schwächungszauberdauer",
    ["Buff duration"] = "Stärkungszauberdauer",
    ["Crowd control duration"] = "CC-Dauer",
    ["Aura stacks"] = "Aurastapel",
    ["Timer text colour"] = "Farbe der Restzeit",
    ["Stack text colour"] = "Farbe der Stapelzahl",
    ["Text settings"] = "Texteinstellungen",
    ["Spell target"] = "Zauberziel",
    ["Background settings"] = "Hintergrund-Einstellungen",
    ["Hide the gryphons"] = "Greifen ausblenden",
    ["Removes the two beasts at the ends of Blizzard's main action bar. The bar itself stays."] = "Entfernt die beiden Wappentiere an den Enden der Standard-Aktionsleiste. Die Leiste selbst bleibt.",
    ["Extra indicators"] = "Weitere Anzeigen",
    ["Enemy colours"] = "Gegnerfarben",
    ["Enemy types"] = "Gegnertypen",
    ["The health bar colour a unit takes from its reaction to you."] = "Die Farbe, die eine Einheit aus ihrer Haltung zu dir bekommt.",
    ["Neutral enemies"] = "Neutrale Gegner",
    ["Units that are not hostile until you make them so."] = "Einheiten, die erst feindlich werden, wenn du sie dazu machst.",
    ["Other nameplates"] = "Andere Namensplaketten",
    ["Nameplate spacing"] = "Namensplaketten-Abstand",
    ["|cffaaaaaaThe game's own settings, changed live and not part of the profile — except the hitbox. Not changeable in combat.|r"] = "|cffaaaaaaDie spieleigenen Einstellungen, live geändert und nicht Teil des Profils — außer dem Trefferbereich. Im Kampf nicht änderbar.|r",
    ["Stackable nameplates"] = "Stapelbare Namensschilder",
    ["Extra aura options"] = "Extra-Aurenoptionen",
    ["Target and focus effects"] = "Ziel- und Fokuseffekte",
    ["Plate scale while casting"] = "Plakettengröße beim Zaubern",
    ["A casting unit's plate grows to this size, so the one that matters stands out. 100 = off."] = "Die Plakette einer zaubernden Einheit wächst auf diese Größe, damit die wichtige heraussticht. 100 = aus.",
    ["Opacity while casting"] = "Deckkraft beim Zaubern",
    ["A casting unit's plate is at least this opaque, even when something else is targeted."] = "Die Plakette einer zaubernden Einheit ist mindestens so deckend, auch wenn etwas anderes im Ziel ist.",
    ["The unit's name gives way to the spell name for as long as the cast runs."] = "Der Name der Einheit weicht für die Dauer des Zaubers dem Zaubernamen.",
    ["Active talent group"] = "Aktive Talentwahl",
    ["Left-click: show this talent group"] = "Klick: diese Talentwahl anzeigen",
    ["Right-click: activate this talent group"] = "Rechtsklick: diese Talentwahl aktivieren",
    ["Talent group %d (not active)"] = "Talentwahl %d (nicht aktiv)",
    ["Talents can only be learned in the active talent group."] = "Talente lassen sich nur in der aktiven Talentwahl lernen.",
    ["Talent groups cannot be switched in combat."] = "Im Kampf lässt sich die Talentwahl nicht wechseln.",
    ["This client refused to switch the talent group."] = "Der Client hat den Wechsel der Talentwahl abgelehnt.",
    ["Input line above the chat"] = "Eingabezeile über dem Chat",
    ["Puts the chat input line above the message area instead of below it. The panel and the tab bar follow it."] = "Setzt die Eingabezeile über den Nachrichtenbereich statt darunter. Das Panel und die Reiterleiste folgen ihr.",
    ["Own background for the input line"] = "Eigener Hintergrund für die Eingabezeile",
    ["Draws the input line on our own dark background instead of Blizzard's. The dark background panel already covers the input line, so this shows once that panel is off."] = "Zeichnet die Eingabezeile auf einen eigenen dunklen Hintergrund statt auf Blizzards. Das dunkle Hintergrundpanel deckt die Eingabezeile bereits ab, deshalb zeigt sich das erst, wenn dieses Panel aus ist.",
    ["Addon buttons"] = "Addon-Knöpfe",
    ["Click to show or hide the collected buttons."] = "Klick zeigt oder verbirgt die gesammelten Knöpfe.",
    ["Where other addons' minimap buttons sit: around the map, hidden until the mouse is over it, or gathered in one box under it."] = "Wo die Minikarten-Knöpfe anderer Addons sitzen: rund um die Karte, verborgen bis die Maus darüber liegt, oder gesammelt in einem Kasten darunter.",
    ["Around the minimap"] = "Rund um die Minikarte",
    ["Only on mouseover"] = "Nur bei Mauskontakt",
    ["Collected in a box"] = "Gesammelt in einem Kasten",
    -- Patch notes 1.49.0
    ["Hide The Gryphons – Takes the two beasts off the ends of Blizzard's main bar without dimming anything else"] = "Greifen ausblenden – Nimmt die beiden Tiere an den Enden von Blizzards Hauptleiste weg, ohne sonst etwas abzudunkeln",
    ["Switching the module off now switches it off. Its handlers are registered when the addon loads, so a module that was already off at login never ran its shutdown: being stunned in a battleground still popped the loss-of-control display, and the interrupt bar filled up and never emptied again, because the ticker that clears its icons only starts when the module is switched on."] = "Das Modul abzuschalten schaltet es jetzt wirklich ab. Seine Handler werden beim Laden angemeldet, ein Modul also, das beim Anmelden schon aus war, hat seine Abschaltung nie durchlaufen: im Schlachtfeld betäubt zu werden ließ die Anzeige für Keine Kontrolle trotzdem erscheinen, und die Unterbrechen-Leiste füllte sich und wurde nie wieder leer, weil der Ticker, der ihre Symbole abräumt, erst beim Einschalten anläuft.",
    ["The interrupt bar no longer reads the whole world's combat log. It registered on load and never unregistered, so every combat line anywhere — several thousand a second in a raid — was taken apart for a bar whose own default is arena and battlegrounds only. It uses the same zone filter as the display beside it now."] = "Die Unterbrechen-Leiste liest nicht mehr das Kampfprotokoll der ganzen Welt. Sie war beim Laden angemeldet und wurde nie abgemeldet, also wurde jede Kampfzeile überall — im Schlachtzug einige Tausend pro Sekunde — für eine Leiste zerlegt, deren eigene Vorgabe Arena und Schlachtfelder lautet. Sie benutzt jetzt denselben Zonenfilter wie die Anzeige daneben.",
    ["Switching the module on inside an arena counts as arriving. The zone decision used to live in the loading screen alone, so anyone who enabled it while already in there got no diminishing-returns ticker until the next one."] = "Das Modul in einer Arena einzuschalten zählt als Ankommen. Die Zonenentscheidung lag allein im Ladebildschirm, wer es also drinnen einschaltete, bekam bis zur nächsten Arena keinen Ticker für die abnehmende Wirkung.",
    ["The item level text size slider works again. It looked for the numbers in two places it hoped they would be, and where a client parents its paper doll buttons elsewhere it found none and quietly did nothing — which from the outside is indistinguishable from the text simply being too small."] = "Der Regler für die Größe der Gegenstandsstufen wirkt wieder. Er suchte die Zahlen an zwei Stellen, an denen er sie erhoffte, und wo ein Client seine Ausrüstungsknöpfe woanders einhängt, fand er keine und tat still gar nichts — von außen nicht zu unterscheiden davon, dass die Schrift einfach zu klein ist.",
    ["Input Line Above The Chat – Puts the input line over the message area instead of under it, with the panel and the tab bar following it; Wrath client only"] = "Eingabezeile über dem Chat – Setzt die Eingabezeile über den Nachrichtenbereich statt darunter, Panel und Reiterleiste folgen ihr; nur auf dem Wrath-Client",
    ["Own Background For The Input Line – Draws the input line on its own dark background instead of Blizzard's, which is what you saw once the dark panel was off; Wrath client only"] = "Eigener Hintergrund für die Eingabezeile – Zeichnet die Eingabezeile auf einen eigenen dunklen Hintergrund statt auf Blizzards, den du zu sehen bekamst, sobald das dunkle Panel aus war; nur auf dem Wrath-Client",
    ["Icon zoom is now called Icon crop and reads in percent. It is the same question the nameplate sliders ask, and it was answering in hundredths while they answered in percent."] = "Icon-Zoom heißt jetzt Icon-Zuschnitt und liest sich in Prozent. Es ist dieselbe Frage, die die Regler der Namensplaketten stellen, und sie wurde in Hundertsteln beantwortet, während jene in Prozent antworteten.",
    ["The extra width belongs to the friends tab alone now. The row texts there stretch with the window, but the column headers on the who, guild and raid tabs sit at fixed offsets and stay put, so every point of width you added landed in an empty right half. Those three tabs go back to Blizzard's own proportions, which is what their columns were measured for."] = "Die Zusatzbreite gehört jetzt der Freundesliste allein. Die Zeilentexte dort wachsen mit dem Fenster, aber die Spaltenköpfe der Register Wer, Gilde und Schlachtzug sitzen auf festen Abständen und bleiben stehen, jeder Punkt Breite landete dort also in einer leeren rechten Hälfte. Diese drei Register gelten wieder in Blizzards eigenen Proportionen, für die ihre Spalten ausgemessen wurden.",
    ["The set list and the icon picker take the character panel's style. In the classic style they used to be a flat dark surface with a purple edge holding Blizzard's red buttons — two materials in a hand's width. They now carry Blizzard's dialog frame there and stand in the same material as the window they hang off, while the modern style keeps the flat look."] = "Die Setliste und der Symbolwähler tragen den Stil des Charakterfensters. Im Classic-Stil waren sie eine flache dunkle Fläche mit lila Kante, in der Blizzards rote Knöpfe standen — zwei Materialien auf einer Handbreit. Sie nehmen dort jetzt Blizzards Dialograhmen und stehen im selben Material wie das Fenster, an dem sie hängen; der moderne Stil behält den flachen Anstrich.",
    ["The character panel no longer breaks when the sidebar builds its first set row. The marker bar on the row still reached for an accent colour that had been removed, so the list stayed empty and the panel came up bare."] = "Das Charakterfenster bricht nicht mehr ab, wenn die Seitenleiste ihre erste Setzeile baut. Der Markierungsbalken der Zeile griff noch auf eine Akzentfarbe zu, die entfernt worden war, die Liste blieb dadurch leer und das Fenster kam nackt hoch.",
    ["Addon Buttons – Choose where other addons' buttons sit: around the map, hidden until you mouse over it, or gathered in one box below it; Wrath client only"] = "Addon-Knöpfe – Wähle, wo die Knöpfe anderer Addons sitzen: rund um die Karte, verborgen bis die Maus darüber liegt, oder gesammelt in einem Kasten darunter; nur auf dem Wrath-Client",
    ["Icon Crop (%) – How much of the border the game bakes into its icons is cut away, set per aura row and for the cast bar icon"] = "Icon-Zuschnitt (%) – Wie viel von dem Rand, den das Spiel in seine Symbole einbackt, weggeschnitten wird, je Auren-Reihe und für das Symbol der Zauberleiste",
    ["The rounded bar style no longer leaves dead space at both ends. The round shape does not fill its own image — a transparent border runs all the way round it — and stretching that border across a wide, short bar put roughly eleven points of empty bar at each end and barely one above and below, which is why it showed up sideways and not upright."] = "Der runde Balkenstil lässt an beiden Enden keinen toten Streifen mehr. Die runde Form füllt ihr eigenes Bild nicht aus — ringsum läuft ein durchsichtiger Rand —, und diesen Rand über einen breiten, niedrigen Balken zu dehnen legte an jedem Ende rund elf Punkte leeren Balken und oben und unten knapp einen, weshalb es waagerecht auffiel und senkrecht nicht.",
    ["The options page is cut by question instead of by mechanism. Sixteen sections had settings that belong together lying far apart, with the bar texture under one heading and the cast bar's texture under another; eight settings were reachable from two sections at once."] = "Die Optionsseite ist nach Fragen geschnitten statt nach Mechanik. Sechzehn Abschnitte hatten zusammengehörige Einstellungen weit auseinander liegen, die Leistentextur unter der einen Überschrift und die Textur der Zauberleiste unter einer anderen; acht Einstellungen waren aus zwei Abschnitten zugleich erreichbar.",
    ["Every text on the plate sits in a slot now, the way the aura rows already did: top, left, right or centred, filled with the unit name or the health text. Four on/off switches became position pickers, each starting on the place its text already had."] = "Jeder Text auf der Plakette liegt jetzt in einem Platz, so wie die Auren-Reihen es schon taten: oben, links, rechts oder zentriert, gefüllt mit dem Einheitennamen oder dem Lebenstext. Vier Ein-Aus-Schalter sind zu Positionswählern geworden, jeder beginnt auf dem Platz, den sein Text ohnehin schon hatte.",
    ["The stacking dropdown had no readable value at all. It was reading a setting this client does not have; the one it does have is now read and written, measured in the running game."] = "Das Klappmenü für die Stapelung zeigte überhaupt keinen lesbaren Wert. Es las eine Einstellung, die dieser Client nicht hat; die, die er hat, wird jetzt gelesen und geschrieben, im laufenden Spiel gemessen.",
    ["A gear icon on a half-width row opens a small floating window instead of unfolding inside the cell. Half a cell has no room for a slider, and six of them had been squeezed into stubs."] = "Ein Zahnrad an einer halbbreiten Zeile öffnet ein kleines schwebendes Fenster, statt innerhalb der Zelle aufzuklappen. Eine halbe Zelle hat für einen Regler keine Breite, und sechs von ihnen waren dort zu Stummeln gequetscht.",
    ["Colour swatches, eyes, gears and arrows sit directly beside the control they belong to rather than in the icon strip on the right, which stays reserved for the gear and the info dot."] = "Farbfelder, Augen, Zahnräder und Pfeile sitzen direkt neben dem Bedienelement, zu dem sie gehören, statt im Symbolstreifen rechts, der dem Zahnrad und dem Info-Punkt vorbehalten bleibt.",
    ["On the Wrath client the module stands down completely and the client keeps its own window. Our restyle addresses Blizzard's widgets by name and by region number, and behind those names that client has a different anatomy: black holes where the hidden regions used to be, a stretched title bar, dropdowns over the recipe list — and no error, because nothing throws, it simply lands on the wrong widgets."] = "Auf dem Wrath-Client tritt das Modul ganz zurück und der Client behält sein eigenes Fenster. Unser Anstrich spricht Blizzards Bedienelemente über Namen und über Regionsnummern an, und hinter diesen Namen steht auf jenem Client eine andere Anatomie: schwarze Löcher dort, wo die versteckten Regionen saßen, eine gedehnte Titelleiste, Klappmenüs über der Rezeptliste — und kein Fehler, denn es wirft nichts, es landet nur auf den falschen Bedienelementen.",
    ["Talent group buttons run down the right edge, one for each group you have bought. Left-click shows a group, right-click activates it, the same split Blizzard's own window uses. Talents can only be learned in the active group, so a click in the preview does nothing and the tooltip says so beforehand."] = "Am rechten Rand laufen Knöpfe für die Talentwahlen entlang, einer je gekaufter Wahl. Linksklick zeigt eine Wahl an, Rechtsklick aktiviert sie, dieselbe Aufteilung, die Blizzards eigenes Fenster benutzt. Talente lassen sich nur in der aktiven Wahl lernen, ein Klick in der Vorschau tut deshalb nichts und der Kurztipp sagt es vorher.",
    ["The tab carries a book instead of a question mark. That mark is Blizzard's placeholder for a missing icon and read like a defect."] = "Der Reiter trägt ein Buch statt eines Fragezeichens. Dieses Zeichen ist Blizzards Platzhalter für ein fehlendes Symbol und las sich wie ein Defekt.",
    ["Glyphs"] = "Glyphen",
    ["CHARACTER"] = "Charakter",
    ["Packs the selected bar setup into a string you can pass on. Slots, macros and key bindings travel with it."] = "Packt das gewählte Leisten-Setup in eine Zeichenkette zum Weitergeben. Belegungen, Makros und Tastenbelegungen reisen mit.",
    ["Reads a bar setup string into your library. Putting it onto your bars stays a separate step."] = "Liest eine Leisten-Setup-Zeichenkette in deine Bibliothek. Es auf die Leisten zu legen bleibt ein eigener Schritt.",
    ["The bar setup string is damaged."] = "Die Leisten-Setup-Zeichenkette ist beschädigt.",
    ["This is not a bar setup string."] = "Das ist keine Leisten-Setup-Zeichenkette.",
    ["Bar setup '%s' imported."] = "Leisten-Setup '%s' eingelesen.",
    ["Macros left alone: the switch above is off."] = "Makros unangetastet: der Schalter oben ist aus.",
    ["Macros: %d restored, |cffff8800%d failed|r -- the macro list may be full."] = "Makros: %d wiederhergestellt, |cffff8800%d fehlgeschlagen|r -- die Makroliste ist womöglich voll.",
    ["Macros: %d restored."] = "Makros: %d wiederhergestellt.",
    ["Key bindings left alone: the switch above is off."] = "Tastenbelegungen unangetastet: der Schalter oben ist aus.",
    ["Key bindings: %d applied."] = "Tastenbelegungen: %d gesetzt.",
    ["Bar setup '%s' saved: %d slots, %d macros, %d key bindings."] = "Leisten-Setup '%s' gespeichert: %d Belegungen, %d Makros, %d Tastenbelegungen.",
    ["|cffff8800No key bindings were captured.|r This client may not report them."] = "|cffff8800Es wurden keine Tastenbelegungen erfasst.|r Dieser Client meldet sie möglicherweise nicht.",
    -- Patch notes 1.50.0
    ["Export as string – Packs the selected setup into a string you can pass on, with its slots, macros and key bindings"] = "Als String exportieren – Packt das gewählte Setup in eine Zeichenkette zum Weitergeben, mit Belegungen, Makros und Tastenbelegungen",
    ["Import from string – Reads someone else's setup into your library; a name you already use gets a number rather than being overwritten"] = "Aus String importieren – Liest das Setup eines anderen in deine Bibliothek; ein Name, den du schon benutzt, bekommt eine Nummer statt überschrieben zu werden",
    ["An imported setup is rebuilt entry by entry before it is stored. The restore walks every entry, so a malformed one would have thrown in the middle of a run with part of your bars already changed. Broken entries are dropped, the rest still arrives."] = "Ein eingelesenes Setup wird Eintrag für Eintrag neu aufgebaut, bevor es abgelegt wird. Der Wiederherstellungslauf greift auf jeden Eintrag zu, ein missgebildeter hätte also mitten im Lauf geworfen, mit einem Teil deiner Leisten bereits umgestellt. Kaputte Einträge fallen weg, der Rest kommt trotzdem an.",
    ["Saving and loading say what they did. Both had been counting their work all along and throwing the numbers away, so a setup whose macros all failed looked exactly like one that had none, and a save that captured no key bindings said nothing at all."] = "Speichern und Laden sagen, was sie getan haben. Beide hatten ihre Arbeit die ganze Zeit mitgezählt und die Zahlen weggeworfen: ein Setup, dessen Makros samt und sonders scheiterten, sah aus wie eines ohne Makros, und ein Speichern ohne erfasste Tastenbelegungen sagte gar nichts.",
    ["The character window can be placed by hand on the Wrath client. Blizzard's editor does not own that window, so it takes the same direct route the loot window already uses; one box moves the character, reputation and skills tabs together, and the stats panel and set list travel with it."] = "Das Charakterfenster lässt sich auf dem Wrath-Client von Hand platzieren. Blizzards Editor besitzt dieses Fenster nicht, also nimmt es denselben direkten Weg wie das Beutefenster; ein Kasten bewegt Charakter, Ruf und Fertigkeiten gemeinsam, und Werte-Panel und Setliste reisen mit.",
    ["The window starts wide on the Wrath client. The slider has always gone to 400 — it simply started at nothing, so the extra room only ever reached whoever went looking for it."] = "Das Fenster startet auf dem Wrath-Client breit. Der Regler ging schon immer bis 400 — er begann nur bei nichts, der zusätzliche Platz erreichte also nur den, der ihn suchen ging.",
    ["The glyph page opens from a button under the talent group buttons, and it is dark now. The rune circle is dimmed rather than removed, because it is what makes that page recognisable; the sockets take the accent colour, and the glyph artwork and the pickup highlight stay as they are."] = "Die Glyphenseite öffnet über einen Knopf unter den Talentwahl-Knöpfen, und sie ist jetzt dunkel. Der Runenkreis wird abgedunkelt statt entfernt, denn an ihm erkennt man die Seite; die Fassungen nehmen die Akzentfarbe, und die Glyphengrafik und die Aufnahme-Hervorhebung bleiben, wie sie sind.",
    ["The talent group button shows its tree's icon instead of a question mark. It asked for that icon through an interface that does not answer on every client, and fell back to the placeholder; the answer is now worked out from the ranks themselves, which cannot be misread."] = "Der Talentwahl-Knopf zeigt das Symbol seines Baums statt eines Fragezeichens. Er fragte danach über eine Schnittstelle, die nicht auf jedem Client antwortet, und fiel auf den Platzhalter zurück; die Antwort wird jetzt aus den Rängen selbst ermittelt, und die sind nicht misslesbar.",
    ["The level number on the player frame sits where the client puts it on the Wrath client. Our two anchors are measured against one frame sheet, and where a different one ships, the number landed beside the portrait — the client keeps that anchor itself there anyway, moving it as the rest and PvP icons come and go."] = "Die Stufenzahl am Spielerfenster sitzt auf dem Wrath-Client dort, wo der Client sie hinlegt. Unsere zwei Anker sind gegen ein Rahmenblatt ausgemessen, und wo ein anderes ausgeliefert wird, landete die Zahl neben dem Portrait — der Client pflegt diesen Anker dort ohnehin selbst und verschiebt ihn, wie Ruhe- und PvP-Symbol kommen und gehen.",
    -- Patch notes 1.51.0
    ["Socket strip under the window – A row of every socket on your equipped gear, hung under the character window; click a socket to put a gem from your bags into it"] = "Sockelleiste unter dem Fenster – Eine Reihe mit jedem Sockel deiner angelegten Ausrüstung, unter dem Charakterfenster; ein Klick auf einen Sockel setzt einen Stein aus deinen Taschen ein",
    ["The enchant text on armour slots reads the enchant again instead of the item's difficulty tag. The filter took the first green line of the tooltip, and where an item carries a tag that tag stands above the enchant — so every such slot showed the tag, while a weapon two rows down showed its enchant correctly because nothing stood in front of it. The tag and the client's bracketed hints are both recognised now, in every language rather than only in English and German."] = "Der Verzauberungstext an den Rüstungsplätzen zeigt wieder die Verzauberung statt der Schwierigkeitsmarke des Gegenstands. Der Filter nahm die erste grüne Zeile des Tooltips, und wo ein Gegenstand eine Marke trägt, steht sie über der Verzauberung — also zeigte jeder solche Platz die Marke, während eine Waffe zwei Reihen tiefer ihre Verzauberung richtig zeigte, weil dort nichts davorstand. Marke und die geklammerten Bedienhinweise des Clients werden jetzt beide erkannt, und zwar in jeder Sprache statt nur auf Englisch und Deutsch.",
    ["The set list no longer casts a shadow past its own frame. What looked like the background standing out over the border was a drop shadow: not an outline but four filled rectangles reaching up to seven pixels beyond the frame on every side, and behind Blizzard's dialog frame there was nothing for it to fall on. It is gone in both looks."] = "Die Set-Liste wirft keinen Schatten mehr über ihren eigenen Rahmen hinaus. Was wie ein überstehender Hintergrund aussah, war ein Schlagschatten: kein Umriss, sondern vier gefüllte Rechtecke, die auf jeder Seite bis zu sieben Pixel über den Rahmen hinausreichten — und hinter Blizzards Dialograhmen gab es nichts, worauf er fallen konnte. Er ist in beiden Looks weg.",
    ["In the Classic+ look the dark ground stopped short of the ornate line instead of ending on it, and so showed past the frame on every side."] = "Im Classic+-Look endete der dunkle Grund vor der Zierlinie statt auf ihr und stand deshalb auf jeder Seite über den Rahmen hinaus.",
    -- Patch notes 1.52.0
    ["The own background for the input line is offered on every client. It was limited to one client generation, and the code already said it would work everywhere."] = "Der eigene Hintergrund für die Eingabezeile wird auf allen Clients angeboten. Er war auf eine Client-Generation begrenzt, und im Code stand bereits, dass er überall laufen würde.",
    ["The icon borders are pixel-exact. The border there is not a texture of its own but the rim of a plate behind the icon, so the two have to sit on the same pixel grid, the thickness has to be counted in pixels rather than frame units, and the icon size and spacing have to begin on whole pixels. None of the three was true, which is why a rim came out two pixels on one edge and none on the opposite."] = "Die Symbolränder sind pixelgenau. Der Rand ist dort keine eigene Textur, sondern der Saum einer Platte hinter dem Symbol — beide müssen also auf demselben Pixelraster liegen, die Stärke muss in Pixeln statt in Rahmeneinheiten gerechnet sein, und Größe wie Abstand müssen auf ganzen Pixeln beginnen. Keines der drei traf zu, weshalb ein Saum an einer Kante zwei Pixel breit war und an der gegenüberliegenden gar nicht.",
    ["Apply this arrangement – Puts the unit name and the health value inside the bar, crowd control left of it, incoming debuffs above that and buffs to its right, with the cast bar carrying its icon, its remaining time and its target"] = "Diese Anordnung anwenden – Setzt Einheitennamen und Lebenswert in die Leiste, Kontrolle links davon, eingehende Schwächungen darüber und Stärkungen rechts, und die Zauberleiste trägt Symbol, Restzeit und Ziel",
    ["The unit name was hidden behind the health bar fill as soon as a text slot put it inside the bar. The name and the health value hang from different parents: the value is created on the bar, the name on the plate, and the bar is a child of the plate — so it draws over anything the plate draws. While the name only ever sat above the bar this never showed. It has its own layer now, above the bar but not attached to it, because name-only mode hides that bar and a text parented to a hidden frame would go with it."] = "Der Einheitenname stand hinter der Leistenfüllung, sobald ein Textplatz ihn in die Leiste legte. Name und Lebenswert hängen an verschiedenen Eltern: der Wert wird auf der Leiste erzeugt, der Name auf der Plakette, und die Leiste ist ein Kind der Plakette — sie zeichnet also über allem, was die Plakette zeichnet. Solange der Name nur oberhalb stand, fiel das nie auf. Er hat jetzt eine eigene Ebene über der Leiste, ohne an ihr zu hängen, denn der Nur-Name-Modus blendet diese Leiste aus, und ein Text an einem versteckten Rahmen ginge mit.",
    ["The health text has its controls back: what it shows, and which mark goes between the two numbers. Both were still being read and had been unreachable since the page was rebuilt."] = "Der Lebenstext hat seine Bedienung zurück: was er zeigt, und welches Zeichen zwischen den beiden Zahlen steht. Beides wurde weiterhin gelesen und war seit dem Umbau der Seite durch nichts mehr erreichbar.",
    ["The active talent group was always reported as the first one on clients that do not carry the newer interface for it. Everything behind that believed group one was running: the header called the group you were standing in not active, the activate button offered to switch to the one already on, and the switch reported success while changing nothing. Five files ask that same question, so profile overrides and bar setups were reading it too."] = "Die aktive Talentwahl wurde auf Clients ohne die neuere Schnittstelle dafür immer als die erste gemeldet. Alles dahinter glaubte, Wahl eins laufe: der Kopf nannte die Wahl, in der man stand, nicht aktiv, der Aktivieren-Knopf bot an, auf die schon laufende zu schalten, und der Wechsel meldete Erfolg, ohne etwas zu ändern. Fünf Dateien stellen dieselbe Frage, also lasen auch Profil-Übersteuerungen und Leisten-Setups davon.",
    ["The glyph page stands permanently beside the window. It is lifted out of Blizzard's talent frame, where it lives inside the scroll area of the very window we replace, and handed back when ours closes."] = "Die Glyphenseite steht dauerhaft neben dem Fenster. Sie wird aus Blizzards Talentfenster herausgehoben, wo sie im Rollbereich genau des Fensters liegt, das wir ersetzen, und beim Schließen unseres wieder zurückgegeben.",
    ["The separate glyph button is gone with it. Its only job was to send you to the page that now stands in front of you."] = "Der eigene Glyphen-Knopf ist damit verschwunden. Seine einzige Aufgabe war, dich zu der Seite zu schicken, die jetzt vor dir steht.",
    ["A band under the header carries the activate button and the name of the talent group on screen. Until now switching existed only as a right-click on the small side icons, and nothing announced it."] = "Ein Band unter dem Kopf trägt den Aktivieren-Knopf und den Namen der gezeigten Talentwahl. Bisher gab es das Umschalten nur als Rechtsklick auf die kleinen Symbole an der Seite, und nichts kündigte es an.",
    ["Form paging"] = "Seitenwechsel durch Gestalten",
    ["Keep the main bar on its page in every form"] = "Aktionsleiste 1 behält ihre Seite in jeder Gestalt",
    ["|cffaaaaaaCat, bear, stealth, stances and Shadowform normally swap the main bar to their own page. Switch this off to keep the bar you built through every form.|r"] = "|cffaaaaaaKatze, Bär, Schleichen, Haltungen und Schattengestalt wechseln die Hauptleiste normalerweise auf ihre eigene Seite. Schalte das ab, damit deine Leiste in jeder Gestalt stehen bleibt.|r",
    -- Patch notes 1.52.1
    ["Keep the main bar on its page in every form – Cat, bear, stealth, stances and Shadowform stop swapping action bar 1 to a page of their own"] = "Aktionsleiste 1 behält ihre Seite in jeder Gestalt – Katze, Bär, Schleichen, Haltungen und Schattengestalt schieben Aktionsleiste 1 nicht mehr auf eine eigene Seite",
    ["The ticker that paints cooldown dimming and range colouring no longer walks switched-off bars. It read and repainted every action bar five times a second, including the ones whose buttons nobody can see, so running two bars cost as much as running all of them."] = "Der Ticker, der die Abklingzeit-Abdunklung und die Reichweitenfärbung zeichnet, läuft nicht mehr über abgeschaltete Leisten. Er las und färbte jede Aktionsleiste fünfmal je Sekunde, auch die, deren Knöpfe niemand sieht — zwei Leisten kosteten damit so viel wie alle zusammen.",
    ["Leaving a button no longer builds a fresh check each time. The check only ever reads the bar, not the button, so it is built once per bar and shared by all of its buttons."] = "Das Verlassen eines Knopfes baut nicht mehr jedes Mal eine frische Prüfung. Die Prüfung liest ohnehin nur die Leiste und nicht den Knopf, also wird sie einmal je Leiste gebaut und von allen ihren Knöpfen geteilt.",
    ["The opponent frames are left alone unless you actually asked for a different arrangement. They are protected frames: anchoring one from our side is allowed outside a fight, but it marks the frame for the rest of the session, and the next time the default interface repositions it during a round its own call is refused and the block is reported against us. There is no way to anchor a protected frame without leaving that mark, so an untouched setup now keeps the default stacking. Order, spacing, grow direction and slot offsets all still work — the message becomes the price of a feature you asked for rather than something every arena hands out for free."] = "Die Gegnerrahmen bleiben unangetastet, solange du keine andere Anordnung verlangt hast. Es sind geschützte Rahmen: sie außerhalb eines Kampfes zu verankern ist erlaubt, markiert den Rahmen aber für den Rest der Sitzung, und wenn die Standard-Oberfläche ihn mitten in einer Runde selbst umsetzt, wird ihr eigener Aufruf abgelehnt und der Block uns angelastet. Einen geschützten Rahmen ohne diese Markierung zu verankern geht nicht, also behält eine unveränderte Anordnung jetzt die Standard-Stapelung. Reihenfolge, Abstand, Wuchsrichtung und Slot-Versätze wirken weiterhin — die Meldung wird zum Preis einer Funktion, die du bestellt hast, statt zu etwas, das jede Arena umsonst verteilt.",
    ["Move up and move down work again on a category you switched off and back on. The order list was filled once, while it was still empty, so anything that did not exist at that moment never got an entry, and its arrows then did nothing at all for the rest of the session without saying so."] = "Nach oben und nach unten wirken wieder bei einer Kategorie, die du ab- und wieder eingeschaltet hast. Die Reihenfolgeliste wurde einmal gefüllt, solange sie noch leer war; was in diesem Moment nicht existierte, bekam nie einen Eintrag, und seine Pfeile taten danach den Rest der Sitzung gar nichts, ohne es zu sagen.",
    ["Switching a module off releases its event handlers again. The note recording which module owns a handler stayed behind when the handler was unregistered, and that note kept a hard reference to every handler the module had ever registered."] = "Ein abgeschaltetes Modul gibt seine Ereignis-Handler wieder frei. Der Vermerk, welchem Modul ein Handler gehört, blieb beim Abmelden stehen, und dieser Vermerk hielt eine harte Referenz auf jeden Handler, den das Modul je registriert hatte.",
    -- Patch notes 1.52.2
    ["Casting out of the spell book keeps working after the book was opened from the micro menu. Our micro buttons are stand-ins that hand the click on to the default button behind them, which runs everything that follows inside our own call — and for the spell book that ends in the book writing down which half of itself it is showing. That note then counted as ours, the book reads it on every click on a spell, and so every cast from the book was refused as coming from an addon. Out of combat as well, for the rest of the session, until the interface was reloaded. Opening the book by its key was never affected. The micro menu now carries the default button itself, wearing our icon, so nothing is handed through us any more."] = "Aus dem Zauberbuch lässt sich wieder wirken, auch wenn das Buch über das Mikromenü geöffnet wurde. Unsere Mikroknöpfe sind Attrappen, die den Klick an den Standardknopf dahinter weiterreichen — damit läuft alles Folgende innerhalb unseres eigenen Aufrufs, und beim Zauberbuch endet das darin, dass das Buch notiert, welche Hälfte von sich es gerade zeigt. Diese Notiz galt dann als unsere, das Buch liest sie bei jedem Klick auf einen Zauber, und so wurde jedes Wirken aus dem Buch als Aufruf eines Addons abgelehnt. Auch außerhalb des Kampfes, für den Rest der Sitzung, bis die Oberfläche neu geladen wurde. Über seine Taste geöffnet war das Buch nie betroffen. Das Mikromenü trägt jetzt den Standardknopf selbst, mit unserem Symbol, sodass nichts mehr durch uns hindurchgereicht wird.",
    ["Pointing at a bag slot shows the tooltip of the bag itself — quality colour, how much it holds, everything the item carries — with the click hints under it, instead of the bare name. In the inventory window as well as at the bank, which had drifted apart although the two bars are the same thing."] = "Beim Zeigen auf ein Taschensymbol erscheint der Tooltip der Tasche selbst — Qualitätsfarbe, Fassungsvermögen, alles was der Gegenstand mitbringt — mit den Klick-Hinweisen darunter statt nur des nackten Namens. Im Inventarfenster ebenso wie an der Bank, die auseinandergelaufen waren, obwohl die beiden Leisten dasselbe sind.",
    ["The bar in the inventory window takes bags now, the way the one at the bank already did: drag a bag onto a slot to put it there, or left-click a slot with a bag on the cursor. Right-click with an empty hand takes the bag off again, and left-click with an empty hand still shows and hides it. The backpack and the keyring are not slotted bags, so they accept nothing and are not offered the right-click line in the first place."] = "Die Leiste im Inventarfenster nimmt jetzt Taschen an, so wie die an der Bank es schon tat: eine Tasche auf ein Symbol ziehen legt sie in diesen Platz, ein Linksklick mit einer Tasche am Zeiger tut dasselbe. Ein Rechtsklick mit leerer Hand nimmt die Tasche wieder ab, ein Linksklick mit leerer Hand blendet sie weiterhin ein und aus. Rucksack und Schlüsselbund sind keine angelegten Taschen, sie nehmen nichts an und bekommen die Rechtsklick-Zeile gar nicht erst angeboten.",
    ["The enchant on the wrist slot sits closer to the rows around it, and the enchant on the weapon sits six pixels lower."] = "Der Verzauberungstext am Handgelenks-Platz sitzt näher an den Zeilen um ihn herum, der an der Waffe sechs Pixel tiefer.",
    ["The trainer tab is a button of its own now. It used to be a spare tab of the spell book that we wrote on with every update, and the book reads those tabs back in the middle of its own pass. It also goes away with the pet book, where it used to stay behind."] = "Der Trainer-Reiter ist jetzt ein eigener Knopf. Vorher war es ein freier Reiter des Zauberbuchs, den wir bei jedem Update beschrieben haben, und das Buch liest diese Reiter mitten in seinem eigenen Durchlauf zurück. Außerdem verschwindet er mit dem Tierbuch, wo er vorher stehen blieb.",
} end)
